  str_monster_name_2902701_en = "Forsakin",
  str_monster_name_2000271_en = "Lumo Ranger",
  str_monster_desc_2900063 = "Se dice que es miembro de la misteriosa organización Eclipse. No solo tiene ataques poderosos, sino que también puede comandar a los Eclipsites.",
  str_monster_desc_2900141 = "Un miembro de la misteriosa organización Eclipse, ella y su hermana Shire conforman las Gemelas Víbora. Hará lo que sea necesario para lograr su objetivo.",
  str_monster_desc_2900181 = "Un miembro de la misteriosa organización Eclipse, ella y su hermana Shelt conforman las Gemelas Víbora. Impulsiva, mata a los enemigos con brutalidad y crueldad.",
  str_monster_desc_2900201 = "Se dice que es miembro de la misteriosa organización Eclipse. No solo tiene ataques poderosos, sino que también puede comandar a los Eclipsites.",
  str_monster_desc_2900211 = "Violento y gigantesco, es un poderoso Eclipsite que parece soportar un sufrimiento sin fin. Es mejor mantenerse alejado de él.",
  str_monster_desc_2900221 = "Una fusión de Shelt y Shire. Sufriendo de un dolor increíble, tiene un fuerte deseo de venganza, lo que lo convierte en un Eclipsite brutal y poderoso.",
  str_monster_desc_2900231 = "La criatura que guarda el Colossus Mantiz que posee una misteriosa tecnología antigua. Ten cuidado con eso.",
  str_monster_desc_2900232 = "La criatura que guarda el Colossus Mantiz que posee una misteriosa tecnología antigua. Ten cuidado con eso.",
  str_monster_desc_2900241 = "Su fuerza destructiva es suficiente para destruir todo un ejército. Se dice que es un subordinado leal de un miembro de la organización Eclipse.",
  str_monster_desc_2900251 = "Extremadamente ágil, puede compararse con un fantasma que va y viene sin dejar un solo rastro, y es poco probable que los medios ordinarios lo dañen. También conocido como Cazador de Almas.",
  str_monster_desc_2000011 = "Con habilidades de lucha que superan con creces las de Dretchers, es la principal unidad de combate de los Eclipsites. También se les conoce como Capitanes y a menudo se les ve comandando Dretchers.",
  str_monster_desc_2000071 = "Un Eclipsite gigantesco responsable de la destrucción de varias fortificaciones y es conocido como Demoledor.",
  str_monster_desc_2000101 = "Responsable de investigar los movimientos Aurorians y también conocido como Scout. Por lo general, ataca a los Aurorians con otros Eclipsites.",
  str_monster_desc_2000111 = "Sirviente del Ojo Malvado con una fuerte habilidad de ATQ y RES, a veces se encuentran ayudando a los Dretchers.",
  str_monster_desc_2000121 = "Un Eclipsite especializado en detectar movimientos Aurorians. También conocido como vidente, a veces puede detectar a grandes distancias.",
  str_monster_desc_2000131 = "Un ejército de criaturas reptilianas grises responsables de varias tareas básicas de combate, también conocidas como los Cleaners.",
  str_monster_desc_2000141 = "Una criatura pequeña que lleva una caja negra que transporta los suministros de la organización Eclipse, también conocida como Corredor.",
  str_monster_desc_2000151 = "Los luchadores de los Eclipsites. Son poderosos en combate y pueden comandar a los Eclipsites, también conocidos como Oficiales.",
  str_monster_desc_2000161 = "Tiene una gran capacidad de camuflaje. A menudo se infiltran en reuniones de Aurorian para asesinar y, por lo tanto, se les conoce como Asesinos.",
  str_monster_desc_2000171 = "Uno de los \"Eclipsites Materializados\". Por lo general, tiene la forma de una cuenta negra y lo carga una Sombra u otros Eclipsites. A menudo se lanza en momentos críticos de batallas para pelear.",
  str_monster_desc_2000181 = "Uno de los \"Eclipsites Materializados\". Por lo general, tiene la forma de una cuenta negra y lo carga una Sombra u otros Eclipsites. A menudo se lanza en momentos críticos de batallas para pelear.",
  str_monster_desc_2000211 = "No son aptos para la batalla, pero restauran PS de otros Eclipsites. Se dice que han evolucionado de Geist Sombrío, a veces se les conoce como Sanadores.",
  str_monster_desc_2000221 = "No son aptos para la batalla, pero pueden hacer que emerjan picos del suelo, el techo y otras paredes de roca para atacar a los transeúntes. A veces se los conoce como Spikers.",
  str_monster_desc_4000221 = "Sin poder de combate.",
  str_monster_desc_2000231 = "Sus pies pueden absorber el Lumina circundante, volviéndose extremadamente poderosos. Se dice que evolucionaron de Necrófagos Sombríos y también se les conoce como \"Ingestores de Energía\".",
  str_monster_desc_2000241 = "Una élite del Ojo Malvado que tiene fuertes habilidades de observación, lo que dificulta que los Aurorians no sean detectados También conocidos como Buscadores.",
  str_monster_desc_2000251 = "Los miembros más jóvenes que forman la base del poderío militar de Lumopolis son numerosos y muy activos en las Patrullas.",
  str_monster_desc_2000261 = "Ellos soportan la carga de proteger la ciudad las veinticuatro horas del día sin una sola queja. Sin descansar nunca, se les considera la columna vertebral de la Guardia.",
  str_monster_desc_2000271 = "Son guardias que también sirven como exploradores Después de someterse a entrenamientos especiales, poseen una movilidad, destreza y agilidad extremadamente altas.",
  str_monster_desc_2000281 = "Guardias armados con un escudo de defensa superior. Con la capacidad de soportar duras batallas, son los fuertes muros que protegen a sus camaradas.",
  str_monster_desc_2000291 = "Vagabundos que se sometieron a entrenamiento de combate. Su impactante carga los hace imparables en el campo de batalla.",
  str_monster_desc_2000293 = "Vagabundos que se sometieron a entrenamiento de combate. Su impactante carga los hace imparables en el campo de batalla.",
  str_monster_desc_2000301 = "Eclipsites Blindados de Noche Blanca, Vientre Negro. Anteriormente eran viciosos, pero después de ser capturados, se han convertido en una fuente de entretenimiento.",
  str_monster_desc_2000302 = "La versión mejorada de Eclipsites Blindados. Aunque sus armaduras son más hermosas, no pueden escapar al destino de ser una fuente de entretenimiento para los demás.",
  str_monster_desc_2000311 = "Le gusta luchar contra los Aurorians con sus espadas dobles y es muy hábil. Sin embargo, rara vez funciona con otros Eclipsites y también se le conoce como espadachín.",
  str_monster_desc_2000321 = "Evolucionado a partir de un insecto que se movía rápido antes de la guerra, se mueve rápidamente y es muy difícil de tratar. También se llama Chaser.",
  str_monster_desc_2000341 = "Saqueadores profesionales que se ganan la vida robando a civilizaciones antiguas. Dado que toda su energía se usa para robar, sus habilidades de combate son muy bajas y solo escaparán al encontrarse con un enemigo.",
  str_monster_desc_2000351 = "Se dice que es una versión más débil del Triturador. Se cree que es un Triturador gravemente herido que evolucionó después de ser tratado.",
  str_monster_desc_2000411 = "Condicionados por fuertes enerías, algunos de los Eclipsites de Ojo Malvado han sufrido extrañas mutaciones.",
  str_monster_desc_2000421 = "Se dice que es una mutación de Shadow Eclipsite, puede aumentar el ATK de otros Eclipsites.",
  str_monster_desc_2000431 = "Un. Eclipsite especial creado por los antepasados de los gusanos de arena. Su Darkflow es muy inestable y explota al morir.",
  str_monster_desc_2000441 = "Algunos Eclipsites se vieron afectados por una fuerte energía y evolucionaron mucho, lo que les proporcionó una alta resistencia hacia un elemento en particular.",
  str_monster_desc_2000442 = "Este tipo de eclipse ha acumulado tanta energía elemental que puede afectar el elemento de su entorno circundante.",
  str_monster_desc_2000451 = "Los soldados de Lumopolis que fueron engañados por Gertzurde perdieron la capacidad de pensar y atacar después de ser controlados por los Eclipsites. Marcharían a la batalla bajo las órdenes de Gertzurde.",
  str_monster_desc_2000401 = "Un Eclipsite de bajo nivel que tiene cero inteligencia. Sólo puede obedecer las órdenes de su invocador y resistir los ataques de ellos.",
  str_monster_desc_2000491 = "Réplica creada por los Eclipsites de alto nivel que posee habilidades especiales. Se ve idéntico a su maestro, al punto de causar un caos considerable entre las filas enemigas.",
  str_monster_desc_2000501 = "Estos Eclipsites tienen un gancho especialpara atraer objetivos para ataques grupales, así que ten cuidado.",
  str_monster_desc_2000511 = "Este tipo de Eclipsites posee un cristal gris que emite un rayo único que a su vez interrumpe el flujo Lumina del objetivo, haciéndolo muy difícil de controlar.",
  str_monster_desc_2000521 = "Los mutantes aparecen después de que algunos Eclipsites devoren los cadáveres de otros Eclipsites. Pueden liberar un campo de fuerza especial que bloquea Lumina y hace que sea imposible fluir.",
  str_monster_desc_2000531 = "Eclipsites de Sonda Mutada; se dice que ha mutado una capacidad de visión de largo alcance con un método poderoso y preciso de un ataque de largo alcance.",
  str_monster_desc_2000541 = "Eclipsites Belicistas Mutados. No solo tienen un mayor poder de combate, sino también la habilidad especial de erosionar Lumina.",
  str_monster_desc_2000551 = "Un nuevo tipo de Eclipsite que apareció en el Territorio Secreto. Se dice que nacieron de los resentimiento de una antigua raza que fue exterminada por los Eclipsites. Esta es la única manera de explicar el origen de la poderosa habilidad de maldición que han dominado.",
  str_monster_desc_2000561 = "Eclipsites Raros. Parecen Fantas. flotan., se mueven rápido, y, bás., no pueden ser golpe. También conocido como fantasmas.",
  str_monster_desc_2000571 = "Test. de la explo. de energía de Schummer Blanco. Estos Eclipsites espe. se forman a partir de la mezcla de su mal. y odio. Incapaz de mov., su aura oscura cubre el cielo, lo suf. como para poseer una pod. hab. para maldecir.",
  str_monster_desc_2000581 = "Se dice que es una variante del Abismo, un Eclipsite de bajo nivel. Acude a la llamada de una Eclipsite de alto nivel y puede autodestruirse con gran fuerza. La única forma de evitarlo es eliminarlo antes de que explote.",
  str_monster_desc_2000601 = "Un Eclipsite especial que era pequeño y apenas visible a simple vista. Su cuerpo se ha hinchado a su tamaño actual debido al efecto de fuertes emociones negativas.",
  str_monster_desc_2000602 = "Una ilusión creada por Luminatics de Dawn que contiene un poder mágico.",
  str_monster_desc_2000611 = "A special Eclipsite that was small and barely visible to the naked eye. Its body has swelled to its current size due to the effect of strong negative emotions.",
  str_monster_desc_2000701 = "Estos Eclipsites especiales han despertado de un profundo sueño. Son grandes en número, pero sus tácticas son bastante simples. ¡Pero ten cuidado, ya que tienen la capacidad de transformarse!",
  str_monster_desc_2000702 = "Un castillo roto enterrado en el fondo del mar. Cada vez que suena su campana, el Monarca Desolado desata su ira sobre sus enemigos.",
  str_monster_desc_2000703 = "Este caballo de guerra era un mero cadáver antes de que el Monarca Desolado lo despertara. Conservando la fuerza y ​​la lealtad de su pasado, ataca a todos los enemigos de su amo sin dudarlo.",
  str_monster_desc_2000704 = "Originalmente ayudantes del rey, pueden percibir pasajes en el vacío que otros no pueden, y luego se mueven rápidamente para atacar.",
  str_monster_desc_2000705 = "Originalmente una noble venganza la llevó a venir a este mar, donde revivió al legendario rey antiguo. Sin embargo, las fuerzas oscuras a las que llamó también devoraron su alma, convirtiéndola en una Eclipsite.",
  str_monster_desc_2000711 = "Estos peones perdidos han ganado el poder del vacío. Aunque sus tácticas siguen siendo simples, su efectividad en el combate se ha incrementado significativamente. No se pueden subestimar.",
  str_monster_desc_2000712 = "Un castillo que aplasta a todos, su campana se convierte en la peor pesadilla de cualquier enemigo.",
  str_monster_desc_2000713 = "Con un relincho aterrador y unos cascos que sacuden la tierra, cuando estos feroces jinetes entran en acción, lo único que puede detenerlos es la muerte.",
  str_monster_desc_2000714 = "Palabras de crueldad y corrupción rodean... Cuidado con los ataques desde los lados.",
  str_monster_desc_2000715 = "Caroline... Loca por el poder, se ha convertido en una con el vacío, ganando un poder incalculable.",
  str_monster_desc_2000901 = "Se rumora que el Eclipse ha creado este nuevo tipo de Eclipsite. Ellos se autodestruyen para destruir el terreno a su alrededor y romper la defensiva del ejército Aurorian.",
  str_monster_desc_2001001 = "Un Eclipsite que una vez habitó en las profundidades del Territorio Secreto, sobresale en lanzar ataques desde el subsuelo. También se dice que puede cavar pasajes subterráneos para otras Eclipsites.",
  str_monster_desc_2001301 = "El polvo se ha asentado y la identidad de un enemigo familiar pero extraño está a punto de ser revelada. Es hora de demostrar tu determinación.",
  str_monster_desc_2101301 = "Minions of Eclipsites, convocados por Eclipsites de alto nivel.",
  str_monster_desc_4001301 = "Minions of Eclipsites, convocados por Eclipsites de alto nivel.",
  str_monster_desc_2001401 = "Los tentáculos simbióticos de un Kittypus transfieren cualquier daño entrante directamente a su anfitrión.",
  str_monster_desc_2900271 = "Este tipo de Eclipsite ha sufrido una extraña mutación. Se dice que su poder de combate es comparable al de los Eclipsites de alto nivel. Es el jefe de todos los Eclipsites blindados y tiene un PS muy alto.",
  str_monster_desc_2900262 = "Un Aurorian corroído por poder. fuerzas oscuras. Ha perdido toda su timidez y es extremadamente peligroso.",
  str_monster_desc_2900263 = "En el pasado, Eve se volvió loca por el \"tratamiento\" de la misteriosa mujer que la hizo perder el control de su poder y la quema de \"esa\" Subciudad. La rabia y la culpa están destro. su corazón mientras la tragedia se repite una y otra vez... Calma su ira ahora.",
  str_monster_desc_2900264 = "Una chica miste. que encon. en Red-Eye Gorge. Ella \"ordenó\" a los Eclipsites que se llevaran a Eve con un propósito desconocido.",
  str_monster_desc_2900281 = "Un tipo de Eclipsite que tiene poca inteli. y no tiene volun. propia. Su propósito es desc., y uno solo puede adivinar que está asociado con la Crisis de Darkover. También conocido como Darkover Omen.",
  str_monster_desc_2900391 = "Aunque se mueve lentam. tiene una fuerte DEF y también puede lanzar bombas Abisales con poderes abrumadores. También conocido como Transpor.",
  str_monster_desc_2900401 = "Originalmente un Celestita, pero se unió a Eclipse y posee un enorme poder aumentado.",
  str_monster_desc_2900402 = "Originalmente un Celestita, pero se unió a Eclipse y posee un enorme poder aumentado.",
  str_monster_desc_2900403 = "Originalmente un Celestita, pero se unió a Eclipse y posee un enorme poder aumentado.",
  str_monster_desc_2900411 = "Orig. miembro de los Guardianes de Lumopolis. Ganó a Shelt, estaba disp. a destruir Lumopolis por ellos.",
  str_monster_desc_2900421 = "Despues de que Nozard fue derrotado, su cuerpo fue recuperado por una organización desconocida y transformado experimentalmente en un monstruo aterrador.",
  str_monster_desc_2900422 = "Un gran eclipse que se asemeja a un dragón gigantesco, al acecho en Blazing Tooth Canyon.",
  str_monster_desc_2900431 = "Un antiguo gusano de arena gigante que ha ocupado el sitio desde que fue destruído. Recientemente, después de despertar de su largo letargo, comenzó a atacar a todos los intrusos invasores.",
  str_monster_desc_2900441 = "El Eclipse transf. a Umbrahulk, haciéndolo más poderoso. Desde entonces, el Eclipse le ha encargado explorar los restos de la Cumbre y hacer frente a diversas contingencias.",
  str_monster_desc_2900451 = "Orig. un mons. parecido a un fant., comen. a evol. debido al poder de la Luz después de entrar en la tierra. Puede crear varias ilus. con luz refractada en el campo de batalla.",
  str_monster_desc_2900452 = "Un portal creado por Eclipsite Phorosion. Se usa para escon. y emboscar cuando detecta la deb. de un enemigo.",
  str_monster_desc_2900501 = "Evol. a partir del Siphorb, absorbió tanto Lumina que es incapaz de controlar el color de la luz circundante. También puede usar su maná para adsorber a los Aurorians cercanos y atacarlo.",
  str_monster_desc_2900601 = "Mutantes creados después de que el Solmorfo de la organización Eclipse absorbiera el poder de la Cumbre. Pueden lanzar de pronto la Lumina que absorbieron para dar un gran golpe mortal.",
  str_monster_desc_2900611 = "Mutantes creados por la Organización Eclipse utilizando los restos de Eclipsites de alto nivel como Fantasmas. Tienen una capacidad de división más poderosa y solo pueden ser destruídos derrotándolos a él y a todos sus clones.",
  str_monster_desc_2900641 = "Varias Caracalitas se combinaron y mutaron en un Eclipsite de alto nivel cuyo dominio del Eclipsium es aún más poderoso. Con su técnica especial para encerrar Lumina, es extremadamente difícil de manejar.",
  str_monster_desc_2900651 = "Se dice que cuando el gen de Tabaad fue inyectado en un poderoso Eclipsite, emerge un Eclipsite de alto nivel similar a Tabaad con habilidades más poderosas y una obediencia incondicional.",
  str_monster_desc_2900661 = "Otro juguete nuevo de Forsakin. En contraste con el Aburrimiento anterior, posee una técnica aterradora que puede erosionar a Lumina además de su gran poder. Nunca debe tomarse a la ligera.",
  str_monster_desc_2900671 = "Después de que las semillas dentro de su cuerpo lograran un crecimiento parasitario, su forma que absorbió grandes cantidades de energía se ha vuelto completamente diferente al pasado. Incluso su aparencia ha cambiado sutilmente.",
  str_monster_desc_2900681 = "Eclipsites de Parpadeo mutados. Extrem. ágil, puede compararse con un fantasma que va y viene sin dejar un solo rastro, y es poco probable que los medios ordinarios lo dañen.",
  str_monster_desc_2900701 = "Robot dejado por una civil. antigua. Con un diseño único, puede seguir funcio. incluso si está parcial. destruído. Es extrem. difícil de manejar.",
  str_monster_desc_2900711 = "Robot apareció después de la división de T-1024. Primero encontrará otros T-256 e intentará formar otro T-1024.",
  str_monster_desc_2910711 = "Un robot funcional con orígenes desconocidos. Sus capacidades ofensivas no deben subestimarse.",
  str_monster_desc_29107141 = "\"¡Bip! ¡Bip!\"",
  str_monster_desc_29107111 = "\"¡Bip! ¡Bzz!\"",
  str_monster_desc_2800241 = "\"¿Qué estás mirando? No esperes encontrar ninguna información sobre mí desde aquí. Ni los Aurorians ni los Celestitas pueden entender el nivel MÁS ALTO de una persecución...\"",
  str_monster_desc_2900801 = "Un antiguo rey que estuvo en las prof. del océano durante eones. Despertado por la Reina Engañosa, ha prometido atrapar a sus enemigos en el vacío por siempre.",
  str_monster_desc_2900811 = "El enfurecido rey antiguo controla y juega con todos y cada uno de los intrusos hasta que la muerte finalmente los reclama.",
  str_monster_desc_2900911 = "Se rumora que son Eclipsites de alto nivel que anteriormente participaron en varias batallas feroces. Desconocidos en número y poseedores de la rara habilidad de volar, ahora han despertado de su sueño y están listos para sumergir a los Aurorians en una pesadilla.",
  str_monster_desc_2900912 = "Este Eclipsite sigue a Hylingerr y puede ayudarlo en la batalla.",
  str_monster_desc_2901001 = "Originalmente un noble de Lumopolis, después de ser desterrado de la ciudad, su resentimiento por su antigua nación se agudizó, hasta el punto en que desertó al Eclipse e intentó derrocar el liderazgo de Lumopolis. Cuando su plan falló, se hundió aún más en la locura, su odio creciente alimentaba su poder ...",
  str_monster_desc_2901101 = "Incapaz de superar su miedo y desesperado por realizar su ambición, sufre una peligrosa transformación temporal sin pensarlo dos veces, transformándose en esta aterradora criatura.",
  str_monster_desc_2901201 = "Un héroe ancestral que se convirtió en Eclipsite para luchar contra ellos. Ahora es un monstruo sin sentido.",
  str_monster_desc_2901300 = "Eclipsite enigmático de origen desconocido, cuya presencia no parece ajustarse a la realidad que conoces.",
  str_monster_desc_2901301 = "El polvo se ha asentado y la identidad de un enemigo familiar pero extraño está a punto de ser revelada. Es hora de demostrar tu determinación.",
  str_monster_desc_2901401 = "Una compañera especial de Gretel. Generalmente tranquilo y plácido, pero se sabe que se vuelve loco en la batalla. Aproximación con precaución.",
  str_monster_desc_2901501 = "Una compañera especial de Gretel. Juguetón y enérgico, disfruta especialmente luchando contra un grupo de enemigos.",
  str_monster_desc_2901601 = "Una compañera especial de Gretel. Tiene un par de patas extremadamente fuertes que pueden repeler a cualquier enemigo.",
  str_monster_desc_2901701 = "Una compañera especial de Gretel. Se parece a un gato con muchas patas... Es lindo, pero algo inquietante.",
  str_monster_desc_2901801 = "Los residentes de la Ciudad Perdida, cuyas identidades siguen siendo un misterio, parecen considerarse dueños de este lugar.",
  str_monster_desc_2901901 = "Exjefe de los Wisp que se dedica a luchar contra los invasores de Cloud Island.",
  str_monster_desc_2901911 = "La frenética Nagi atacará a cualquiera que perciba como un intruso.",
  str_monster_desc_2902001 = "Un tirano que vino de otra isla del Lejano Oriente para gobernar Cloud Island, y hará cualquier cosa para declarar su soberanía sobre ella.",
  str_monster_desc_2902101 = "Debido a su obsesión, se convirtió en un hombre horrible y prometió eliminar a todos los que se resistieran.",
  str_monster_desc_2902201 = "Un poderoso Eclipsite que vivió solo en las ruinas durante muchos años. Completamente loco, ataca a todos los forasteros.",
  str_monster_desc_2902202 = "Un ex soldado de Illumina que se convirtió en un Eclipsite bajo la influencia de Darkflow. El odio consumió toda su cordura y le robó toda su antigua gloria.",
  str_monster_desc_2902301 = "La IA en la base subterránea de Eraveil que ha estado protegiendo la base durante miles de años y es responsable de eliminar a todos los enemigos invasores.",
  str_monster_desc_2902401 = "La IA en la base subterránea de Eraveil que parece grande y pesada, es Claudiaamigo de",
  str_monster_desc_2902501 = "El mayordomo de la medalla de oro de Andersen que no deja manchas, basura o alimañas desatendidas.",
  str_monster_desc_2902601 = "Se dice que es el PhantomEl \"hermano\" de Eternal Night. Es capaz de usar diferentes tácticas según la hora del día y es extremadamente difícil de manejar.",
  str_monster_desc_2902701 = "\"¿Qué estás mirando? No esperes encontrar ninguna información sobre mí desde aquí. Ni los Aurorians ni los Celestitas pueden entender el nivel MÁS ALTO de una persecución...\"",
  str_monster_ability_2900063 = "Ataca objetivos frontales con sus garras gigantes. Puede volar y bombardear zonas específicas en el suelo.",
  str_monster_ability_2900141 = "Experta en ataques cuerpo a cuerpo, sus ataques aturdirán al objetivo. Cuando está en modo Rabiosa, sus ataques normales se convierten en ataques dobles, con un rango de habilidad mejorado, y puede invocar a Geist Sombrío y Necrófago Sombrío al mismo tiempo.",
  str_monster_ability_2900142 = "Sobresaliente en el combate cuerpo a cuerpo, sus ataques son capaces de aturdir a los objetivos. Tiene la capacidad de convocar a otros Eclipsites. Mientras está en modo Rabid, restaura el 20% de su salud máxima; después de que finaliza el modo Rabid, sus ataques normales pueden golpear dos veces y su rango de habilidad aumenta considerablemente.",
  str_monster_ability_2900181 = "Experta en ataques a distancia que aturdirán al objetivo e invocarán al Geist Sombrío. Cuando está en modo Rabiosa, sus ataques normales golpean dos veces, con un rango de habilidad mejorado. Puede invocar a Geist Sombrío y Necrófago Sombrío al mismo tiempo.",
  str_monster_ability_2900182 = "Sobresaliente en el combate de largo alcance, sus ataques son capaces de derribar objetivos. Tiene la capacidad de convocar a otros Eclipsites. Mientras está en modo Rabid, restaura el 20% de su salud máxima; después de que finaliza el modo Rabid, sus ataques normales pueden golpear dos veces y su rango de habilidad aumenta considerablemente.",
  str_monster_ability_2900201 = "Es bueno usando su gran cuerpo para atacar a los objetivos que tiene enfrente. Se hunde en el suelo y daña a los objetivos cercanos al emerger.",
  str_monster_ability_2900211 = "Su ataque cuerpo a cuerpo también retrocede, y tiene la capacidad de invocar Piedras para atacar. Los objetivos impactados serán retrocedidos y esas áreas generarán nuevas piedritas. También puede lanzar un ataque a pantalla completa, y el daño infligido está determinado por la cantidad de Piedras.",
  str_monster_ability_2900221 = "Su ataque también retrocede. Puede convertir el área de combate en Lumina de su propio elemento y desatar una amplia gama de ataques basicos en su propio elemento: Fuego - Daño de área grande con efectos de Quemadura; Trueno - Daño de pantalla completa con Plaga de Picos aleatoria.",
  str_monster_ability_2900231 = "El ataq. cuer. a cuer. de Philex viene con un retro., y su habilidad de ATQ atur. a los obj.",
  str_monster_ability_2900232 = "Vani puede usar energía para atacar a distancia y recuperar PS para Philex.",
  str_monster_ability_2900241 = "Lanza rondas incendiarias en la zona de batalla, haciendo que las unidades que pasen sean infligidas con Quemadura. Puede cargar contra un objetivo y aturdirlo, usando el aura de la espada para atacar dos filas de objetivos frente a él.",
  str_monster_ability_2900251 = "Real. un ataq. de área en forma de cruz y convo. a un clon para que luche junto a él. Después de la clonación, absorberá el PS del clon anterior para restaurarlo a sí mismo. Cuando su PS es inferior al 50%, sus ataq. normales se conver. en ataques dobles; Los ataques de área se conver. en ataq. de pant. completa.",
  str_monster_ability_2000011 = "La principal unidad de combate de Eclipsites, experta en combate cuerpo a cuerpo con garras.",
  str_monster_ability_2000071 = "Un Eclipsite de gran tamaño responsable de la destrucción de varias fortificaciones y es más que capaz de derribar edificios.",
  str_monster_ability_2000101 = "Un explorador de Eclipsites que puede usar la luz emitida por su boca para atacar a los enemigos desde la distancia.",
  str_monster_ability_2000111 = "Más conocido por su uso de barreras para resistir ataques.",
  str_monster_ability_2000121 = "Un Eclipsite con habilidades de invocación de bajo nivel. Incapaz de moverse solo y lucha invocando a Dretcher.",
  str_monster_ability_20001211 = "Un Eclipsite con hab. de invocación de bajo nivel. Incapaz de moverse por su cuenta y lucha convocando a Eclipsites.",
  str_monster_ability_20001221 = "Un Eclipsite con habilidades de invocación de bajo nivel. Incapaz de moverse solo y lucha invocando Sabuesos de Hechizos.",
  str_monster_ability_20001231 = "Un Eclipsite con habilidades de invocación de bajo nivel. Incapaz de moverse por sí solo y lucha invocando a Darkwasp.",
  str_monster_ability_20001241 = "Un Eclipsite con habilidades de invocación de bajo nivel. Incapaz de moverse por sí solo y lucha invocando Dreadblades.",
  str_monster_ability_20001251 = "Un Eclipsite con habilidades de invocación de bajo nivel. Incapaz de moverse por sí solo y lucha invocando Slashers.",
  str_monster_ability_20001261 = "Un Eclipsite con habilidades básicas de invocación. Incapaz de moverse por sí solo y lucha invocando a Prober.",
  str_monster_ability_2000131 = "Un Eclipsite de bajo nivel, solo es capaz de ataques básicos basados en el instinto.",
  str_monster_ability_2000141 = "Un Eclipsite con ATQ promedio que es responsable de recolectar suministros.",
  str_monster_ability_2000151 = "Experto en usar sus dos enormes puños para pelear. Su habilidad Golpe de Martillo inflige daño terrestre y Aturdir a los objetivos.",
  str_monster_ability_2000161 = "Usa su lanza para atacar al objetivo y gana la habilidad de convocar a Geist Sombrío.",
  str_monster_ability_2000171 = "Eclipsite Materializado de Tipo II: Eclipsites Sanadores. Por lo general, tiene la forma de una cuenta negra y es capaz de curar otros Eclipsites cuando se libera.",
  str_monster_ability_2000181 = "Eclipsite Materializado de Tipo I: Eclipsites a Distancia. Por lo general, tiene la forma de cuenta negra. Participa en la batalla cuando se libera, pero su poder de combate es relativamente débil.",
  str_monster_ability_2000211 = "Un Eclipsite con la cap. de curar, prin. responsable de restaurar PS de otros Eclipsites.",
  str_monster_ability_2000221 = "Inadecuado para la batalla, pero puede hacer que surjan picos del suelo para atacar a los transeúntes.",
  str_monster_ability_4000221 = "Normalmente, los monstruos de este tipo usan púas en el suelo para atacar a los transeúntes. Pero la habilidad de este en particular parece ser diferente de alguna manera.",
  str_monster_ability_2000231 = "Una gama de Eclipsite cuya principal habilidad de combate es fortalecerse al absorber Lumina. Es experto en ataques a larga distancia y, aunque su poder de batalla original es deficiente, después de absorber Lumina, su poder de batalla mejora significativamente.",
  str_monster_ability_2000241 = "Un Eclipsite con habilidades de invocación intermedias. Incapaz de moverse por sí solo, lucha invocando Probador. que poseen habilidades de ataque a distancia.",
  str_monster_ability_20002411 = "Un Eclipsite con poderosas hab. de invocación. Puede convocar a varios tipos de Eclipsites para luchar.",
  str_monster_ability_20002421 = "Un Eclipsite con habilidades de invocación intermedias. Lucha invocando Espadas Aterradoras que poseen poderosas habilidades cuerpo a cuerpo.",
  str_monster_ability_20002422 = "Un Eclipsite con habilidades de invocación intermedias. Lucha invocando Espadas Aterradoras que poseen poderosas habilidades cuerpo a cuerpo y Sabuesos de Hechizos con increíbles capacidades defensivas.",
  str_monster_ability_20002423 = "Un Eclipsite con habilidades de invocación intermedias. Lucha invocando Dreadblades que poseen poderosas habilidades cuerpo a cuerpo y Vinesmark que lanza ataques mortales a distancia.",
  str_monster_ability_2000251 = "Miembros jóvenes de la base militar de Lumopolis. En gran número, su modo de combate principal es el uso de armas equipadas para ataques de largo alcance.",
  str_monster_ability_2000261 = "Guardias mecánicos Lumopolis. Cuando se encuentran con enemigos, luchan creando soldados de espada larga.",
  str_monster_ability_2000271 = "Explo. de élite de Lumopolis que se moverán instan. a otra ubicación desp. de atacar a su obj. Su mov. y destreza los convierten en un obj. difícil de alcan. en el combate reg.",
  str_monster_ability_2000281 = "Guardias arm. con escudos con DEF sup. El esc. en sus brazos sirve no solo como medio de def., sino tam. como arma cuerpo a cuerpo.",
  str_monster_ability_2000291 = "Vagab. que se somet. a entren. de combate. Tienen una fuerte vol. de luchar y poseen fuertes hab. cuerpo a cuerpo.",
  str_monster_ability_2000293 = "Vagab. que se somet. a entren. de combate. Tienen una fuerte vol. de luchar y poseen fuertes hab. cuerpo a cuerpo.",
  str_monster_ability_2000301 = "Eclipsites port. normales. Norm. transporta envíos ligeros de Nightium. Derrótalos para conseguir el dinero.",
  str_monster_ability_2000302 = "Eclipsites port. mejorados. Norm. transp. grandes envíos de Nightium. Derrótalos para conseguir el dinero.",
  str_monster_ability_2000311 = "Un Eclipsite de recién aparición que puede haber evolucionado a partir de otros Eclipsites. Es bueno con espadas doble y lanza ataques dobles sobre su objetivo cuando se enfrentan.",
  str_monster_ability_2000321 = "Un Eclipsite de tipo insecto de movimiento rápido, al que se le ha ordenado perseguir y cazar a sus objetivos de cerca.",
  str_monster_ability_2000341 = "Una gran cantidad de bandidos que saben escapar.",
  str_monster_ability_2000351 = "Un poderoso Eclipsite que puede derribar objetivos con sus ataques.",
  str_monster_ability_2000411 = "Un Eclipsite mutante que se especializa en ataques a distancia. Cuando su elemento es Fuego, puede convocar Lluvia Ardiente para quemar a los objetivos que son golpeados. Cuando su elemento es Trueno, puede convocar Poder del Rayo para paralizar a los objetivos golpeados.",
  str_monster_ability_2000421 = "Especialista en ataques a distancia y otorga beneficios a los Eclipsites cercanos en batalla.",
  str_monster_ability_2000431 = "Especialista en combate cuerpo a cuerpo. Cuando está a punto de murir, se moverá hacia los jugadores y se detonará, causando daño a todos los objetivos circundantes.",
  str_monster_ability_2000441 = "Ataca al objetivo con ataques cuerpo a cuerpo. Los efectos de los ataques de Aurorian que no contrarresten su elemento se reducirán considerablemente.",
  str_monster_ability_2000442 = "Lanza ataques cuerpo a cuerpo contra su objetivo y convierte todas las fichas a lo largo de su ruta de movimiento en fichas del mismo elemento que él.",
  str_monster_ability_2000451 = "Inflige efec. neg. a sus enemigos.",
  str_monster_ability_2000501 = "Puede atraer obj. dist. hacia sí mismo e infligir un gran daño a los obj. dentro de 1 cúmulo circun.",
  str_monster_ability_2000511 = "Su rango de ataque es muy pequeño. Sin embargo, su ataque hace que un Aurorian pierda energía, aumentando el número de rondas de enfriamiento de la Habilidad Activa.",
  str_monster_ability_2000521 = "Puede bloquear elementos de casillas. Al golpear un objetivo, los elementos de las casillas alrededor del objetivo se bloquearán. Después de moverse, bloquea los elementos de casillas alrededor de sí mismo.",
  str_monster_ability_2000531 = "Eclipses que son extremadamente buenos para atacar desde la distancia. Cuanto más lejos esté el objetivo atacado de Vinesmark, más daño recibirá.",
  str_monster_ability_2000541 = "Los poderosos ataques de Doomskull pueden aplastar mosaicos dentro de un rango de área grande.",
  str_monster_ability_2000551 = "Eclipsites raros con la capacidad de maldecir. Lanzará una maldición sobre el objetivo. El Aurorian maldito no puede usar Habilidades Activas, moverse o ser elegido Capitán durante varias rondas.",
  str_monster_ability_2000561 = "Un cazador de largo alcance que cambia su posición antes de atacar en cada ronda.",
  str_monster_ability_2000571 = "Dem. control. por Schummer. Interv. con el desp. Aurorian. Si la Hora de Aurora no se puede activar en varias rondas, los Aurorians se sumer. en la oscuridad.",
  str_monster_ability_2000581 = "Eclipsite invocado por Sin forma, este monstruo descerebrado lanza ataques suicidas contra sus enemigos. Explota si no es destruido en un determinado número de rondas, destruyendo su ubicación actual.",
  str_monster_ability_2000582 = "Un Eclipsite convocado por Formless, este monstruo sin sentido lanza ataques suicidas contra sus enemigos. Explota si no se destruye dentro de un cierto número de rondas, invocando un Área de alarma.",
  str_monster_ability_2000601 = "Un Eclipsite sin hab. de combate, pero puede unirse a un Eclipsite dentro de 1 cúmulo circun. de sí mismo. Desp. de adherirse, prop. al Eclipsite un escudo y mej. sus ataques.",
  str_monster_ability_2000602 = "Esto se une a Dawn y recu. su PS cuando está dentro de 1 cúmulo circun. de Dawn.",
  str_monster_ability_2000611 = "Un Eclipsite sin capacidad de combate, pero puede unirse a un Aurorian dentro de 1 grupo circundante de sí mismo. Una vez conectado, seguirá reduciendo el valor de cordura del auroriano.",
  str_monster_ability_2000701 = "Después de moverse, inflige daño a los enemigos en 4 casillas en forma de cruz a su alrededor. Al llegar al borde del Alchemy Board, serán promovidos a Torre Enfurecida, Caballero Caído, Alfil Eclipse o Reina Engañosa, según su orden de llegada.",
  str_monster_ability_2000702 = "Solo puede moverse horizontal o verticalmente desde su propia posición. Después de moverse, inflige daño a los objetivos dentro de 1 cúmulo circundante. Al chocar contra un objetivo mientras se mueve, infligirá un daño mayor a este objetivo y lo empujará hacia el borde del tablero.",
  str_monster_ability_2000703 = "Solo puede saltar en diagonal. Después de aterrizar, inflige daño a los enemigos en las 4 casillas circundantes en forma de cruz. Si hay un objetivo en su punto de aterrizaje, inflige un daño severo al objetivo y lo aturde, mientras lo derriba.",
  str_monster_ability_2000704 = "Solo se mueve en diagonal. Inflige daño a objetivos dentro de su rango máximo en forma de cruz.",
  str_monster_ability_2000705 = "Inflige daño equivalente a un porcentaje de los PS máximos del objetivo a los blancos dentro de su rango de forma radial.",
  str_monster_ability_2000711 = "Después de moverse, inflige daño a los enemigos en 4 fichas en forma de cruz alrededor. Al llegar al borde del Alchemy Board, serán promovidos a Torre Enfurecida - RAM, Caballero Caído - CHARGE, Eclipse Bishop - EX, o Reina Engañosa, según su orden de llegada.",
  str_monster_ability_2000712 = "Solo puede moverse horizontal o verticalmente desde su propia posición. Después de moverse, inflige daño a los objetivos dentro de 2 cúmulos circundantes. Al chocar contra un objetivo mientras se mueve, infligirá un daño mayor a este objetivo y lo empujará hacia el borde del tablero.",
  str_monster_ability_2000713 = "Solo puede saltar en diagonal. Después de aterrizar, inflige daño a 1 cúmulo circundante. Si hay un objetivo en su punto de aterrizaje, inflige un daño severo y lo aturde, mientras lo derriba.",
  str_monster_ability_2000714 = "Solo mueve en diagonal. Inflige daño a los objetos dentro de su rango máximo en forma de cruz y reduce su DEF.",
  str_monster_ability_2000715 = "Inflige daño equivalente a un porcentaje del PS máximo del objetivo a los blancos dentro de su rango máximo de forma radial. Si no hay objetivos en las 8 direcciones a su alrededor, gana una barrera defensiva.",
  str_monster_ability_2000901 = "Se autodestruye después de la cuenta regresiva hasta cero, destruyendo el mosaico en su ubicación actual y dejándolo inutilizable.",
  str_monster_ability_2001001 = "Sobresale en la utilización de terrenos destrozados y posee la capacidad de infligir un gran daño a las unidades que se encuentran alrededor de las casillas rotas.\nCuando los Aurorians atraviesan casillas rotas, su contador de combo no aumentará.",
  str_monster_ability_2001301 = "Con gran habilidad de ATQ y normalmente escondido en el campo de batalla. No puede ser atacado a menos que se revele durante la Hora de Aurora.",
  str_monster_ability_2001341 = "Inflige mucho daño y es invencible en casillas verdes.",
  str_monster_ability_2101301 = "Eclipsite Minion no ataca y normalmente está oculto en el campo de batalla. No puede ser atacado a menos que se revele durante Aurora Time.",
  str_monster_ability_4001301 = "Hace mucho daño.",
  str_monster_ability_2001401 = "Sensible y dócil, esquivará los ataques aurorianos a toda costa.",
  str_monster_ability_2900271 = "Un Eclipsite blindado avan. que puede usar hab. de rango de pantalla completa.",
  str_monster_ability_2900262 = "Incapaz de moverse por sí solo, pero tiene un amplio rango de ataque. Puede absorber la materia oscura y convertirla en una barrera. También puede atacar y derribar a tres filas de enemigos frente a él.",
  str_monster_ability_2900263 = "Incapaz de moverse por sí solo, pero tiene un amplio rango de ataque. Puede absorber la materia oscura y convertirla en una barrera. También puede atacar y derribar a tres filas de enemigos frente a él.",
  str_monster_ability_2900264 = "Inflige daño a los enem. dentro de 2 cúmulos circun. y a los enem. en la pant. completa. Puede transformarse en Dawn Sprite para recuperar su PS.",
  str_monster_ability_2900281 = "Puede convo. una faro y rest. el PS de la faro mien. obtiene una reduc. de daño según la cant. de faros a su alrededor. Sus hab. tienen un Ataque a dist. en forma de cruz y el daño y el alc. de su hab. cargable se basan en la cantidad de bal.",
  str_monster_ability_2900391 = "No puede mov. por sí solo y solo es vuln. al Daño de Bomba. Puede convo. bombas y, una vez que esté comp. cargado, invocará bombas de forma cont. y lanzará una Habilidad de Daño de área amplia.",
  str_monster_ability_2900401 = "Resistente a los ataques físicos y puede resistir el daño de Ataques Normales. Inflige daño a los objetivos avanzados y puede lanzar ataques a pantalla completa. Capaz de invocar Cristales de Relámpago.",
  str_monster_ability_2900402 = "Resistente al daño de Ataque Normal. Inflige daño a los objetivos en un rango en forma de cruz o en pantalla completa, invocando rayos en áreas específicas periódicamente. Inflige daño continuo en toda la pantalla después de volverse rabioso.",
  str_monster_ability_2900403 = "Es buena en ataques a distancia y AOE, y puede sincronizar su PS. El PS de la Schummer más herida se sincronizará con el PS de la Schummer más sana en el campo de batalla, hasta un 30% por regeneración.",
  str_monster_ability_2900411 = "Invoca refuerzos en batalla. El rango de ataque ahora es todo el campo y los ataques agregarán un debilitamiento a los enemigos golpeados que reduce su defensa. Los ataques normales enfurecidos golpearán dos veces.",
  str_monster_ability_2900421 = "Puede atacar áreas especificas e invocar Sabueso de hechizos como apoyo, infligiendo daño a los objetivos en el frente o en toda la pantalla.",
  str_monster_ability_2900422 = "Inflige daño a los objetivos que se encuentran frente a él o en toda la pantalla y repele a las unidades enemigas. Capaz de invocar Spikepests.",
  str_monster_ability_2900431 = "Es bueno usando su gran cuerpo para atacar objetivos en el frente. Se hunde en el suelo y daña a los objetivos cercanos al emerger. También puede invocar Bichos de explosión.",
  str_monster_ability_2900441 = "Su ataque normal viene con un retroceso, y puede convocar un cristal duplicado para crear 1 piedrita elemental por ronda. Puede consumir todas los piedritas para lanzar un ataque al objetivo, cuyo daño está determinado por la cantidad de Piedritas.",
  str_monster_ability_2900451 = "Se escon. en el Lumiwall más ale. del jug.; Los ataq. pueden cambiar el elem. de la cas. en su ruta de ataque.",
  str_monster_ability_2920451 = "Crea ilusiones alrededor de los objetivos después de embestirlos. Cada Lumiwall reduce el daño recibido por el Phorosion, así como su ATK; mientras están Despertados, los Lumiwalls crean aún más ilusiones en cada ronda.",
  str_monster_ability_2900452 = "Se escon. en el Lumiwall más ale. del jug.; Los ataq. pueden cambiar el elem. de la cas. en su ruta de ataque.",
  str_monster_ability_2900501 = "Posee la cap. de cambiar el color del cas. del Alchemy Board. Los obj. alcanzados por su habilidad serán atraídos hacia él.",
  str_monster_ability_2900601 = "Experto en atacar a distancia. Puede jalar objetivos distantes hacia sí, cambiar elementos de las casillas de enemigos golpeados y las de un gran rango a su alrededor.",
  str_monster_ability_2900611 = "No puede moverse, pero es hábil en ataques cruzados y a distancia; los ataques harán que los Aurorians pierdan energía, lo que a su vez aumenta el nº de rondas de enfriamiento de las Habilidades Activas; se dividirá cuando muera.",
  str_monster_ability_2900641 = "Hábil en ataques a distancia. Bloquea los elementos de las casillas a su alrededor después de moverse, y es capaz de contraatacar, bloqueando los elementos de las casillas en 1 cúmulo circundante alrededor de Aurorians, cada vez que usan una Habilidad Activa.",
  str_monster_ability_2900651 = "Hábil en a distancia; los ataques de alcance ultra grande causan más daño a los objetivos más lejanos; puede convocar a Vinesmarks en busca de apoyo.",
  str_monster_ability_2900661 = "Shatterblast aplastará todas las casillas del campo. Este ataque puede hacer retroceder al objetivo. Puede contraatacar. Aplastará 2 casillas aleatorias en el campo cada vez que un aurorian libere una habilidad activa.",
  str_monster_ability_2900662 = "Shatterblast aplastará todas las casillas del campo. Este ataque puede hacer retroceder al objetivo.",
  str_monster_ability_2900671 = "Puede usar ataques en forma de cruz o de pantalla completa e invocar rayos. Cuando se enfurece, obtiene la capacidad de derribar objetivos de manera significativa e infligir daño a pantalla completa y daño de amplio alcance.\nNota: Cuando se activan todos los demonios de Schummer, Schummer lanzará una hab. en pantalla completa que aniquila a todos los Aurorians.",
  str_monster_ability_2900681 = "Invoca No Entidades que pueden autodestruirse. Posee una poderosa habilidad de teletransporte y puede teletransportarse lejos de ti, a los bordes del Alchemy Board, para atacar.",
  str_monster_ability_2900701 = "Los ataques provocan un efecto de retroceso en el objetivo; reflejará el daño si es atacado mientras se defiende; posee un fuerte poder de recuperación; convoca un T256 al morir.",
  str_monster_ability_2900711 = "Una construcción mecánica vieja que apareció luego de div. de T-1024. Posee una capacidad innata de ataque de largo alcance.",
  str_monster_ability_2910711 = "Un robot funcional con orígenes desconocidos y capaz de realizar ataques a distancia normales.",
  str_monster_ability_29107141 = "\"¡Bip! ¡Bip!\"",
  str_monster_ability_29107111 = "\"¡Bip! ¡Bzz!\"",
  str_monster_ability_2800241 = "Parece ser un oponente muy poderoso con un poder oculto que derribará al objetivo en cada ronda.",
  str_monster_ability_2900801 = "Capaz de ordenar a Peones Perdidos que inflijan daño a los objetivos en 1 cúmulo circundante. Puede derribar objetivos a su alrededor y lanzar ataques a pantalla completa.",
  str_monster_ability_2900811 = "Capaz de ordenar a Peones Perdidos que inflijan daño a los objetivos en 1 cúmulo circundante. Puede derribar objetivos a su alrededor y lanzar ataques a pantalla completa.",
  str_monster_ability_2900911 = "Inflige daño a los objetivos en un rango enorme frente a él, y tiene la habilidad de seguir los objetivos.",
  str_monster_ability_29009111 = "Puede infligir daño a objetivos en un área grande frente a él y tiene la capacidad de rastrear objetivos. Puede invocar tentaclaws que podrían afectar la cordura de los aurorianos.",
  str_monster_ability_2900912 = "Ataca dondequiera que se encuentre el jugador en la ronda anterior. Sus ataques de área infligen daño a los objetivos y los derriban. Este monstruo resucita en su local varias rondas después de morir.",
  str_monster_ability_2901001 = "Ataca y repele a los enemigos alrededor de las casillas dañadas. Carga contra las unidades enemigas dentro de su rango de ataque y las repele. Puede dañar fichas teletransportándose repetidamente.",
  str_monster_ability_2901101 = "Puede atacar a los Aurorians desde el rango y posee la habilidad de controlar Eclipsites.",
  str_monster_ability_2901201 = "Posee un poder extraño y aterrador. Cuando el PS de Claymore cae a una cierta cantidad, _____.",
  str_monster_ability_2901300 = "Tiene una poderosa habilidad para reducir daños. Solo puede infligirle daño durante Hora de Aurora.",
  str_monster_ability_2901301 = "Tiene una poderosa habilidad para reducir daños. Solo puede infligirle daño durante Aurora Time. Capaz de convocar Esbirros del Traficante del Miedo con un ATQ fuerte para ayudarlo.",
  str_monster_ability_2901341 = "Tiene una DEF extremadamente fuerte y puede convocar a Fearmonger Minions con un fuerte ATK para ayudarlo. Sin embargo, la DEF del Fearmonger también disminuye cuando los Fearmonger Minions mueren.",
  str_monster_ability_2901401 = "Los ataques convocan a un tipo especial de Spikepest que no se puede matar con ataques que limpian el tablero. Si los jugadores se paran demasiado cerca al atacar, su daño contra mobs se reduce significativamente.",
  str_monster_ability_2901501 = "Excreta una sustancia venenosa, por lo que una parte de sus ataques cuerpo a cuerpo paralizarán al jugador. Si los jugadores se paran demasiado cerca al atacar, su daño contra mobs se reduce significativamente.",
  str_monster_ability_2901601 = "Ironstomp marcha pesadamente por el campo de batalla, infligiendo un daño devastador a cualquier casilla en su camino.",
  str_monster_ability_2901701 = "Kittypus desata sus tentáculos e inflige un daño masivo a los aurorianos. (Recuerde: ¡las tenazas de Kittypus transfieren todo el daño entrante a su anfitrión!)",
  str_monster_ability_2901801 = "Mantiene una distancia de los objetivos y es capaz de invocar y controlar trampas para ayudarse en el combate.",
  str_monster_ability_2901901 = "Capaz de tomar diferentes decisiones tácticas basadas en la distancia de los Aurorianos.",
  str_monster_ability_2901911 = "Cuando está frenético, el manejo de la espada de Castellan se mejora y causa una gran cantidad de daño.",
  str_monster_ability_2902001 = "Astuto y traicionero, es experto en ataques a distancia, y cuando el enemigo se acerca, huye y deja una sombra atrás. En cada ronda, puede conjurar un número específico de fantasmas para ayudar en la batalla.",
  str_monster_ability_2902101 = "Invoca una gran cantidad de fantasmas y desata diferentes habilidades poderosas según la distancia entre los aurorianos y el enemigo en cada ronda. Cuando Fujikumo Nobutora - Devour mata a un fantasma, restaura HP por ti mismo.",
  str_monster_ability_2902201 = "Un Eclipsite horrible que acumula valor de moretones cuando sufre daños durante el día. Capaz de contraatacar, inflige DAÑO a los objetivos cercanos y restaura HP de acuerdo con su valor de magulladura cada vez que un Aurorian libera una habilidad activa. ¡Sus poderes parecen aumentar después del anochecer!",
  str_monster_ability_2902202 = "Acumula valor de contusión al sufrir daños durante el día. Capaz de contraatacar, Helios inflige DAÑO a los objetivos cercanos y restaura HP de acuerdo con su valor de moretones cada vez que un Aurorian libera una habilidad activa. Se transforma en un Eclipsite más poderoso después del anochecer, perdiendo temporalmente las habilidades de hematomas, pero en cambio puede moverse 3 veces en cada ronda.",
  str_monster_ability_2902301 = "Capaz de moverse ingeniosamente en el campo y resistir los ataques normales de Aurorian, así como la mayoría del daño terrestre usando los obstáculos. Cuando se destruye el obstáculo, corre rápidamente hacia los obstáculos cercanos. Las habilidades Claudia Lanza obstáculos cercanos serán más poderosos que cuando se lanzan en el suelo.",
  str_monster_ability_2902401 = "Posee DEF fuerte que hace Claudia casi imbatible en el campo de batalla.",
  str_monster_ability_2902501 = "Minos cambiará entre dos estados según su pila de Marcas. Cuando está en el Estado Mortal y el Estado Minotauro, restablecerá todas las fichas por las que pasó a fichas mejoradas y debilitadas respectivamente. Cuantas más fichas mejoradas haya en el tablero, más poderoso se volverá Minos.",
  str_monster_ability_2902601 = "Puede acumular Bruise cuando recibe daño durante el día, convirtiéndolo en HP por la noche mientras se convierte en un Eclipsite más poderoso que puede infligir daño a todos los enemigos en la pantalla.",
  str_monster_ability_2902701 = "Parece ser un oponente muy poderoso que puede derribar al objetivo en cada ronda y convocar Eclipsites para ayudar en la batalla. Incluso puede controlar la generación de la Región Oscura.",
  str_monster_name_2910271 = "Coagulating Goldor",
  str_monster_ability_2910271 = "No solo posee un ataque de pant. comp., sino que también cuenta con una mayor defensa. Desp. de recibir una cierta cantidad de daño en cada ronda, no se le puede infligir más daño.",
  str_monster_name_2100111 = "Spellhound Warden",
  str_monster_ability_2100111 = "Un Spellhound de hechi. mut. con una barre. más fuer. que los Sabuesos de hechi. prom., otorgan. una mayor resis. al daño.",
  str_monster_name_2910211 = "Bloodthirsty Umbrahulk",
  str_monster_ability_2910211 = "Un Eclipsite sed. de sangre que recup. PS desp. de atacar obj. Su ataque cuerpo a cuerpo va acom. de un efecto de retro. y puede convocar piedritas. También puede lanzar un ataque a pant. comp., infligiendo daño según la cantidad de piedritas invocadas.",
  str_monster_name_2910701 = "Modified T1024",
  str_monster_ability_2910701 = "Después de la modificación, el T1024 puede repararse a sí mismo atacando. Los ataques causan un efecto de retroceso en el objetivo; reflejará el daño si es atacado mientras se defiende; posee un fuerte poder de recuperación; convoca un T256 al morir.",
  str_monster_name_2910501 = "Shifting Solmorph",
  str_monster_name_2920501 = "Evolved Solmorph",
  str_monster_name_2910601 = "Shadowborn Solfall",
  str_monster_name_2910451 = "Umbral Phorosion",
  str_monster_ability_2910451 = "Se esconderá en el Lumiwall más alejado del jugador. Los ataques pueden cambiar el elemento de los mosaicos en su ruta de ataque. Rompe 3 Lumiwalls para que aparezcan.",
  str_monster_name_2910403 = "Grievous Schummer",
  str_monster_ability_2910403 = "Habilidad en ataque a distancia y AoE y puede sincronizar sus PS. Sincroniza: El PS Schummer más bajo sincron. su PS con el PS Schummer más alto en el campo de batalla, restaurando su PS.",
  str_monster_name_2920403 = "Shattered Schummer",
  str_monster_ability_2920403 = "Restaura PS cuando es atacado por Aurorians con Elemento efectivo.\nExperto en ataques a distancia y AoE, y puede sincronizar sus PS. Sincronizar: el PS Schummer más bajo sincronizará su PS con el PS Schummer más alto en el campo de batalla, restaurando su PS.",
  str_monster_name_2910411 = "Rueful Gertzurde",
  str_monster_ability_2910411 = "Cuando Gertzurde está en modo Furia, los ataques normales golpearán dos veces y convocarán refuerzos en la batalla. Los ataques agregarán una desventaja de ataque y defensa a los enemigos golpeados. El rango de ataque de Gertzurde ahora es la red completa.",
  str_monster_name_2910441 = "Ferocious Herkeros",
  str_monster_name_2910611 = "Augmented Deathless",
  str_monster_ability_2910611 = "Incapaz de moverse, pero hábil en ataques cruzados y de amplio alcance; los ataques harán que los Aurorians pierdan energía, lo que a su vez aumenta el número de rondas de enfriamiento de Habilidades Activas; se dividirá cuando muera. Cada vez que muere un Inmortal, los Inmortales restantes se restauran a PS completo.",
  str_monster_name_2910252 = "Berserk Phantom",
  str_monster_ability_2910252 = "Obtiene una cierta cantidad de ATQ por ronda, y después de recibir una cierta cantidad de daño en cada ronda, no se le puede infligir más daño. Lanza un ataque de área en forma de cruz y convoca a clones para que luchen junto a él. Después de la clonación, absorberá el PS del clon anterior para restaurarlo a sí mismo. Cuando su PS es inferior al 50%, sus ataques normales se convertirán en ataques dobles y los ataques de área se convertirán en ataques de pantalla completa.",
  str_monster_name_2100241 = "Ravenous Croweye",
  str_monster_ability_2100241 = "Un Eclipsite con hab. de invo. de nivel medio. Incapaz de mov. solo y lucha invo. Lín. planas.",
  str_monster_name_2910431 = "Earthsplitting Mara Sol",
  str_monster_ability_2910431 = "Sobresale por usar su gran cuerpo para atacar objetos frente a él. Se hunde en el suelo y daña a los objetos cercanos al emerger, al mismo tiempo que invoca Bichos de explosión.",
  str_monster_name_2910141 = "Rabid Shelt",
  str_monster_ability_2910141 = "Exper. en ataq. cuerpo a cuerpo, puede lanzar dos ataq. norm en cada ronda. Sus ataq. aturden a los obj. alcan., y también puede convo. a Geist Sombrío y Necrófago Sombrío. Posee la cap. de contraatacar, invo. Geist Sombrío o Necrófago Sombrío para ayudar en la bat. siempre que los Aurorians usen hab.",
  str_monster_name_2910182 = "Rabid Shire",
  str_monster_ability_2910182 = "Exper. en ataq. a dist., puede lanzar dos ataques nor. en cada ronda. Sus ataq. retro. a los obj. alcan., y tam. pueden convocar a Geist Sombrío y Necrófago Sombrío. Poseen la cap. de contraatacar, invo. Geist Sombrío o Necrófago Sombrío para ayudar en la bat. siempre que los Aurorians usen habilidades.",
  str_monster_name_2910231 = "Bloodthirsty Philex",
  str_monster_ability_2910231 = "Un Eclipsite sed. de sangre que recu. PS desp. de atacar obj. Sus ataq. cuerpo a cuerpo infligen un efec. de retro. y sus hab. de ataque aturden a los objetivos.",
  str_monster_name_2910232 = "Analeptic Vani",
  str_monster_ability_2910232 = "Un Eclipsite sediento de sangre que recupera PS después de atacar objetivo. Puede usar energía. para atacar a distancia y restaurar PS a Philex.",
  str_monster_name_2910221 = "Boredom Splitter",
  str_monster_ability_2910221 = "Ignora el daño de los Aurorians con el mismo elem. que él mismo, y rest. PS cuando es atacado por Aurorians contrarrestados por este elemento. Sus ataq. norm. infligen un efecto de retroceso. Desata una amp. gama de ataq. bas. ​​en su elem.: Fuego - Daño de área gran. con efectos de Quemadura, Trueno - Daño a pant. comp. que genera Plaga de picos aleat.",
  str_monster_name_2100311 = "Augean Annihilator",
  str_monster_ability_2100311 = "Puede atacar a su obj. cuatro veces. Inmune al daño de hab. Contador de movimiento: cada vez que los Aurorians usan una hab. activa en esta ronda, el rango de mov. del aniq. de Augean aum. en 2 en la sig. ronda.",
  str_monster_name_21003111 = "Augean",
  str_monster_ability_21003111 = "Inmune al daño de habilidad.",
  str_monster_ability_21003112 = "Contador de movimiento: cada vez que los aurorianos usan una habilidad activa en esta ronda, el rango de movimiento del Augean Annihilator aumenta en +2 en la siguiente ronda.",
  str_monster_name_21003111_en = "Augean",
  str_monster_ability_21003111_en = "Immune to skill damage.",
  str_monster_name_2250281 = "Enslaved Dark Summoner",
  str_monster_name_9100161 = "Sombra necrótica",
  str_monster_desc_9100161 = "Cuando ciertas Sombras entran en la Cumbre, el poder especial de la luz que existe aquí hace que se transformen, aumentando su capacidad para cazar a sus presas. Es por este motivo que se despliegan específicamente para hacer frente a los exploradores que se atreven a entrar en la Cumbre.",
  str_monster_ability_9100161 = "Usa su lanza para atacar objetivos. Posee la habilidad de convocar Avispones Oscuros.",
  str_monster_name_5400231 = "Bloodthirsty Philex",
  str_monster_ability_5400231 = "Un Eclipsite sediento de sangre que recupera PS después de atacar objetivos. Sus ataques cuerpo a cuerpo derriban objetivos, y sus ataques de habilidad aturden a los objetivos.",
  str_monster_name_5400232 = "Analeptic Vani",
  str_monster_ability_5400232 = "Un Eclipsite sediento de sangre que recupera PS después de atacar objetivo. Puede usar energía. para atacar a distancia y restaurar PS a Philex.",
  str_monster_name_20005011 = "Rhein",
  str_monster_desc_20005011 = "Para escapar del castigo de Lumopolis, usó sus potenciadores para transformarse de un ex líder del gremio en un monstruo malvado.",
  str_monster_ability_20005011 = "El Rhein mutado puede detener objetivos distantes a su vecindad inmediata y lanzar ataques y Plaga de Picos a objetivos dentro de 1 cúmulo circundante.",
  str_monster_name_20002441 = "Lachon Hermes",
  str_monster_desc_20002441 = "A través del deseo de poder y una larga vida, degeneró en un lacayo de Eclipse, convirtiéndose finalmente en la monstruosidad que ves ante ti.",
  str_monster_ability_20002441 = "El Lachon mutado gana una habilidad de invocación avanzada. No puede moverse y lucha convocando grupos de Eclipsites.",
  str_monster_name_3900281 = "Invocador Oscuro Nefasto",
  str_monster_alias_3900281 = "Códice Desolación",
  str_monster_desc_3900281 = "1. Los monstruos nefastos se mejorarán continuamente de acuerdo con la cantidad de daño que reciban. Cada pila de mejoras aumenta su ATQ en un 10%.\n2. El ATQ de los monstruos aumenta un 8% y la DEF aumenta un 5% en cada ronda.",
  str_monster_ability_3900281 = "Invoca faros en una ubicación fija y restaura los PS del faro. Inflige daño adicional según el número actual de faros. Su habilidad es un ataque a distancia en forma de cruz que se puede cargar para infligir daño a pantalla completa.",
  str_monster_name_3900264 = "Dawn Nefasto",
  str_monster_alias_3900264 = "Códice Desolación",
  str_monster_desc_3900264 = "1. Los monstruos nefastos se mejorarán continuamente de acuerdo con la cantidad de daño que reciban. Cada pila de mejoras aumenta su ATQ en un 10%.\n2. El ATQ de los monstruos aumenta un 8% y la DEF aumenta un 5% en cada ronda.",
  str_monster_ability_3900264 = "Inflige daño a los enemigos dentro de 2 cúmulos circundantes y a todos los enemigos en el campo de batalla. Puede generar Dawn Sprite en una ubicación fija y ordenarles que inflijan daño al enemigo.",
  str_monster_name_3900641 = "Caracalune Nefasto",
  str_monster_alias_3900641 = "Códice Desolación",
  str_monster_desc_3900641 = "1. Los monstruos nefastos se mejorarán continuamente de acuerdo con la cantidad de daño que reciban. Cada pila de mejoras aumenta su ATQ en un 10%.\n2. El ATQ de los monstruos aumenta un 8% y la DEF aumenta un 5% en cada ronda.",
  str_monster_ability_3900641 = "Sobresale en el uso de ataques de amplio alcance. Después de usar ataque a distancia en forma de cruz, bloquea el elemento de la casilla sobre la que está parado.",
  str_monster_name_3900661 = "Explosión Nefasta",
  str_monster_alias_3900661 = "Códice Desolación",
  str_monster_desc_3900661 = "1. Los monstruos nefastos se mejorarán continuamente de acuerdo con la cantidad de daño que reciban. Cada pila de mejoras aumenta su ATQ en un 10%.\n2. El ATQ de los monstruos aumenta un 8% y la DEF aumenta un 5% en cada ronda.",
  str_monster_ability_3900661 = "Sobresale en el uso de ataques de amplio alcance. Después de usar ataques a distancia en cruz, rompe la casilla sobre la que está parado.",
  str_monster_name_3900211 = "Umbrahulk Nefasto",
  str_monster_alias_3900211 = "Códice Desolación",
  str_monster_desc_3900211 = "1. Los monstruos nefastos se mejorarán continuamente de acuerdo con la cantidad de daño que reciban. Cada pila de mejoras aumenta su ATQ en un 10%.\n2. El ATQ de los monstruos aumenta un 8% y la DEF aumenta un 5% en cada ronda.",
  str_monster_ability_3900211 = "Puede convocar a Piedritas y ordenarles que ataquen. Los objetivos alcanzados son derribados y se generan nuevas Piedritas en la ubicación del derribo. Puede lanzar ataques a pantalla completa. El daño infligido depende del número actual de Piedritas.",
  str_monster_name_3900251 = "Fantasma Nefasto",
  str_monster_alias_3900251 = "Códice Desolación",
  str_monster_desc_3900251 = "1. Los monstruos nefastos se mejorarán continuamente de acuerdo con la cantidad de daño que reciban. Cada pila de mejoras aumenta su ATQ en un 10%.\n2. El ATQ de los monstruos aumenta un 8% y la DEF aumenta un 5% en cada ronda.",
  str_monster_ability_3900251 = "Puede lanzar ataques de área en forma de cruz. Invoca clones para lanzar ataques a pantalla completa.",
  str_monster_name_3900411 = "Gertzurde Nefasto",
  str_monster_alias_3900411 = "Códice Desolación",
  str_monster_desc_3900411 = "1. Los monstruos nefastos se mejorarán continuamente de acuerdo con la cantidad de daño que reciban. Cada pila de mejoras aumenta su ATQ en un 10%.\n2. El ATQ de los monstruos aumenta un 8% y la DEF aumenta un 5% en cada ronda.",
  str_monster_ability_3900411 = "Invoca refuerzos en batalla. Cada ataque agrega una desventaja de DEF a los enemigos, y el rango de ataque se extiende por todo el tablero. Los ataques normales golpearán dos veces.",
  str_monster_name_3000451 = "Sirviente Nefasto",
  str_monster_alias_3000451 = "Códice Desolación",
  str_monster_desc_3000451 = "1. Los monstruos nefastos se mejorarán continuamente de acuerdo con la cantidad de daño que reciban. Cada pila de mejoras aumenta su ATQ en un 10%.\n2. El ATQ de los monstruos aumenta un 8% y la DEF aumenta un 5% en cada ronda.",
  str_monster_ability_3000451 = "Al rugir, los ataques acumulan una desventaja de DEF en los objetivos alcanzados.",
  str_monster_name_3000602 = "Nefasto Dawn Sprite",
  str_monster_alias_3000602 = "Códice Desolación",
  str_monster_desc_3000602 = "1. Los monstruos nefastos se mejorarán continuamente de acuerdo con la cantidad de daño que reciban. Cada pila de mejoras aumenta su ATQ en un 10%.\n2. El ATQ de los monstruos aumenta un 8% y la DEF aumenta un 5% en cada ronda.",
  str_monster_ability_3000602 = "Ordenado por Dawn para enfrentarse al enemigo en batalla, se aferran al cuerpo del enemigo cuando están dentro de 1 cúmulo circundante e infligen daño a su objetivo.",
  str_monster_name_3000131 = "Faro Nefasto",
  str_monster_alias_3000131 = "Códice Desolación",
  str_monster_desc_3000131 = "1. Los monstruos nefastos se mejorarán continuamente de acuerdo con la cantidad de daño que reciban. Cada pila de mejoras aumenta su ATQ en un 10%.\n2. El ATQ de los monstruos aumenta un 8% y la DEF aumenta un 5% en cada ronda.",
  str_monster_ability_3000131 = "Un Faro convocado por un Invocador Oscuro. Aumenta el ATQ del Invocador Oscuro.",
  str_monster_name_3910451 = "Phorosion Nefasta",
  str_monster_alias_3900451 = "Códice Desolación",
  str_monster_desc_3900451 = "1. Los monstruos nefastos se mejorarán continuamente de acuerdo con la cantidad de daño que reciban. Cada pila de mejoras aumenta su ATQ en un 10%.\n2. El ATQ de los monstruos aumenta un 8% y la DEF aumenta un 5% en cada ronda.",
  str_monster_ability_3910451 = "Al usar ataques a distancia, crea un espejismo en una ubicación fija. Al chocar contra objetivos, crea un espejismo junto al objetivo.",
  str_monster_name_2001501 = "Fantasma",
  str_monster_desc_2001501 = "Un monstruo especial del Lejano Oriente que se dice que \"ni está vivo ni muerto\" y es extremadamente hostil hacia los vivos.",
  str_monster_ability_2001501 = "Sus habilidades de lucha pueden no ser temibles, pero su número sí lo es.",
  str_monster_name_21601191 = "Revy",
  str_monster_name_21601191_en = "Revy",
  str_monster_name_21601171 = "Gram",
  str_monster_name_21601171_en = "Gram",
  str_monster_name_21601291 = "Luke",
  str_monster_name_21601291_en = "Luke",
  str_monster_name_21500991 = "Areia",
  str_monster_name_21500991_en = "Areia",
  str_monster_name_21500751 = "Odi",
  str_monster_name_21500751_en = "Odi",
  str_monster_name_21300531 = "Jomu",
  str_monster_name_21300531_en = "Jomu",
  str_monster_name_21400401 = "Joanie Boom",
  str_monster_name_21400401_en = "Joanie Boom",
  str_monster_desc_21601191 = "Una nueva recluta Illumina. Genial en combate, pero distante, impulsiva y con mala comunicación. Tiene ilusión de lograr la gloria en batalla.",
  str_monster_desc_21601171 = "Un veterano que ha servido las líneas defensivas Illumina, él se retiró y ahora trabaja con logística. Firme afuera y blando adentro, él es un gran aliado en el campo de batalla.",
  str_monster_desc_21601291 = "Comandante adjunto de un escuadrón de mercenarios Umbraton, un hombre de honor, sabe todo de la ciudad. Ahora trabaja duro para ampliar las fuerzas mercenarias.",
  str_monster_desc_21500991 = "Una mercenaria errante en Umbraton. Nació con una maldición que la hizo anémica, y depende de su espada mágica para sobrevivir.",
  str_monster_desc_21500751 = "Personal técnico de Rediesel Wrench que confía mucho en su tecnología de comunicaciones. Le gusta quejarse y gritar a los demás en el canal de comunicación, pero se pone nerviosa cuando hay problemas.",
  str_monster_desc_21300531 = "Un comerciante de Rediesel Wrench. Típico mercader en busca de dinero, nunca pierde la oportunidad de obtener ganancias... Incluso cuando se enfrenta a tareas difíciles, su cuchillo corto es el que usualmente hace el trabajo.",
  str_monster_desc_21400401 = "Una niña fascinada por las explosiones, que se emociona de forma inusual cuando algo detona. Tal locura es una entrada a Rediesel Wrench. Como Rediesel, se pasa todo el tiempo estudiando explosivos y ni siquiera podría importarle menos si su vida corre peligro...",
  str_monster_ability_21601191 = "Experto en ataques a distancia, inflige daño en un área de columna.",
  str_monster_ability_21601171 = "Adepto a los ataques cuerpo a cuerpo, usa sus habilidades para infligir daño de gran área a los enemigos circundantes.",
  str_monster_ability_21601291 = "Experto en ataques a distancia, usa su habilidad de pantalla completa para infligir daño e infligir Parasitic Mark a los enemigos. Cada vez que el enemigo se mueve, recibe daño de Parasitic Mark.",
  str_monster_ability_21500991 = "Experta en ataques de área, sus habilidades aumentan su propio ACT y ATK para infligir un gran daño de área.",
  str_monster_ability_21500751 = "Experta en ataques de área a distancia, sus ataques infligen Veneno.",
  str_monster_ability_21300531 = "Experto en ataques cuerpo a cuerpo, sus ataques infligen sangrado.",
  str_monster_ability_21400401 = "No se mueve, sino que usa una gran área de ataque, cambia los elementos de mosaico dentro del alcance e inflige quemadura.",
  str_monster_name_1300221 = "Chainsaw Rick",
  str_monster_desc_1300221 = "El chico bajito, ruidoso y alocado que parece nunca frenar y siempre lleva un casco de conejo en la cabeza. Está constantemente empujando sus límites en batalla, lo que a menudo es malentendido con tener un deseo de muerte. Es un milagro que siga vivo.",
  str_monster_ability_1300221 = "Chainsaw Rick inflige daño a la unidad enemiga más cercana alrededor de un mosaico rojo.",
  str_monster_name_1300521 = "Dove",
  str_monster_desc_1300521 = "Una mensajera que trabaja para la Federación Illumina, aunque no es miembro. Sólo presta servicios postales, y es una vaga total sin una pizca de orgullo profesional, dispuesta a hacer cualquier cosa para retrasar o librarse del trabajo.",
  str_monster_ability_1300521 = "Dove inflige daño a la unidad enemiga más cercana alrededor de una casilla verde.",
  str_monster_name_1400321 = "Ángel",
  str_monster_desc_1400321 = "Integrante del Salón de Justicia de Lumo y un ángel de un ala. Ella es sensible y con fuerte sentido de orgullo. A pesar de su edad, Angel ha vivido la guerra.",
  str_monster_ability_1400321 = "Ángel inflige daño a la unidad enemiga más cercana alrededor de un mosaico amarillo.",
  str_monster_name_1501491 = "Roy",
  str_monster_desc_1501491 = "El gerente de logística de Rediesel Wrench. Aunque parece desorganizado, en realidad es muy atento y protector con todos en Rediesel Wrench.",
  str_monster_ability_1501491 = "Roy inflige daño a la unidad enemiga más cercana alrededor de un mosaico amarillo.",
  str_monster_name_1400411 = "Srta. Blanc",
  str_monster_desc_1400411 = "Mujer tranquila y elegante, actúa como guía para los neófitos de Lumopolis. Mantiene la compostura incluso en las catástrofes, insinuando un pasado extraordinario, pero cuando se le pregunta por ello, se limita a una misteriosa sonrisa...",
  str_monster_ability_1400411 = "La Sra. Blanc no solo inflige daño a la unidad enemiga más cercana alrededor de un mosaico azul, sino que también convierte todos los mosaicos a su alrededor en azules.",
  str_monster_name_1300471 = "Zoya",
  str_monster_desc_1300471 = "Una genial investigadora de la Federación Illumina cuya hambre de conocimiento ocupa toda su atención... Eso, y una cierta Comandante de la Legión. Aunque parece callada, acercarse a ella precipitadamente sería una invitación al ridículo. Por el bien de todos, sería mejor no molestarla muy seguido.",
  str_monster_ability_1300471 = "Zoya restaura HP al compañero de equipo con el HP más bajo.",
  str_monster_name_1300531 = "Jomu",
  str_monster_desc_1300531 = "Un comerciante de Rediesel Wrench. Típico mercader en busca de dinero, nunca pierde la oportunidad de obtener ganancias... Incluso cuando se enfrenta a tareas difíciles, su cuchillo corto es el que usualmente hace el trabajo.",
  str_monster_ability_1300531 = "Jomu inflige daño a los enemigos dentro de 1 grupo circundante.",
  str_monster_name_1201631 = "Tourdog",
  str_monster_desc_1201631 = "Una fascinante criatura del norte apasionada por los juegos. Cada vez que se encuentre con alguien nuevo, siempre preguntará: \"Estimado maestro, ¿acepta comisiones?\"",
  str_monster_ability_1201631 = "Tiene una pasión ardiente por el baile.",
  str_monster_name_1600061 = "Carleen",
  str_monster_desc_1600061 = "La capitana de Jardines Lumo es también la hija de Schwartz. Una noble dama que nunca tolera la vileza, respeta el orden y detesta el mal. Lo más sorprendente es que se convirtió en caballero, no por influencia de su padre, sino por su propio esfuerzo.",
  str_monster_ability_1600061 = "Carleen no solo inflige daño a la unidad enemiga más cercana alrededor de una casilla azul, sino que también inflige daño a otros enemigos en la misma columna y los repele.",
  str_monster_name_1600111 = "Sharona",
  str_monster_desc_1600111 = "Un comandante de la Legión de la Federación Illumina y una belleza fría con el poder de los dragones. A pesar de su apariencia gélida, es alguien con quien puedes contar. Sus orígenes están envueltos en misterio. Después de unirse a la Federación, se convirtió en la Comandante de la Legión gracias a su logro militar. Ella siempre lleva su espada llama azur que simboliza su herencia.",
  str_monster_ability_1600111 = "Sharona inflige daño a los enemigos dentro de 2 grupos circundantes.",
  str_monster_name_1500331 = "Vice",
  str_monster_desc_1500331 = "Miembro de la Federación Illumina con una personalidad amable. No sólo es muy talentosa, trabajadora y entusiasta, sino que también ha recibido un entrenamiento intensivo desde muy joven gracias al reconocimiento de altos funcionarios. Ahora ha sido nombrada capitana de la expedición encargada de búsqueda y excavación de ruinas antiguas.",
  str_monster_ability_1500331 = "Vice no solo inflige daño a la unidad enemiga más cercana alrededor de un mosaico azul, sino que también inflige daño continuo al enemigo más cercano.",
  str_monster_name_1600021 = "Hiiro",
  str_monster_desc_1600021 = "Una chica con habilidades de lucha inigualables. Como comandante de la Legión de la Federación Illumina, es conocida por ser estricta, seria y decidida. Afronta cada batalla con una confianza calculada y ha conseguido muchas victorias con su espada larga en mano.",
  str_monster_ability_1600021 = "Hiiro no solo inflige daño a la unidad enemiga más cercana alrededor de un mosaico verde, sino que también inflige Crimson Sakura al enemigo más cercano.",
  str_monster_name_2800601 = "toro 8",
  str_monster_desc_2800601 = "Diseñado especialmente para el rally, este vehículo ha sido reacondicionado para atravesar terrenos difíciles. No solo es duradero, sino que también está fuertemente armado.",
  str_monster_ability_2800601 = "No se pueden lanzar habilidades sin un conductor.",
  str_monster_name_2000191 = "Totó",
  str_monster_desc_2000191 = "En realidad, cada pequeño Slasher tiene un sueño. Es solo que a nadie le importaba preguntar.",
  str_monster_name_1500901 = "Barbara",
  str_monster_desc_1500901 = "La cantora ídolo de Rediesel Wrench. Barbara parece ser amable y simpática, pero revela su lado irritable cuando se encuentra con un fan demasiado ofensivo. Viaja por todas partes para hacerse la ídolo más popular.",
  str_monster_ability_1500901 = "Barbara inflige daño a todos los enemigos que ocupan casillas rojas.",
  str_monster_name_1501141 = "Genevieve",
  str_monster_desc_1501141 = "Elegante cazarrecompensas del True Order que es alegre y le gusta disfrutar de un vaso de refresco aquí y allá. Actualmente está tratando de construir una red de inteligencia para rastrear el paradero de una determinada persona.",
  str_monster_ability_1501141 = "Genevieve salta sobre los enemigos ubicados en diagonal desde su posición y, después de aterrizar, inflige daño a 1 grupo circundante. Si hay un objetivo en el punto de aterrizaje, inflige daño severo al objetivo y lo derriba.",
  str_monster_name_1600141 = "Schwartz",
  str_monster_desc_1600141 = "El gobernador de Lumopolis y su actual gobernante, cuya posición y estatus le sitúan muy por encima de los demás. Tal éxito no está exento de costos, y la soledad es su compañera constante. Sin embargo, Schwartz pasa innumerables horas manteniendo el orden en Lumopolis, y siempre se esfuerza por hacerlo lo mejor posible sin bajar la guardia.",
  str_monster_ability_1600141 = "Schwartz inflige daño a todos los enemigos en el campo de batalla mientras convoca a Lumo Guards para eliminar a sus enemigos.",
  str_monster_name_2001701 = "llorón",
  str_monster_desc_2001701 = "Un eclipse que está principalmente activo durante la noche. Durante el día, se postra en el suelo y no puede moverse.",
  str_monster_ability_2001701 = "Durante el día se postra en el suelo y se mantiene en posición defensiva. Una vez que comienza la noche, retoma su verdadero estado.",
  str_monster_name_3902501 = "Minos",
  str_monster_name_3902501_en = "Minos",
  str_monster_alias_3902501 = "Códice Desolación",
  str_monster_desc_3902501 = "1. Los monstruos nefastos se mejorarán continuamente de acuerdo con la cantidad de daño que reciban. Cada pila de mejoras aumenta su ATQ en un 10%.\n2. El ATQ de los monstruos aumenta un 8% y la DEF aumenta un 5% en cada ronda.",
  str_monster_ability_3902501 = "Invoca una ficha debilitada en una posición aleatoria cada ronda. Inflige daño al objetivo una vez cada vez que pasa sobre una casilla debilitada. La habilidad cargable inflige daño a pantalla completa.",
  str_monster_name_3903101 = "Barbara",
  str_monster_name_3903101_en = "Barbara",
  str_monster_alias_3903101 = "Códice Desolación",
  str_monster_desc_3903101 = "1. Los monstruos nefastos se mejorarán continuamente de acuerdo con la cantidad de daño que reciban. Cada pila de mejoras aumenta su ATQ en un 10%.\n2. El ATQ de los monstruos aumenta un 8% y la DEF aumenta un 5% en cada ronda.",
  str_monster_ability_3903101 = "Muévase siempre a la ubicación más lejana del objetivo. Inflige daño de gran área excepto en algunas zonas seguras específicas. La habilidad cargable inflige daño a pantalla completa y derriba a los objetivos.",
  str_monster_name_3903201 = "Connolly",
  str_monster_name_3903201_en = "Connolly",
  str_monster_name_3903301 = "Beryl",
  str_monster_name_3903301_en = "Beryl",
  str_monster_alias_3903201 = "Códice Desolación",
  str_monster_alias_3903301 = "Códice Desolación",
  str_monster_desc_3903201 = "1. Los monstruos nefastos se mejorarán continuamente de acuerdo con la cantidad de daño que reciban. Cada pila de mejoras aumenta su ATQ en un 10%.\n2. El ATQ de los monstruos aumenta un 8% y la DEF aumenta un 5% en cada ronda.",
  str_monster_desc_3903301 = "1. Los monstruos nefastos se mejorarán continuamente de acuerdo con la cantidad de daño que reciban. Cada pila de mejoras aumenta su ATQ en un 10%.\n2. El ATQ de los monstruos aumenta un 8% y la DEF aumenta un 5% en cada ronda.",
  str_monster_ability_3903201 = "Los tentáculos se invocan en cada ronda en lugares aleatorios para dificultar el movimiento de los aurorianos. El HP de los tentáculos aumenta ronda a ronda. Las habilidades infligen daño de área y las habilidades cargables infligen daño a pantalla completa.",
  str_monster_ability_3903301 = "Sanguine Crystal se invoca cada ronda en puntos aleatorios para dificultar el movimiento de los aurorianos. Cuando Nefarious Beryl pasa un cristal, lo rompe y obtiene un impulso de ATK. Las habilidades infligen daño de área y las habilidades cargables infligen daño a pantalla completa.",
  str_monster_name_3903401 = "Schwartz",
  str_monster_name_3903401_en = "Schwartz",
  str_monster_ability_2900913 = "Ataca dondequiera que el jugador estuviera ubicado en la ronda anterior. Este monstruo resucitará en su ubicación varias rondas después de morir.",
  str_monster_name_2903001 = "guardián del núcleo",
  str_monster_name_2903001_en = "Core Guardian",
  str_monster_desc_2903001 = "Un guardián gigantesco que protege el núcleo de energía de la nave. Se despertará y luchará cuando el Núcleo esté bajo amenaza.",
  str_monster_ability_2903001 = "Este poderoso ser tiene la capacidad de alterar todo el tablero, pero también tiene un talón de Aquiles.",
  str_monster_name_2001801 = "rueda trituradora",
  str_monster_desc_2001801 = "Uno de los sistemas de defensa del Energy Core y difícil de destruir. Lanzará interminables ataques contra los enemigos.",
  str_monster_ability_2001801 = "Un ser indestructible. Cuando su HP llegue a cero, entrará en un estado paralizado. Se vuelve invencible en ese estado y recuperará HP automáticamente en cada ronda. Cuando su HP esté lleno, recuperará la capacidad de moverse y actuar.",
  str_monster_name_2001802 = "Módulo de congelación",
  str_monster_desc_2001802 = "El módulo de refrigeración permite que el potente Core Guardian funcione con normalidad.\nPuede que sea la única debilidad del guardián, pero si te acercas a él precipitadamente, te quemarás con el calor que emite.",
  str_monster_ability_2001802 = "Interrumpe un área e inflige daño a los aurorianos por cada casilla que se mueva dentro del área interrumpida.",
  str_monster_desc_2900311 = "Eclipsite increíblemente poderoso, de quien se dice que luchó en innumerables guerras. Un ser fuerte que ha sobrevivido a lluvias de balas y bombas. Nadie sabe cuántos de sus enemigos han caído bajo sus espadas.",
  str_monster_passiveskill_name_2900144 = "De la nada: Gloom Ghoul",
  str_monster_passiveskill_desc_2900144 = "Invoca una Runa en una ubicación aleatoria, que se convierte en un Gloom Ghoul en 3 rondas.",
  str_monster_passiveskill_name_2900184 = "Inesperadamente: Shadowgeist",
  str_monster_passiveskill_desc_2900184 = "Invoca una runa en una ubicación aleatoria, que se convierte en un Shadowgeist en 3 rondas.",
  str_monster_passiveskill_name_2000451 = "Sacrificio del sirviente",
  str_monster_passiveskill_desc_2000451 = "Restaura una cierta cantidad de HP al jugador cuando muere.",
  str_monster_passiveskill_name_2900611 = "Inmortal: Clon",
  str_monster_passiveskill_desc_2900611 = "Se divide en unidades de combate más pequeñas cuando muere.",
  str_monster_passiveskill_name_2900641 = "Caracalune: Contaminación",
  str_monster_passiveskill_desc_2900641 = "Inflige una pequeña cantidad de daño al jugador y bloquea las fichas dentro de 1 grupo circundante del jugador.",
  str_monster_passiveskill_name_2900661 = "Shatterblast: Grieta en la Tierra",
  str_monster_passiveskill_desc_2900661 = "Genera 2 fichas dañadas al azar en el campo.",
  str_monster_passiveskill_name_2900671 = "Schummer: Aniquilación",
  str_monster_passiveskill_desc_2900671 = "Cuando todos los Daemons de Schummer se han activado, Schummer lanza una habilidad que derrota todo en la pantalla.",
  str_monster_passiveskill_name_2902200 = "Contraataque nocturno",
  str_monster_passiveskill_desc_2902200 = "Inflige daño a los objetivos dentro de 2 grupos circundantes y recupera algo de HP en función del Moretón acumulado.",
  str_monster_passiveskill_name_2902301 = "Claudia: Plataforma",
  str_monster_passiveskill_desc_2902301 = "Claudia no puede ser dañada por ataques normales cuando está parada en una plataforma o Asher.",
  str_monster_passiveskill_name1_2902301 = "Claudia: Teletransportarse",
  str_monster_passiveskill_desc1_2902301 = "Cuando la plataforma debajo de ella se rompe, o Asher queda fuera de combate, Claudia se teletransporta a otra plataforma dentro de 2 grupos circundantes o cae al suelo.",
  str_monster_passiveskill_name_9000101 = "Vuelo",
  str_monster_passiveskill_desc_9000101 = "Este enemigo puede moverse a través del abismo.",
  str_monster_passiveskill_name_2000311 = "Doble cuchillada",
  str_monster_passiveskill_desc_2000311 = "Dreadblades ataca al objetivo dos veces.",
  str_monster_passiveskill_name_2000221 = "Plaga de picos",
  str_monster_passiveskill_desc_2000221 = "Genera Spikepest en baldosas pisadas.",
  str_monster_passiveskill_name_2000511 = "Confusión",
  str_monster_passiveskill_desc_2000511 = "Al golpear a un objetivo, aumenta las rondas de enfriamiento de la habilidad activa de este Aurorian.",
  str_monster_passiveskill_name_2000521 = "Encarcelamiento de Lumina",
  str_monster_passiveskill_desc_2000521 = "Bloquea las fichas en 1 grupo circundante después de moverse. Pierde efecto cuando está aturdido, asustado, paralizado o infligido con otros efectos de control.",
  str_monster_passiveskill_name_2000551 = "Resentimiento",
  str_monster_passiveskill_desc_2000551 = "Al atacar, inflige una maldición sobre los Aurorians del mismo elemento. Los Aurorians malditos no podrán atacar ni usar habilidades activas.",
  str_monster_passiveskill_name1_2000551 = "Disipación de rencor",
  str_monster_passiveskill_desc1_2000551 = "Cuando muere, elimina las maldiciones colocadas por Cursed Fay en los aurorianos del mismo elemento.",
  str_monster_passiveskill_name_2001701 = "desfile de lamentos",
  str_monster_passiveskill_desc_2001701 = "Se postra en el suelo en posición defensiva durante el día. Una vez que comienza la noche, recupera su verdadero estado y ataca a los aurorianos.",
  str_monster_passiveskill_name_2901001 = "hombre en marco",
  str_monster_passiveskill_desc_2901001 = "Se esconde cuando está en los mosaicos dañados, solo recibe daño de área y se vuelve inmune a los ataques y habilidades normales cuando se selecciona un mosaico.",
  str_monster_passiveskill_name_2901301 = "aurora debilitada",
  str_monster_passiveskill_desc_2901301 = "El daño recibido durante la Hora de Aurora aumenta considerablemente.",
  str_monster_passiveskill_name_2001301 = "aurora vital",
  str_monster_passiveskill_desc_2001301 = "Solo puede ser atacado por aurorianos durante el tiempo de aurora.",
  str_monster_passiveskill_name_2903001 = "Guardián del núcleo intacto",
  str_monster_passiveskill_desc_2903001 = "Cuando Core Guardian está alerta, solo recibe daño de un solo objetivo de los ataques que no seleccionan mosaicos y se vuelve inmune a los ataques normales y de área.",
  str_monster_passiveskill_name1_2903001 = "Guardián del núcleo paralizado",
  str_monster_passiveskill_desc1_2903001 = "Se exponen más puntos débiles después de que Core Guardian se paraliza y se pierde la inmunidad al daño.",
  str_monster_passiveskill_name_2000901 = "Autodestrucción cronometrada",
  str_monster_passiveskill_desc_2000901 = "Se autodestruye después de que la cuenta regresiva llega a cero, destruyendo el mosaico debajo de él.",
  str_monster_passiveskill_name_2001801 = "Rueda trituradora paralizada",
  str_monster_passiveskill_desc_2001801 = "Cuando el HP de Crusher Wheel se reduce a cero, entra en un estado paralizado. Cuando su HP vuelve a estar lleno, recupera la capacidad de moverse y actuar.",
  str_monster_passiveskill_name_2001802 = "Fallo del módulo de congelación",
  str_monster_passiveskill_desc_2001802 = "La debilidad del Guardián del Núcleo. Cuando el HP del Freeze Module se reduce a cero, el Core Guardian entra en un estado paralizado.",
  str_monster_passiveskill_name_2900301 = "Escudo de jugador de bolos",
  str_monster_passiveskill_desc_2900301 = "El Escudo de energía protege a Bowlinger de sufrir daños. (Paralizarlo atacando un área sin protección con el Deathrider para infligir daño a Bowlinger de manera efectiva)",
  str_monster_passiveskill_name_2910281 = "Escudo de fuente de alimentación",
  str_monster_passiveskill_desc_2910281 = "Cada Dark Summoner Beacon en el campo reduce el daño recibido por Dark Summoner.",
  str_monster_passiveskill_name_2010481 = "Lumiwall",
  str_monster_passiveskill_desc_2010481 = "Los aurorianos solo pueden infligir daño al Lumiwall después de que el Phorosion se esconda en este Lumiwall. Otros Lumiwalls no pueden ser atacados.",
  str_monster_passiveskill_name_2901201 = "Luz del Engañador",
  str_monster_passiveskill_desc_2901201 = "Claymore tiene la capacidad de conectarse y moverse a lo largo de mosaicos del mismo color.",
  str_monster_passiveskill_name1_2901201 = "Tumba de inmortales",
  str_monster_passiveskill_desc1_2901201 = "Después de que Call of the Grave se disipa, Claymore obtiene una habilidad de contraataque que inflige daño a los aurorianos en función del ATK del auroriano que lanzó la habilidad y recupera su propio HP.",
  str_monster_passiveskill_name_2900312 = "Doble cuchillada",
  str_monster_passiveskill_desc_2900312 = "Augean ataca al objetivo dos veces.",
  str_monster_passiveskill_name1_2900312 = "Madriguera",
  str_monster_passiveskill_desc1_2900312 = "Aumenta la distancia de movimiento en 2 fichas y se recupera en la siguiente ronda.",
  str_monster_passiveskill_name_3900451 = "Fuerza nefasta",
  str_monster_passiveskill_desc_3900451 = "Cuando los monstruos nefastos reciben daño, el efecto del contador de elementos aumenta en un 100%.\nLos monstruos nefastos se mejorarán continuamente según el daño que reciban. Cada pila de mejora aumenta su ATK en un 10%.\nEl ATK de los monstruos nefastos aumenta en un 8 % y la DEF aumenta en un 5 % en cada ronda.",
  str_monster_passiveskill_name_3910281 = "Imán de energía",
  str_monster_passiveskill_desc_3910281 = "Cada baliza de invocador oscuro en el campo aumenta el ATK de invocador oscuro.",
  str_monster_passiveskill_name_3903101 = "Escudo nefasto",
  str_monster_passiveskill_desc_3903101 = "Inmune al daño durante su fase de acción.",
  str_monster_passiveskill_name_3903301 = "Nefasto: invocación de cristal",
  str_monster_passiveskill_desc_3903301 = "Genera cristales de sangre en ubicaciones aleatorias en el campo cada ronda (hay una restricción de número máximo).",
  str_monster_passiveskill_name_3903201 = "Nefasto: Nacido del pavor",
  str_monster_passiveskill_desc_3903201 = "Genera tentáculos en ubicaciones aleatorias en el campo cada ronda (hay una restricción de número máximo).",
  str_monster_passiveskill_name_3902501 = "Infame: Debilitamiento designado",
  str_monster_passiveskill_desc_3902501 = "Genera mosaicos debilitados en ubicaciones aleatorias en el campo cada ronda.",
  str_monster_passiveskill_name_2901341 = "Corazón roto",
  str_monster_passiveskill_desc_2901341 = "Reduce la DEF de Fearmonger cada vez que muere un Minion Fearmonger.",
  str_monster_passiveskill_name_29009211 = "Armadura colapsada",
  str_monster_passiveskill_desc_29009211 = "La DEF inicial de Hylingerr es muy alta, y disminuye a medida que se reduce la cordura del auroriano, hasta un mínimo del 40 %.",
  str_monster_passiveskill_name_2912101 = "Devorador de fantasmas",
  str_monster_passiveskill_desc_2912101 = "Restaura el 1% del HP máximo cuando atrapa un fantasma.\nReduce la propia DEF en un 1% cuando muere un fantasma en el campo.",
  str_monster_name_2903901 = "Casta",
  str_monster_name_2903901_en = "Casta",
  str_monster_desc_2903901 = "Aparentemente distante, pero en realidad muy responsable. Se asoció con Pollux para formar el dúo de mercenarios llamado \"Raven's Blood\" para defender mejor a los niños que viven en la iglesia.",
  str_monster_ability_2903901 = "Ataca a los enemigos cuerpo a cuerpo con una bayoneta o los ataca a distancia con balas. Ataca a los enemigos con diferentes habilidades según su ubicación.",
  str_monster_passiveskill_name_29039011 = "Ruleta Rusa: Contador",
  str_monster_passiveskill_desc_29039011 = "Cada vez que un Auroriano usa una Habilidad Activa, Casta mueve 2 fichas hacia el Auroriano. Cuando hay algún Auroriano dentro de 1 grupo circundante de Casta, lanza la habilidad para atacar al Auroriano.",
  str_monster_passiveskill_desc_29039012 = "Cada vez que un Auroriano usa una Habilidad Activa, Casta mueve 3 fichas hacia el Auroriano. Cuando hay algún Auroriano dentro de 1 grupo circundante de Casta, lanza la habilidad para atacar al Auroriano.",
  str_monster_passiveskill_desc_29039013 = "Cada vez que un Aurorian usa una Habilidad Activa, Casta mueve 3 fichas hacia el Aurorian y se aplica 2 capas de escudo de conteo a sí misma. Cuando hay algún Auroriano dentro de 1 grupo circundante de Casta, lanza la habilidad para atacar al Auroriano.",
  str_monster_name_2903701 = "Cañón autopropulsado",
  str_monster_name_2903701_en = "Self-Propelled Cannon",
  str_monster_desc_2903701 = "Poderosos guardias capaces de patrullar por su cuenta. Tanto el cañón principal como el del hombro son increíblemente poderosos. Solo uno de esos guardias puede causar un gran daño.",
  str_monster_ability_2903701 = "Puede usar torretas para infligir daño continuo al enemigo y ahuyentar a cualquier enemigo que se le acerque demasiado. La guardia se fortalecerá cuando perciba una gran amenaza.",
  str_monster_ability_4000445 = "Lanza ataques cuerpo a cuerpo contra objetivos, y convierte todas las fichas a lo largo de su ruta de movimiento en fichas de su propio elemento, generando picos en el camino.",
  str_monster_passiveskill_name_4000445 = "Llama Murkmite",
  str_monster_passiveskill_desc_4000445 = "Genera picos a lo largo de su ruta de movimiento y convierte las fichas pasadas en rojas.",
  str_monster_name_21500781 = "Robyn",
  str_monster_name_21500781_en = "Robyn",
  str_monster_desc_21500781 = "Miembro de los Lanzas en Umbraton. Tímida e introvertida, se mantiene cerca de su hermana, Dayna, mientras intenta sobrevivir en Umbraton.",
  str_monster_ability_21500781 = "Dayna se vuelve más poderosa cuando es derrotada.",
  str_monster_name_21400481 = "Dayna",
  str_monster_name_21400481_en = "Dayna",
  str_monster_desc_21400481 = "Ya es líder de los Lanzas a pesar de su corta edad, y es bien conocida por establecer un firme punto de apoyo en los oscuros y mugrientos callejones de Umbraton con su insuperable determinación y sus armas furtivas y diabólicas.",
  str_monster_ability_21400481 = "Experto en ataques a distancia, inflige daño en un área de columna.",
  str_monster_name_21400911 = "Chloe",
  str_monster_name_21400911_en = "Chloe",
  str_monster_desc_21400911 = "Músico amable y amigable de Lumopolis que se ahoga fácilmente en sus tristes recuerdos. Ella perdió a su familia debido a la guerra, por lo que vive en el dolor y le resulta difícil olvidarlo.",
  str_monster_ability_21400911 = "Aumenta el ATK del aliado según la cantidad de fichas azules en el campo.",
  str_monster_ability_21400912 = "Aumenta el ATK del aliado según la cantidad de fichas azules en el campo. También aumenta ACT.",
  str_monster_name_21200501 = "Korgon",
  str_monster_name_21200501_en = "Korgon",
  str_monster_desc_21200501 = "¡Es un tiburón aterrador incluso cuando sonríe! Es el protector de un pequeño asentamiento y, a pesar de su exterior feroz y temible, en realidad es un tierno amante de los gatos.",
  str_monster_ability_21200501 = "Lanza poderosos ataques que pueden causar retroceso al golpear a un objetivo.",
  str_monster_name_21300491 = "Seleucid",
  str_monster_name_21300491_en = "Seleucid",
  str_monster_desc_21300491 = "Un guerrero alto y fuerte que suele recorrer Umbraton con armadura completa y una gran espada. Hombre de pocas palabras, nunca se ha quitado el casco y prefiere dejar que la fuerza bruta hable por él.",
  str_monster_ability_21300491 = "Restablece mosaicos que no son azules dentro de 1 grupo circundante mientras inflige daño.",
  str_monster_ability_4900251 = "Realiza ataques de área en forma de cruz e invoca a un clon para luchar junto a él. Al clonarse a sí mismo, absorbe el HP del clon anterior para recuperar HP y aumentar su ATK. Cuando el clon está presente, la forma real de Phantom también puede esquivar ataques, pero también recibirá daño cuando el clon se lastime.",
  str_monster_ability_4910252 = "Al llegar, se vuelve rabioso y convoca a un clon para luchar junto a él. Si el Fantasma absorbe el clon, recupera HP y aumenta considerablemente el ATK.",
  str_monster_passiveskill_name_290370113 = "Reacción del mecanismo",
  str_monster_passiveskill_desc_290370113 = "Mueve 1 mosaico e invoca 1 T256 al frente",
  str_monster_name_4910181 = "Regina",
  str_monster_name_4910181_en = "Regina",
  str_monster_desc_4910181 = "Su naturaleza audaz y desinhibida, así como su impulsividad, son las marcas de una verdadera ¡alma rockera! Su feroz estilo musical la hizo muy popular dentro de Rediesel Wrench, permitiéndole no sólo inspirar a las tropas, sino también liderarlas al frente.",
  str_monster_ability_4910181 = "Persigue enemigos y lanza ataques con acción intimidatoria.",
  str_monster_name_4903101 = "Barbara",
  str_monster_name_4903101_en = "Barbara",
  str_monster_desc_4903101 = "La cantora ídolo de Rediesel Wrench. Barbara parece ser amable y simpática, pero revela su lado irritable cuando se encuentra con un fan demasiado ofensivo. Viaja por todas partes para hacerse la ídolo más popular.",
  str_monster_ability_4903101 = "Lanza \"bombas\" al campo para obstaculizar a los enemigos.",
  str_monster_ability_49031011 = "Invoca elementos al campo para obstaculizar a los enemigos.",
  str_monster_name_4910301 = "Sinsa",
  str_monster_name_4910301_en = "Sinsa",
  str_monster_desc_4910301 = "Líder franco de Rediesel Wrench que está increíblemente unido a sus miembros y es muy protector de su hermana menor. Se dedica a asegurar la supervivencia del grupo.",
  str_monster_ability_4910301 = "Un poderoso atacante cuya fuerza se transforma después de la derrota de Eve.",
  str_monster_name_4911051 = "Eve",
  str_monster_name_4911051_en = "Eve",
  str_monster_desc_4911051 = "La hermana menor de Sinsa que cayó bajo la influencia Eclipsite y perdió el control cuando era niña. Ha recuperado su inocencia después de ser sanada.",
  str_monster_ability_4911051 = "Capaz de ataques de precisión y daño de área amplia.",
  str_monster_ability_4900141 = "Se destaca en los ataques cuerpo a cuerpo y tiene la capacidad de convocar a otros Eclipsites. Después de que se vuelve rabioso, sus ataques normales infligen daño dos veces con un rango de habilidad muy mejorado.",
  str_monster_ability_4900181 = "Sobresale en ataques a distancia que aturdirán al objetivo e invocarán Eclipsites. Después de que se vuelve rabioso, sus ataques normales infligen daño dos veces con un rango de habilidad muy mejorado.",
  str_monster_passiveskill_name_21500781 = "Vínculo entre hermanos",
  str_monster_passiveskill_desc_21500781 = "Robyn se vuelve más poderosa cuando Dayna es derrotada.",
  str_monster_ability_4900641 = "Sobresale en el uso de ataques de área grande. Bloquea los elementos de los mosaicos a su alrededor después de que se mueve.",
  str_monster_ability_4900661 = "Shatterblast aplastará las fichas al comienzo de la batalla. Este ataque puede derribar objetivos.",
  str_monster_name_2903801 = "Astor",
  str_monster_name_2903801_en = "Astor",
  str_monster_desc_2903801 = "Un espíritu femenino itinerante sin dueño ni voluntad propia; Aparte de su apariencia femenina, todo lo que queda es una terrible enemistad hacia los vivos. A través de siniestros rituales, este espíritu puede combinarse con Darkflow para crear una poderosa entidad sobrenatural.",
  str_monster_ability_2903801 = "Alborota a través de un área designada y absorbe la energía de Deathly Candles para fortalecerse.",
  str_monster_ability_39038011 = "Arrasa a través de un área designada, evocando la energía de Deathly Candles para causar daño.",
  str_monster_passiveskill_name_2903801 = "Deseo a la luz de las velas",
  str_monster_passiveskill_desc_2903801 = "Cuando no hay Aurorianos dentro del rango de ataque, Astor comienza a encender Velas de la Muerte cercanas (si todas las Velas de la Muerte están encendidas, Astor recupera el 20% de su HP máximo).\nAdemás, cada vela de la muerte encendida otorga a Astor una reducción del daño del 10 %.",
  str_monster_passiveskill_name_39038011 = "Deseo a la luz de las velas",
  str_monster_passiveskill_desc_39038011 = "Cuando no hay Aurorianos dentro del rango de ataque, Astor comienza a encender Velas de la Muerte en el campo de batalla.\nSi todas las velas de la muerte están encendidas, Astor inflige un gran daño a los aurorianos.",
  str_monster_passiveskill_name_39038012 = "Deseo a la luz de las velas",
  str_monster_passiveskill_desc_39038012 = "Cuando no hay Aurorianos dentro del rango de ataque, Astor comienza a encender Velas de la Muerte en el campo de batalla.\nSi todas las velas de la muerte están encendidas, Astor inflige un gran daño a los aurorianos.\nSi no se encienden todas las velas de la muerte, Astor inflige una pequeña cantidad de daño a los aurorianos.",
  str_monster_passiveskill_name_2903802 = "Deseo a la luz de las velas",
  str_monster_passiveskill_desc_2903802 = "Cuando no hay Aurorianos dentro del rango de ataque, Astor comienza a encender Velas de la Muerte cercanas (si todas las Velas de la Muerte están encendidas, Astor recupera el 20% de su HP máximo).\nAdemás, cada Vela de la Muerte encendida aumenta la reducción de daño de Astor, y cada Vela de la Muerte apagada aumenta el ATK de Astor.",
  str_monster_name_2903600 = "Flor Diavola",
  str_monster_name_2903601 = "diávola",
  str_monster_name_2903601_en = "Diavola",
  str_monster_desc_2903601 = "A Diavola le gusta esconderse y eliminar sigilosamente a sus enemigos con veneno.",
  str_monster_ability_2903601 = "Diavola no puede moverse. Tiene una fuerte resistencia, su cuerpo envuelto en espinas venenosas. Sus flores pueden atraer a Dawn Sprites, pero también exponen su debilidad.",
  str_monster_desc_2000609 = "Una ilusión creada por Diavola que contiene un poder mágico.",
  str_monster_ability_2000609 = "Se une a Diavola y aumenta su ATK cuando está dentro de 1 grupo circundante de Diavola.",
  str_monster_passiveskill_name_2903600 = "Prevención de daños",
  str_monster_passiveskill_desc_2903600 = "Las flores de Diavola solo pueden dañarse con habilidades de francotirador y son inmunes a los ataques normales y al daño de área. Cuando a sus flores les quedan cero HP, Diavola queda paralizada y ya no inflige toxina a los aurorianos.",
  str_monster_passiveskill_name_2903601 = "Corrosión",
  str_monster_passiveskill_desc_2903601 = "Cuando se despierta, Diavola contraataca todos los ataques normales e inflige 1 acumulación de toxina a los aurorianos.",
  str_monster_passiveskill_name_2000609 = "Curar",
  str_monster_passiveskill_desc_2000609 = "Cuando Dawn Sprite es derrotado, restaura una pequeña cantidad de HP del equipo y reduce la cantidad de acumulaciones de Toxin del equipo.",
  str_monster_passiveskill_desc_2000639 = "Restaura un mínimo de HP a Dawn Sprite después de que sea derrotado por Aurorians.",
  str_monster_name_2001901 = "Espíritu de linterna",
  str_monster_name_2001901_en = "Lantern Spirit",
  str_monster_desc_2001901 = "Un Eclipsite que fue modificado por Asmodeus. Sus deseos están controlados por Asmodeus, por lo que obedece todas sus órdenes.",
  str_monster_ability_2001901 = "Los ataques crean cadenas que hacen que tanto el daño recibido como el HP recuperado entre las partes vinculadas se compartan.",
  str_monster_passiveskill_name_2001901 = "Cadenas",
  str_monster_passiveskill_desc_2001901 = "Cuando cualquiera de las partes conectadas por la cadena recibe daño o recupera HP, la otra parte recibirá la misma cantidad de daño o recuperará la misma cantidad de HP. Cuando la cadena está conectada a un Aurorian, se romperá después de exceder cierta longitud.",
  str_monster_passiveskill_name_2001902 = "teletransportarse",
  str_monster_passiveskill_desc_2001902 = "El espíritu de la linterna puede teletransportarse si puede atravesar la casilla en la que se encuentra el auroriano y moverse a la casilla del otro lado.",
  str_monster_name_2903401 = "asmodeo",
  str_monster_name_2903401_en = "Asmodeus",
  str_monster_desc_2903401 = "El poderoso Wraith tiene la aterradora habilidad de ver a través de todos los deseos de sus oponentes y disfruta manipulándolos.",
  str_monster_ability_2903401 = "Cuando el Asmodeus inmune al daño de ataque normal y el Asmodeus inmune al daño de habilidad están ambos en el campo, su HP se comparte a través de Chain of Desire, y también puede torturar a su presa con su Chain of Nightmares.",
  str_monster_passiveskill_name_29034001 = "Asmodeus: Cadena del deseo",
  str_monster_passiveskill_desc_29034001 = "Cuando cualquiera de los Asmodeus conectados por la Cadena del Deseo recibe daño o recupera HP, el otro Asmodeus recibirá la misma cantidad de daño o recuperará la misma cantidad de HP. Después de que Asmodeus actúe, se generarán Regiones Oscuras bajo la Cadena del Deseo.",
  str_monster_passiveskill_name_29034002 = "Asmodeus: Cambiar",
  str_monster_passiveskill_desc_29034002 = "Antes de que Asmodeus actúe, sus dos cuerpos pueden cambiar de posición para que le resulte más fácil cazar objetivos.",
  str_monster_passiveskill_name_2903401 = "Asmodeus: Cadena de pesadillas",
  str_monster_passiveskill_desc_2903401 = "Los aurorianos conectados por la Cadena de Pesadillas recibirán daño por cada mosaico que atraviesen. Dejar el rango efectivo de la Cadena de Pesadillas la romperá.",
  str_monster_passiveskill_name_2903411 = "Asmodeus: separación del alma",
  str_monster_passiveskill_desc_2903411 = "Cuando se corta el vínculo entre los Aurorianos y la Cadena de Pesadillas, los Aurorianos reciben un gran daño.",
  str_monster_name_2903501 = "cerrito",
  str_monster_name_2903501_en = "Cerritus",
  str_monster_desc_2903501 = "El nuevo Eclipsite encontrado durante la exploración parece ser una variante de un poderoso Eclipsite, excepto que está más trastornado y es mucho más destructivo.",
  str_monster_ability_2903501 = "Cerritus ataca a los aurorianos embistiéndolos y tiene la poderosa habilidad de invocar guijarros y cambiar el terreno. Cerritus se fortalece a medida que avanza la batalla. ¡Los ataques que no matan a Cerritus solo lo hacen más fuerte! Cada pocas rondas, Cerritus ruge enojado y entra en un estado de locura.",
  str_monster_passiveskill_name_29034011 = "Cerritus: Aullido enojado",
  str_monster_passiveskill_desc_29034011 = "Cada 2 rondas, Cerritus aúlla enojado y se cura, ganando ATK y movimiento pero perdiendo DEF. Al mismo tiempo, convoca a Pebbles por todo el campo.",
  str_monster_passiveskill_name_29034012 = "Cerritus: Aullido enojado",
  str_monster_passiveskill_desc_29034012 = "Cada 2 rondas, Cerritus aúlla enojado y se cura, ganando ATK y movimiento pero perdiendo DEF. Al mismo tiempo, convoca a Pebbles por todo el campo.",
  str_monster_passiveskill_name_2903501 = "Cerritus: Aullido enojado",
  str_monster_passiveskill_desc_2903501 = "Cada 2 rondas, Cerritus aúlla enojado y se cura, ganando ATK y movimiento pero perdiendo DEF. Al mismo tiempo, convoca a Pebbles por todo el campo.",
  str_monster_passiveskill_desc_2903504 = "Cada 2 rondas, Cerritus aúlla enojado y se cura, ganando ATK y movimiento. Al mismo tiempo, convoca a Pebbles por todo el campo.",
  str_monster_ability_9200164 = "Utiliza una lanza para atacar objetivos y puede mejorar otros Eclipsites.",
  str_monster_name_21600381 = "Phantom",
  str_monster_name_2902902 = "Jormungand",
  str_monster_name_2902902_en = "Jormungand",
  str_monster_desc_2902902 = "Un Eclipsite nacido en las condiciones extremas del fin de los días. Tiene una figura distorsionada y hace tiempo que perdió la capacidad de pensar inteligentemente. Lo único que le queda son las ganas de seguir avanzando y devorando todo a su paso.",
  str_monster_ability_2902902 = "La estructura del cuerpo de Jormungand le permite replicarse en cualquier momento. Devora cualquier obstáculo en su camino, incluso su propio cuerpo.",
  str_monster_passiveskill_name_2902902 = "Jormungand: Insaciable",
  str_monster_passiveskill_desc_2902902 = "Jormungand ataca de nuevo cada vez que un Aurorian usa una Habilidad Activa.",
  str_monster_passiveskill_name_2902901 = "Jormungand: replicación",
  str_monster_passiveskill_desc_2902901 = "Al comienzo de la ronda de los monstruos, Jormungand se autorreplica, creciendo en longitud en 1 nuevo segmento.",
  str_monster_passiveskill_name_2900251 = "Esquivar",
  str_monster_passiveskill_desc_2900251 = "Se mueve con extrema agilidad y tiene la posibilidad de esquivar ataques. (No se puede esquivar cuando está paralizado).",
  str_monster_name_2002001 = "venomex",
  str_monster_desc_2002001 = "Se dice que es un pariente lejano de una especie de Eclipsite capaz de autodetonarse, excepto que esta variedad puede lanzar bolas de baba venenosas que causan un daño significativo a los organismos vivos.",
  str_monster_ability_2002001 = "Rocía veneno en línea recta o en la ubicación de un auroriano, lo que inflige veneno al enemigo y sus aliados dentro del alcance del veneno.",
  str_monster_ability_2904201 = "Tiene la capacidad de atacar a los aurorianos a distancia y puede lanzar ataques a pantalla completa. Puede invocar fantasmas que no pueden atacar pero rodean a los aurorianos.",
  str_monster_passiveskill_name_2904201 = "Engaño",
  str_monster_passiveskill_desc_2904201 = "Cuando termina la invencibilidad, se invocan 2 Fantasmas de Dreamwalker para rodear a los Aurorianos. Los fantasmas no pueden atacar y no pueden ser atacados.",
  str_monster_passiveskill_desc_2904203 = "Cuando termina la invencibilidad, se invocan 2 Fantasmas Dreamwalker para rodear a los Aurorianos. Los fantasmas no pueden ser atacados.",
  str_monster_name_2904001 = "bennuguardian",
  str_monster_name_2904001_en = "Bennuguardian",
  str_monster_desc_2904001 = "Un antiguo guardián que reside en las profundidades del Territorio Secreto, despertado debido a los frecuentes disturbios de los intrusos. Incluso los Eclipsites tienen miedo de sus poderosas habilidades. Deambula por el campo de batalla sin rumbo fijo.",
  str_monster_ability_2904001 = "Posee un gran poder. Acumula Furia cuando es atacado. Cuando Fury alcanza cierto nivel, entra en un estado Enfurecido, lo que reduce el daño recibido y lanza poderosas habilidades adicionales. Si Bennuguardian es invencible cuando entra en acción, consumirá su energía regenerativa para recuperar su HP completo.",
  str_monster_name_2904202 = "Dreamwalker Ilusión",
  str_monster_passiveskill_name_29040011 = "Bennu Renacimiento",
  str_monster_passiveskill_desc_29040011 = "Si Bennuguardian es invencible cuando entra en acción, consumirá su energía regenerativa para recuperar su HP completo. Sus acumulaciones de Furia se eliminan al mismo tiempo.",
  str_monster_passiveskill_name_29040012 = "furia de bennu",
  str_monster_passiveskill_desc_29040012 = "Bennuguardian acumula Furia cuando es atacado. Cuando Fury llega a 50 acumulaciones, entra en un estado Enfurecido, lo que reduce el daño recibido y lanza una poderosa habilidad de ataque adicional después de actuar en cada ronda. Después de lanzar esta habilidad, el estado Enfurecido de Bennuguardian se desvanece.",
  str_monster_name_2002101 = "Engañar",
  str_monster_name_2002101_en = "Cozen",
  str_monster_desc_2002101 = "Posee una notable habilidad para mezclarse con su entorno. A veces, incluso parece una trampa ordinaria. Sin embargo, una vez que se revela, estalla en un alboroto asesino.",
  str_monster_ability_2002101 = "Suele esconderse en Crud. Cuando termina la cuenta regresiva, aparece y ataca a los aurorianos.",
  str_monster_passiveskill_name_2002101 = "crud",
  str_monster_passiveskill_desc_2002101 = "Cuando termina la cuenta regresiva de Crud, aparece Cozen y ataca a los aurorianos.",
  str_monster_name_2904301 = "Regal",
  str_monster_name_2904401 = "Requiem",
  str_monster_name_2904501 = "Frostfire",
  str_monster_name_2904601 = "Mythos",
  str_monster_name_2904301_en = "Regal",
  str_monster_name_2904401_en = "Requiem",
  str_monster_name_2904501_en = "Frostfire",
  str_monster_name_2904601_en = "Mythos",
  str_monster_passiveskill_name_2904301 = "Escarcha regia",
  str_monster_passiveskill_desc_2904301 = "Tiene la capacidad de contraatacar. Gana 1 acumulación de Vis cada vez que los Aurorianos lanzan Habilidades Activas. Cuando Vis llega a 10 acumulaciones, gana un efecto de aumento de ATK acumulable al comienzo de la ronda de los monstruos. Dura hasta el final de la batalla.",
  str_monster_passiveskill_name_2904401 = "Réquiem Taboo Breaker",
  str_monster_passiveskill_desc_2904401 = "Tiene la capacidad de contraatacar. Gana 1 acumulación de Vis cada vez que los Aurorianos lanzan Habilidades Activas. Cuando Vis llega a 10 acumulaciones, lanza un ataque a pantalla completa al comienzo de la ronda de los monstruos, que inflige daño a todos los objetivos.",
  str_monster_passiveskill_name_2904501 = "Frost Fire: El accidente",
  str_monster_passiveskill_desc_2904501 = "Tiene la capacidad de contraatacar. Gana 1 acumulación de Vis cada vez que los Aurorianos lanzan Habilidades Activas. Cuando Vis llega a 10 acumulaciones, marca un área del campo y, al comienzo de la ronda de los monstruos, desata un daño severo en el área marcada.",
  str_monster_passiveskill_name_2904601 = "Canción infantil: La caza",
  str_monster_passiveskill_desc_2904601 = "Tiene la capacidad de contraatacar. Gana 1 acumulación de Vis cada vez que los Aurorianos lanzan Habilidades Activas. Cuando Vis llega a 10 acumulaciones, marca un área del campo y, al comienzo de la ronda de los monstruos, desata un daño severo en el área marcada.",
  str_monster_name_2904101 = "Yoh",
  str_monster_name_2904101_en = "Yoh",
  str_monster_desc_2904101 = "Una vez que el líder del pez serpiente, fue esclavizado por los aurorianos para que sirviera como herramienta de navegación. Años de creciente odio lo han convertido en un poderoso maníaco.",
  str_monster_ability_2904101 = "Posee poderosas habilidades mágicas y puede controlar proyectiles para infligir daño a los enemigos.",
  str_monster_name_2002202 = "Palabra",
  str_monster_desc_2002202 = "Yoh proyecta palabras en su mente a la realidad para atacar a sus enemigos.",
  str_monster_ability_2002202 = "Cuando la ilusión no está activa, Yoh controla las \"Palabras\", lanzándolas como proyectiles para golpear directamente a los aurorianos. (Los aurorianos pueden destruir proyectiles durante este período para evitar recibir daño).",
  str_monster_desc_49031011 = "Integrante del equipo técnico de Rediesel Wrench que confía mucho en su tecnología de comunicaciones. Le gusta quejarse y gritar a los demás en el Canal de Comunicación, pero se pone nerviosa cuando hay problemas.",
  str_monster_ability_4903103 = "Siempre se mueve a la ubicación más lejana del objetivo. La habilidad inflige daño de gran área. La habilidad cargable inflige daño a pantalla completa y repele a los objetivos.",
  str_monster_ability_4900232 = "Vani puede usar Energía para atacar desde la distancia.",
  str_monster_passiveskill_name_48004341 = "Reanimar",
  str_monster_passiveskill_desc_48004341 = "Mara Sol recupera el 50% de HP cuando está cerca de la muerte, y luego gana la capacidad de contraatacar, pero también recibe más daño. Esta habilidad pasiva solo se puede activar una vez.",
  str_monster_passiveskill_name_48004342 = "Abismo",
  str_monster_passiveskill_desc_48004342 = "Entra en vigor después de que Mara Sol reviva. Cada vez que un auroriano lanza una habilidad activa, Mara Sol invoca un abismo en el campo.",
  str_monster_ability_4000124 = "Un Eclipsite con habilidades de invocación de bajo nivel. Incapaz de moverse por sí mismo y lucha invocando Chasms.",
  str_monster_name_2002301 = "Asistente afónico",
  str_monster_desc_2002301 = "Posible un cierto tipo de \"mentor\" de Eclipsite, ya que ambos curan a otros Eclipsites. La diferencia es que es más probable que este Eclipsite permanezca cerca de sus aliados más voluminosos para aprovechar al máximo el efecto especial de su habilidad.",
  str_monster_ability_2002301 = "El Asistente Afónico se mueve hacia la dirección con el mayor número de Eclipsites. Puede restaurar el HP de otros Eclipsites. Cuantas más casillas ocupen otros Eclipsites dentro del rango de habilidad del Asistente Afónico, más fuerte será el efecto de su curación.",
  str_monster_name_2904801 = "Gusano de arena rosa",
  str_monster_name_2904801_en = "Pink Sandworm",
  str_monster_desc_2904804 = "Un raro gusano de arena nativo del desierto de Rediesel. Está cubierto de escamas rosadas debido a una mutación única, lo que lo hace más poderoso y feroz que otros gusanos de arena. Debido a su apariencia rara y especial, ciertos prevaricadores sin escrúpulos han afirmado que sus escamas son tesoros raros que pueden convertirse en una poción mágica que puede hacer realidad todos los deseos, pero en realidad, son solo escamas rosadas ordinarias sin ninguna funcionalidad especial. .",
  str_monster_ability_2904801 = "Perfora el suelo para encontrar la ubicación de su objetivo y luego sale a la luz. Sobresale en escupir arena negra para atacar objetivos frente a ella.",
  str_monster_name_2904701 = "Cazador mecánico",
  str_monster_name_2904701_en = "Mechanical Huntsman",
  str_monster_desc_2904701 = "Un antiguo guardián creado con el único propósito de proteger los secretos de esta tierra. Es difícil escapar de sus ataques, y también tiene una autorrecuperación increíble para seguir funcionando a lo largo de los siglos. Nadie querrá afrontarlo solo.",
  str_monster_ability_2904701 = "Crea una zona protegida dentro de 2 grupos circundantes de sí mismo cada ronda. Los aurorianos dentro de la zona protegida recibirán daño adicional cada vez que ataquen o se muevan. Si Mechanical Huntsman es invencible cuando entra en acción, consumirá su energía regenerativa para recuperar su HP completo.",
  str_monster_name_2904901 = "los cuatro caballeros",
  str_monster_name_2904901_en = "los cuatro caballeros",
  str_monster_desc_2904901 = "Aunque parecen miembros ordinarios de un jurado, los cascos de yeso que llevan en la cabeza los hacen parecer muy sospechosos. ¡Resulta que hay eclipses escondidos debajo de ellos! Lo confuso es que parecen estar siguiendo las instrucciones de alguien...",
  str_monster_ability_2904901 = "Los Cuatro Caballeros tienen poderosos ataques y magníficas habilidades de teletransporte. Cada vez que 1 de los Cuatro Caballeros sea atacado o recupere HP, los otros caballeros recibirán la misma cantidad de daño o recuperarán la misma cantidad de HP.",
  str_monster_passiveskill_name_2904901 = "Los cuatro caballeros: mutuo",
  str_monster_passiveskill_desc_2904901 = "Cada vez que 1 de los Cuatro Caballeros sea atacado o recupere HP, los otros caballeros recibirán la misma cantidad de daño o recuperarán la misma cantidad de HP.",
  str_monster_name_2905501 = "demonio hati",
  str_monster_name_2905501_en = "demonio hati",
  str_monster_desc_2905501 = "Los recuerdos del pasado inundaron su corazón, creando al temible Demon Hound cuando el odio tomó el control.",
  str_monster_ability_2905501 = "Cuando Demon Hati está al borde de la muerte, puede consumir energía regenerativa para recuperar su HP completo. Ella también lanzará una poderosa habilidad y se mejorará a sí misma. Demon Hati inflige más daño a medida que su HP disminuye y contrarresta las habilidades activas.",
  str_monster_ability_2905502 = "Demon Hati consume una parte de su HP para atacar y recupera una parte de su HP perdido si se golpea a algún Aurorian. Demon Hati inflige más daño a medida que su HP disminuye.",
  str_monster_ability_2905503 = "Cuando Demon Hati está al borde de la muerte, puede consumir energía regenerativa para recuperar su HP completo. Ella también lanzará una poderosa habilidad y se mejorará a sí misma. Demon Hati inflige más daño a medida que su HP disminuye.",
  str_monster_ability_2905504 = "Cuando Demon Hati está al borde de la muerte, puede consumir energía regenerativa para recuperar su HP completo. Ella también lanzará una poderosa habilidad y se mejorará a sí misma. Demon Hati inflige más daño a medida que su HP disminuye y contrarresta las habilidades activas.",
  str_monster_passiveskill_name_2905501 = "Demon Hati: Recuperación",
  str_monster_passiveskill_desc_2905501 = "Cuando Demon Hati tiene HP bajo, consume energía regenerativa para recuperar su HP completo.",
  str_monster_passiveskill_name_2905502 = "Demon Hati: Llamas abisales",
  str_monster_passiveskill_desc_2905502 = "Cada vez que Demon Hati consume energía regenerativa, se convierte en Demon Hati: Ominous Flame esta ronda, se teletransporta junto a los aurorianos y consume el 15% de su HP actual para infligir un daño masivo a los aurorianos. Si golpea a un objetivo, recupera el 15% de su HP perdido.",
  str_monster_passiveskill_name_2905503 = "Demon Hati: Sustento",
  str_monster_passiveskill_desc_2905503 = "Demon Hati recupera parte de su HP perdido cuando inflige daño a los Aurorianos.",
  str_monster_passiveskill_name_2905504 = "Demon Hati: Feral",
  str_monster_passiveskill_desc_2905504 = "Cuanto menor sea el HP de Demon Hati, mayor será el daño infligido por la habilidad.",
  str_monster_passiveskill_name_2905505 = "Demon Hati: tomar represalias",
  str_monster_passiveskill_desc_2905505 = "Cada vez que un auroriano usa una habilidad activa, Demon Hati se teletransporta a los aurorianos lo más cerca posible dentro de 1 grupo circundante y luego ataca a los objetivos dentro de 1 grupo circundante.",
  str_monster_passiveskill_name_2905506 = "Demon Hati: tomar represalias",
  str_monster_passiveskill_desc_2905506 = "Cada vez que un auroriano usa una habilidad activa, Demon Hati se teletransporta a los aurorianos lo más cerca posible dentro de 2 grupos circundantes y luego ataca a los objetivos dentro de 1 grupo circundante.",
  str_monster_name_2905101 = "Taladrador",
  str_monster_name_2905101_en = "Driller",
  str_monster_desc_2905101 = "Un robot de combate desarrollado por Illumina. Se ha desempeñado extremadamente bien en las pruebas internas, pero aún no se ha probado en combate real.",
  str_monster_ability_2905101 = "Driller tiene 2 estados. Se mueve por el campo en su estado normal y cava una cierta cantidad de campos de energía y campos de apoyo en cada ronda. Cuando hay una cierta cantidad de campos de energía en el campo, absorbe y ensambla una plataforma de perforación.",
  str_monster_name_2905102 = "Plataforma de perforación",
  str_monster_name_2905102_en = "Driller Platform",
  str_monster_name_2905001 = "reina araña",
  str_monster_name_2905001_en = "Spider Queen",
  str_monster_desc_2905001 = "Este eclipse especial se parece a las arañas y ha aprendido el comportamiento de los grupos de arañas durante su camino evolutivo. Se esconde en la oscuridad donde la luz del sol no puede llegar.",
  str_monster_ability_2905001 = "Al poseer fuertes habilidades reproductivas, teje telas de araña en un entorno de caza.",
  str_monster_name_2002401 = "Cría de araña",
  str_monster_desc_2002401 = "Descendientes de la Reina Araña que tienen una autoconciencia débil y siguen todas sus órdenes.",
  str_monster_ability_2002401 = "Siguiendo las órdenes de la Reina Araña, las crías de araña se reúnen y atacan a sus presas en grupo.",
  str_monster_passiveskill_name_2002401 = "Rastreo web",
  str_monster_passiveskill_desc_2002401 = "Las crías de araña solo se arrastran por la red y crearán su propio camino cuando no tengan adónde ir.",
  str_monster_name_2905201 = "Figerald",
  str_monster_name_2905201_en = "Figerald",
  str_monster_desc_2905201 = "Como uno de los Espectros más poderosos, ataca con todas sus fuerzas cuando su estatus se ve amenazado.",
  str_monster_ability_2905201 = "Tiene el poder de destruir el medio ambiente y siempre se mantiene a cierta distancia de los Aurorianos.",
  str_monster_name_2002501 = "Soldados Illumina",
  str_monster_desc_2002501 = "Soldados de combate comunes en el ejército de Illumina, conocidos por su habilidad con rifles y cuchillos de combate, así como por su tenacidad, ética de trabajo, proactividad en la batalla y espíritu de lucha intrépido.",
  str_monster_ability_2002501 = "Usa más ataques a distancia. Cuando la batalla se intensifica, acércate rápidamente a los enemigos y enfréntalos en combate cuerpo a cuerpo para acabar con ellos lo antes posible.",
  str_monster_ability_2002502 = "Un hábil combatiente cuerpo a cuerpo con la capacidad de detectar y reaccionar ante los movimientos del enemigo durante intensas batallas, lo que permite contraataques efectivos.",
  str_monster_passiveskill_name_200250103 = "Tenacidad de batalla",
  str_monster_passiveskill_desc_200250103 = "Cuando HP es inferior al 50%, todos los ataques con armas se convertirán en ataques cuerpo a cuerpo con un cuchillo de combate. Al mismo tiempo, todos los moretones acumulados se convertirán en HP restaurado y aumentarán ATK y DEF.",
  str_monster_passiveskill_name_200250113 = "Contraataque agudo",
  str_monster_passiveskill_desc_200250113 = "Cada vez que el enemigo usa una Habilidad Activa, los Soldados de Illumina avanzan 1 casilla y atacan.",
  str_monster_name_2905301 = "Estado de prueba Helios",
  str_monster_name_2905301_en = "Estado de prueba Helios",
  str_monster_desc_2905301 = "Después de vivir solo durante más de una década en la Zona Oscura, este soldado de Illumina se ha olvidado de todo menos de luchar. Lo aterrador es que se ha vuelto más fuerte en la batalla después de haber sido modificado por alguien...",
  str_monster_ability_2905301 = "Una entidad que tiene fuertes habilidades de combate y acumula magulladuras al recibir daño. Cuando sus ataques fallan en su objetivo, se lanza una marca de terror en el campo. Las habilidades de Helios se vuelven más poderosas con cada marca de terror en el campo.",
  str_monster_passiveskill_name_29053011 = "Implacable.despiadado",
  str_monster_passiveskill_desc_29053011 = "Al recibir daño, Helios acumula Contusiones equivalentes al 50% del daño recibido.",
  str_monster_passiveskill_name_29053012 = "marca de terror",
  str_monster_passiveskill_desc_29053012 = "Cuando Helios' Dread Rush o Leap of Terror fallan sus objetivos, se libera una marca de terror en el campo: inflige daño al objetivo directamente y genera una marca en el mosaico en el que se encuentra el objetivo.",
  str_monster_passiveskill_name_2904701 = "Revivir: Contador",
  str_monster_passiveskill_desc_2904701 = "Si Mechanical Huntsman es invencible cuando entra en acción, consumirá su energía regenerativa para recuperar su HP completo. En la próxima ronda después de recuperarse, Mechanical Huntsman usará una habilidad extremadamente peligrosa que reduce el HP de los aurorianos dentro de la zona protegida a 1.",
  str_monster_passiveskill_name_2905102 = "Desmontaje de la plataforma del perforador",
  str_monster_passiveskill_desc_2905102 = "El Perforador y la Plataforma del Perforador tienen HP independientes. En el modo Driller Platform, los jugadores pueden atacar al Driller que se esconde detrás de la plataforma. Si la plataforma del perforador se vuelve invencible, se desarmará automáticamente para revelar al perforador.",
  str_monster_passiveskill_name_2905101 = "Control del perforador",
  str_monster_passiveskill_desc_2905101 = "Cuando Driller entra en acción, si hay 6 Campos de energía en el campo, invoca la Plataforma de Driller, que ocupa 5 casillas donde se encuentra.",
  str_monster_name_2905401 = "Joshua: alma contaminada",
  str_monster_name_2905401_en = "Joshua: Tainted Soul",
  str_monster_desc_2905401 = "La invasión de la materia malvada trae agonía y angustia implacables... Su existencia, nunca pensada para este mundo, fue provocada por ella...",
  str_monster_ability_2905401 = "Tiene un control inmenso sobre su entorno y es parcialmente resistente a los ataques y habilidades normales de los aurorianos.",
  str_monster_name_2003201 = "mimo kartima",
  str_monster_name_2003201_en = "Mime Kartima",
  str_monster_desc_2003201 = "Salvaguardaré el honor de Kartimas.",
  str_monster_ability_2003201 = "Mientras sostiene un escudo para defenderse, Mime Kartima cambiará hábilmente entre un mayal y un escudo para golpear al objetivo de acuerdo con su posición.",
  str_monster_name_2003202 = "Guardia de martillo de Lumópolis",
  str_monster_name_2003202_en = "Lumopolis Hammerguard",
  str_monster_desc_2003202 = "Revisado: Los guardianes de élite de Lumopolis, sus impenetrables escudos y armaduras se alzan como fortalezas, mientras que el estruendoso martillo golpea resonando como poderosas avalanchas.",
  str_monster_ability_2003202 = "Mientras sostiene un escudo para defenderse, Mime Kartima cambiará hábilmente entre un mayal y un escudo para golpear al objetivo de acuerdo con su posición.",
  str_monster_passiveskill_name_200320105 = "Kartima: Guarda escudo",
  str_monster_passiveskill_desc_200320105 = "Kartima blande su escudo, reduciendo el daño de los ataques frontales. Pierde efecto cuando está aturdido, asustado, paralizado o infligido con otros efectos de control.",
  str_monster_passiveskill_name_200320106 = "Kartima: Inflexible",
  str_monster_passiveskill_desc_200320106 = "Kartima es inmune al aturdimiento, el miedo, la parálisis y otros efectos de control durante 2 rondas después de unirse a la batalla.",
  str_monster_passiveskill_desc_200320107 = "Kartima es inmune al aturdimiento, el miedo, la parálisis y otros efectos de control durante 1 ronda después de unirse a la batalla.",
  str_monster_passiveskill_desc_200320108 = "Kartima es inmune al aturdimiento, el miedo, la parálisis y otros efectos de control durante 3 rondas después de unirse a la batalla.",
  str_monster_passiveskill_desc_200320109 = "Kartima es inmune a Stun, Frighten, Paralysis y otros efectos de control durante 5 rondas después de unirse a la batalla.",
  str_monster_passiveskill_name_200320205 = "Guardia de escudo",
  str_monster_passiveskill_desc_200320205 = "Lumopolis Hammerguard blande su escudo, lo que reduce el daño de los ataques frontales. Pierde efecto cuando está aturdido, asustado, paralizado o infligido con otros efectos de control.",
  str_monster_passiveskill_name_200320206 = "Inflexible",
  str_monster_passiveskill_desc_200320206 = "Inmune al aturdimiento, miedo, parálisis y otros efectos de control durante 2 rondas después de unirse a la batalla",
  str_monster_passiveskill_desc_200320207 = "Inmune al aturdimiento, miedo, parálisis y otros efectos de control durante 1 ronda después de unirse a la batalla",
  str_monster_passiveskill_desc_200320208 = "Inmune al aturdimiento, miedo, parálisis y otros efectos de control durante 3 rondas después de unirse a la batalla",
  str_monster_passiveskill_name_39002111 = "Llamada de piedra",
  str_monster_passiveskill_desc_39002111 = "Umbrahulk invoca Pebbles al azar en el campo de batalla al final de cada ronda",
  str_monster_passiveskill_name_3900452 = "Poder abandonado",
  str_monster_passiveskill_desc_3900452 = "Cuando los monstruos Renegados reciben daño, el efecto del contador de elementos aumenta en un 100%.\nLos monstruos abandonados se mejorarán continuamente según el daño que reciban.",
  str_monster_passiveskill_name_3900453 = "Poder abandonado",
  str_monster_passiveskill_desc_3900453 = "Los monstruos abandonados se mejorarán continuamente según el daño que reciban.",
  str_monster_name_2904804 = "Abandonado: Gusano de arena rosa",
  str_monster_name_2904804_en = "Abandonado: Gusano de arena rosado",
  str_monster_name_4904901 = "Abandonado: Los Cuatro Caballeros",
  str_monster_name_4904901_en = "Forsaken: The Four Knights",
  str_monster_name_39038011 = "Abandonado: Astor",
  str_monster_name_39038011_en = "Forsaken: Astor",
  str_monster_name_3100311 = "Abandonado: Augean",
  str_monster_name_3100311_en = "Forsaken: Augean",
  str_monster_desc_3900311 = "Abandonado: Augean se vuelve inmune a todos los ataques de Aurorian y convoca a un clon para enfrentarse al jugador. El daño infligido al clon se transfiere al cuerpo principal.",
  str_monster_ability_3100311 = "Revive un clon cada ronda. El clon puede atacar objetivos varias veces e infligir sangrado. Contador de movimiento: cada vez que los aurorianos usan una habilidad activa en esta ronda, el rango de movimiento del clon aumenta.",
  str_monster_name_3100312 = "Clon abandonado",
  str_monster_desc_3900312 = "1. Todo el daño recibido se transferirá completamente al cuerpo principal. No puede ser inmune al daño basado en porcentaje.\n2. El clon tendrá el mismo ATK y DEF que el cuerpo principal. El Max HP del clon aumentará de acuerdo con la cantidad de daño infligido al cuerpo principal.",
  str_monster_ability_3100312 = "Los clones pueden atacar objetivos varias veces. Contador de movimiento: el rango de movimiento del clon aumentará cada vez que los aurorianos usen una habilidad activa durante la ronda actual.",
  str_monster_name_531400511 = "Mia: Lustrous Soul",
  str_monster_name_531400511_en = "Mia: Lustrous Soul",
  str_monster_desc_531400511 = "Un caballero de Lumopolis que vive una vida aislada en Umbraton.",
  str_monster_ability_531400511 = "Obtiene un beneficio adicional de ATK cuando HP es bajo. Se otorga un escudo cada 3 rondas para resistir el daño.",
  str_monster_name_4902501 = "Abandonado: Minos",
  str_monster_name_4902501_en = "Forsaken: Minos",
  str_monster_passiveskill_name_4902501 = "Abandonado: Debilitamiento Designado",
  str_monster_passiveskill_desc_4902501 = "Genera 4 fichas debilitadas en una ficha diagonal cada ronda.",
  str_monster_passiveskill_name_4902502 = "Abandonado: Ataque Fantasma",
  str_monster_passiveskill_desc_4902502 = "Si está abandonado: si Minos pasa por una casilla mejorada o una baldosa debilitada, se invocará un fantasma para infligir daño a los Aurorians.",
  str_monster_name_4900511 = "Abandonado: Nozard",
  str_monster_name_4900511_en = "Forsaken: Nozard",
  str_monster_ability_4900511 = "indignado, Nozard golpea constantemente el suelo para derribar al jugador y convoca a Gloom Ghouls para que lo ayuden en la batalla. Nozard no recibe daño de los ataques normales.",
  str_monster_name_2905404 = "Joshua: Oscuro Angel",
  str_monster_name_2905404_en = "Joshua: Dark Angel",
  str_monster_name_2905405 = "Joshua: Demonio blanco",
  str_monster_name_2905405_en = "Joshua: White Demon",
  str_monster_name_2000255 = "Guardia lumo maldito",
  str_monster_name_2000285 = "Compañero de escudo Lumo maldito",
  str_monster_name_2000295 = "Lumo Piker maldito",
  str_monster_desc_2905404 = "Como encarnación de rencores interminables, es una parte desgarrada de las emociones de Joshua, una entidad formidable nacida en el vacío, que alberga enemistad hacia todas las almas que irradian amor.",
  str_monster_desc_2905405 = "Un ser impecable convocado desde las profundidades de la llamada de una madre. Se ha despojado de emociones inútiles para alcanzar el ideal supremo, el asesino perfecto que no se ve afectado por los sentimientos.",
  str_monster_desc_2000255 = "Una vez que fue una guardia leal de Lumopolis, ahora ha sido corrompida y enloquecida por Joshua.",
  str_monster_desc_2000285 = "Incluso el guardián más fuerte no puede resistir la corrupción del mal. May las paredes de Lumopolis sean puras una vez más.",
  str_monster_desc_2000295 = "En el pasado, decían que los portadores de lanzas tenían la peor suerte, lo que resultó ser cierto, ya que la invasión del mal los tenía como objetivos desde el principio.",
  str_monster_desc_2000606 = "Nacido de emociones negativas, este Eclipsite rastrearía a aquellos cargados de maldiciones.",
  str_monster_ability_2905404 = "Desata el poder infinito de las maldiciones, y cuando la fuerza de la maldición supere la vida otorgada por la luz, la oscuridad lo engullirá todo.",
  str_monster_ability_2905405 = "Desata el poder infinito de las maldiciones, y cuando la fuerza de la maldición supere la vida otorgada por la luz, la oscuridad lo engullirá todo.",
  str_monster_ability_2000255 = "Los guardias, dejados inconscientes por una maldición, se levantarán de nuevo cuando estén entrelazados por el Lurker o en presencia de Joshua, liberando el poder de la maldición a través de sus ataques.",
  str_monster_ability_2000285 = "Los compañeros de escudo, dejados inconscientes por una maldición, se levantarán de nuevo cuando estén entrelazados por el Lurker o en presencia de Joshua, liberando el poder de la maldición a través de sus ataques.",
  str_monster_ability_2000295 = "Pikers, dejados inconscientes por una maldición, se levantarán de nuevo cuando estén entrelazados por el Lurker o en presencia de Joshua, liberando el poder de la maldición a través de sus ataques.",
  str_monster_ability_2000606 = "Busca a los soldados malditos de Lumopolis, los posee y hace que los soldados en coma se despierten y caigan en la locura.",
  str_monster_passiveskill_name_2000255 = "Maldito",
  str_monster_passiveskill_desc_2000255 = "Cuando atacas a un Aurorian maldito, el punto de maldición sube. Pero al morir, Aurorian emite un estallido final de luz, reduciendo el punto de maldición.",
  str_monster_passiveskill_desc_4904201 = "Cuando termina la invencibilidad, se invoca 1 Fantasma para rodear a los Aurorianos.",
  str_monster_passiveskill_name_4904202 = "Renacimiento de la ilusión",
  str_monster_passiveskill_desc_4904202 = "Las ilusiones solo reciben daño de las habilidades y pueden transferir una parte del daño al Caminante de sueños. Al morir, dejan 1 baldosa rota en sus cimientos antes de revivir la siguiente ronda.",
  str_monster_passiveskill_desc_49042021 = "Las ilusiones solo reciben daño de los golpes de un solo objetivo y pueden transferir una parte del daño al Caminante de sueños. Al morir, dejan 1 baldosa rota en sus cimientos antes de revivir en la siguiente ronda.",
  str_monster_name_5900404 = "Clon de Schummer",
  str_monster_ability_4902501 = "Invoca mosaicos debilitados a su alrededor en cada ronda y absorbe mosaicos mejorados y debilitados en el campo cuando ataca. Cuantas más baldosas Minos absorbe, más peligroso es el ataque de Minos.",
  str_monster_desc_29009112 = "Un enemigo vil ha regresado una vez más, y está decidido a acabar con todos sus enemigos esta vez.",
  str_monster_passiveskill_name_29001821 = "Inesperadamente: Shadowgeist",
  str_monster_passiveskill_desc_29001821 = "Invoca a 2 Shadowgeists en una ubicación aleatoria.",
  str_monster_passiveskill_name_29001421 = "De la nada: Gloom Ghoul",
  str_monster_passiveskill_desc_29001421 = "Invoca 2 Gloom Ghouls en una ubicación aleatoria.",
  str_monster_ability_29001811 = "Hábil en ataques a distancia que aturdirán al objetivo y convocarán al Shadowgeist. Cuando está rabioso, sus ataques normales golpean dos veces con un rango de habilidad muy mejorado, y puede convocar a 2 Shadowgeists al mismo tiempo.",
  str_monster_ability_29001411 = "Experta en ataques cuerpo a cuerpo, sus ataques aturdirán al objetivo con la capacidad de invocar al Necrófago Sombrío. Cuando se vuelve Rabiosa, sus ataques normales se convierten en ataques dobles con un rango de habilidad muy mejorado, y puede invocar a 2 Necrófagos Sombríos al mismo tiempo.",
  str_monster_passiveskill_name_5900404 = "Schummer: Gemelo",
  str_monster_passiveskill_desc_5900404 = "El daño recibido por el clon de Schummer se transferirá a Schummer. Al volverse invencible, queda aturdido durante 1 asalto, luego recupera todos sus PS.",
  str_monster_name_2905601 = "Diosa Denuo",
  str_monster_name_2905601_en = "Denuo Goddess",
  str_monster_desc_2905601 = "Una mariposa extremadamente rara, se rumorea que solo aparece cerca del Valle de Denuo. Es de naturaleza reclusiva, con sentidos muy agudos. No se debe subestimar el poder de combate de las Denuo Diosas adultas.",
  str_monster_ability_2905601 = "Catalizan el crecimiento de las plantas mediante la polinización, protegiéndose a sí mismos mientras infligen un gran daño a los enemigos.",
  str_monster_name_2002601 = "Hierba Encantada Sadesiana",
  str_monster_desc_2002601 = "Inicialmente una forma de vida similar al musgo, pero después de que la Diosa Denuo usa Lumina para impulsar su crecimiento, se transformará en una planta que se asemeja a flores y hierbas.",
  str_monster_ability_2002601 = "Bajo la influencia catalítica de la Diosa Denuo, evoluciona gradualmente en una planta extremadamente mortal.",
  str_monster_name_2002602 = "Hierba Encantada Sadesiana",
  str_monster_desc_2002602 = "Inicialmente una forma de vida similar al musgo, pero después de que la Diosa Denuo usa Lumina para impulsar su crecimiento, se transformará en una planta que se asemeja a flores y hierbas.",
  str_monster_ability_2002602 = "Bajo la influencia catalítica de la Diosa Denuo, evoluciona gradualmente en una planta extremadamente mortal.",
  str_monster_name_2002603 = "Hierba Encantada Sadesiana",
  str_monster_desc_2002603 = "Inicialmente una forma de vida similar al musgo, pero después de que la Diosa Denuo usa Lumina para impulsar su crecimiento, se transformará en una planta que se asemeja a flores y hierbas.",
  str_monster_ability_2002603 = "Bajo la influencia catalítica de la Diosa Denuo, evoluciona gradualmente en una planta extremadamente mortal.",
  str_monster_name_8900181 = "Inspirador del olvido ",
  str_monster_name_8900181_en = "Oblivion Inspirer",
  str_monster_desc_8900181 = "¿Podría ser también la hermana menor de alguien? A pesar de su impulsividad y ferocidad externas, es evidente que en lo profundo hay un alma vulnerable.",
  str_monster_name_8900411 = "Caballero del Olvido",
  str_monster_name_8900411_en = "Oblivion Knight",
  str_monster_desc_8900411 = "Está envuelto en un aire de traición... junto con una lucha constante contra el destino injusto y una sed insaciable de pasión.",
  str_monster_name_8000451 = "Súbdito del Olvido",
  str_monster_name_8000451_en = "Súbdito del Olvido",
  str_monster_name_80011471 = "Perseguidor del Olvido",
  str_monster_name_80011471_en = "Perseguidor del Olvido",
  str_monster_desc_80011471 = "Ella habita entre el recuerdo y el olvido, lo que sugiere que aún se aferra a algo en este mundo.",
  str_monster_ability_533500302 = "Incapaz de moverse por sí mismo, lucha invocando Burstbugs autodestructivos.",
  str_monster_name_99005021 = "Abandonado: Solmorph",
  str_monster_name_99005021_en = "Forsaken: Solmorph",
  str_monster_name_99039011 = "Abandonado: Casta",
  str_monster_name_99039011_en = "Forsaken: Casta",
  str_monster_ability_99005021 = "Inflige daño ineludible en un área grande; posee la habilidad de cambiar el color de las casillas del tablero.",
  str_monster_ability_99039011 = "Ataca a enemigos en rango cuerpo a cuerpo con una bayoneta o los ataca desde la distancia con balas.",
  str_monster_desc_9900501 = "Evolucionó del Siphorb, absorbió tanta Lumina que es incapaz de controlar el color de la luz circundante.",
  str_monster_passiveskill_name_29060011 = "Duelo: Metamorfosis",
  str_monster_passiveskill_desc_29060011 = "Cada ronda, convoca a un Dawn Flor en una ubicación determinada para restaurar HP; cada Dawn Flower otorga un impulso de recuperación adicional.",
  str_monster_name_2906001 = "Duelo Eve",
  str_monster_name_2906001_en = "Grieving Eve",
  str_monster_desc_2906001 = "El dolor del aislamiento y el miedo a ser cortado, esos recuerdos insoportables del pasado, han dado forma a la persona conocida como Eve hoy.",
  str_monster_ability_2906001 = "Cada ronda, convoca a un Dawn Florece en una ubicación determinada en el campo de batalla, restaurando HP de acuerdo con la cantidad de Dawn flores En rondas específicas, obtenga múltiples acumulaciones de inmunidad y luego restaure HP en la ronda siguiente según las acumulaciones de inmunidad.",
  str_monster_name_2006001 = "Dawn Flor",
  str_monster_desc_2006001 = "Estas sencillas flores blancas, pequeñas y ordinarias, se encuentran entre los más preciados consuelos de su corazón.",
  str_monster_ability_2006001 = "Otorga una bonificación de recuperación de HP adicional para el duelo Eve.",
  str_monster_ability_2000401 = "Incapaz de moverse o atacar. Se vincula con el Invocador Oscuro y ofrece reducción de daño.",
  str_monster_name_2003001 = "Lanzallamas Illumina",
  str_monster_desc_2003001 = "\"Reducir a todos los adversarios a cenizas\": esto ejemplifica la eficiencia y la crueldad de las fuerzas de Illumina. Ante las llamas furiosas, toda vida se encuentra en igualdad de condiciones.",
  str_monster_ability_2003001 = "Acumula Moretones al recibir daño. Inflige daño a todos los objetivos dentro del alcance de ataque, causando Quemaduras en ellos y creando incendios.",
  str_monster_passiveskill_name_2003001 = "Pilar del campo de batalla",
  str_monster_passiveskill_desc_2003001 = "Al recibir daño, el Lanzallamas de Illumina acumula Contusiones equivalentes al 50% del daño recibido.",
  str_monster_name_2002901 = "Tanque Illumina L5",
  str_monster_desc_2002901 = "Fabricado a través de modificaciones de camiones, el Tanque Illumina L5 cuenta con una armadura ligera, lo que lo hace perfecto para la fabricación en masa. Su capacidad de carga y sus cañones de disparo rápido acaban rápidamente con las unidades ligeras enemigas.",
  str_monster_ability_2002901 = "Basándose en las posiciones enemigas, opta por disparar una ráfaga rápida de tiros o una embestida cargada para atacar.",
  str_monster_name_2003401 = "Soldado Illumina Corrompido",
  str_monster_name_2003401_en = "Soldado Illumina Corrompido",
  str_monster_desc_2003401 = "Una vez aliados, ahora enemigos, tal es el temor del Eclipse. La única misericordia que queda es darles descanso.",
  str_monster_ability_2003401 = "Crea ciénagas en las casillas por las que se mueve. Cuando tiene poca vida, aumenta significativamente el ACT y mejora la DEF.",
  str_monster_passiveskill_name_20034011 = "Mente Corrupta",
  str_monster_passiveskill_desc_20034011 = "Si el HP está por debajo del 40% al inicio de una ronda, la unidad aumenta su ACT y DEF y cambia su estilo de ataque.",
  str_monster_passiveskill_name_20034012 = "Paso Corrupto",
  str_monster_passiveskill_desc_20034012 = "Crea pantanos en las casillas por las que se mueve.",
  str_monster_name_2003101 = "Sargento de Illumina",
  str_monster_desc_2003101 = "Como oficiales de base del ejército Illumina, son responsables de dirigir a los soldados regulares en el campo de batalla. La mayoría de ellos se gradúan de academias militares, mientras que unos pocos selectos son ascendidos de las filas de veteranos experimentados.",
  str_monster_ability_2003101 = "Su presencia mejora las habilidades de los Soldados Illumina cercanos y les ayuda a recuperar de sus heridas. Si se encuentran aislados de sus aliados o en espacios cerrados con enemigos, estos sargentos toman las armas, infligiendo daño con cortes devastadores y patadas impactantes.",
  str_monster_name_2002701 = "Médico de Illumina",
  str_monster_desc_2002701 = "Dondequiera que esté el Médico Illumina, la moral se eleva, porque los compañeros saben que sus heridas no quedarán sin tratamiento. La Federación Illumina, consciente de este hecho, proporciona a estos médicos una protección mejorada, aumentando significativamente sus capacidades de supervivencia.",
  str_monster_ability_2002701 = "Un Soldado Illumina sin capacidades de combate. Restaura HP para un Soldado Illumina cercano y cura ciertas Contusiones propias.",
  str_monster_name_2002801 = "Señalero Illumina",
  str_monster_desc_2002801 = "Equipado con un comunicador compacto, el Comunicador Illumina lleva una carga pesada. Por lo tanto, la Federación Illumina ha diseñado un aparato de soporte especializado, facilitando su transmisión de señales en movimiento, lo cual es el origen del nombre de esta unidad.",
  str_monster_ability_2002801 = "Un Soldado Illumina sin capacidades de combate pero capaz de invocar refuerzos Illumina en el campo de batalla.",
  str_monster_passiveskill_name_2002701 = "Tenacidad en el campo de batalla",
  str_monster_passiveskill_desc_2002701 = "Al recibir daño, el Médico Illumina acumula Contusiones equivalentes al 50% del daño recibido. Además, su DEF aumenta a medida que su HP disminuye.",
  str_monster_name_2003301 = "Tejedor del Terror",
  str_monster_desc_2003301 = "Impulsado por una obsesión de aniquilar a todos, ignora el agotamiento de su propia energía, persiguiendo incansablemente el objetivo, incluso si eso significa avanzar gradualmente hacia su propia destrucción.",
  str_monster_ability_2003301 = "Una vez que termine el movimiento del equipo, Dreadweaver hará que el equipo cambie de posición inmediatamente, afectando el alcance de los Combos en Cadena. Cuando el HP de Dreadweaver caiga por debajo del 50%, iniciará un ritual de sacrificio: en la siguiente ronda, quemará su HP actual hasta dejarlo en solo 1 punto, infligiendo daño verdadero a los jugadores igual a múltiples veces el HP quemado.",
  str_monster_passiveskill_name_2003301 = "Manipulación psiónica",
  str_monster_passiveskill_desc_2003301 = "Una vez que termine el movimiento del equipo, Dreadweaver hará que el equipo cambie de posición inmediatamente, afectando el lanzamiento de Combos en Cadena.",
  str_monster_passiveskill_name_2003302 = "Sacrificio de Sangre",
  str_monster_passiveskill_desc_2003302 = "Cuando el HP de Dreadweaver caiga por debajo del 50%, iniciará un ritual de sacrificio. En la siguiente ronda, quemará casi todo su HP, infligiendo un enorme daño verdadero a los jugadores. Este efecto solo puede activarse una vez.",
  str_monster_name_7001098 = "Abandonado: Schummer el Aviduz",
  str_monster_name_7001098_en = "Forsaken: Schummer the Aviduz",
  str_monster_ability_7001098 = "Periódicamente invoca relámpagos. El Poder del Relámpago paralizará a los objetivos alcanzados. El Grito de Colossus puede atraer a los Aurorianos hacia el invocador.",
  str_monster_name_2906101 = "Dañado Engine VII",
  str_monster_name_2906101_en = "Corrupted Engine VII",
  str_monster_desc_2906101 = "Originalmente un mecha de combate colosal creado por Illumina, se convirtió en una de las amenazas más formidables después de que su piloto perdiera la razón debido a la contaminación por el lodo.",
  str_monster_ability_2906101 = "Carga imprudentemente hacia el Bastión Illumina, infligiendo daño a los Aurorianos en el camino.",
  str_monster_passiveskill_name_29061011 = "Reparar",
  str_monster_passiveskill_desc_29061011 = "El Engine VII corrupto con invencibilidad quedará paralizado. Durante este período, reparará sus componentes y, una vez completada la reparación, se desplegará nuevamente para el asedio.",
  str_monster_name_2905701 = "Mudbundle",
  str_monster_name_2905701_en = "Mudbundle",
  str_monster_desc_2905701 = "Se rumorea que es una creación de un miembro de Eclipse, este Eclipsite es una fusión de varias características biológicas. Crea temibles pantanos que pueden devorar todo y contaminar lo que tocan.",
  str_monster_ability_2905701 = "Crea atolladeros y sumersiones en su interior, obstruyendo e interrumpiendo los movimientos de los aurorianos en su interior, alterando el terreno.",
  str_monster_name_8002005 = "Irridon",
  str_monster_name_8002005_en = "Irridon",
  str_monster_desc_8002005 = "Jueza Jefa del Salón de Justicia de Lumo. Ella es amable, gentil, recta y dura y tiene un espíritu de entrega propia. Un lado paranoico de ella existe en su corazón, pero lo reprime.",
  str_monster_ability_8002005 = "Ubicado fuera del campo, no puede ser atacado por ataques normales. Comparte el daño con todos los enemigos en el campo.",
  str_monster_name_2003501 = "Bestia Escarcha",
  str_monster_name_2003501_en = "Bestia Escarcha",
  str_monster_desc_2003501 = "Con su pelaje y garras afiladas, este Eclipsite tiene un sorprendente parecido con una bestia salvaje, lo que lo hace muy adecuado para infiltrarse en diversas regiones fronterizas para rastrear, explorar y cazar.",
  str_monster_ability_2003501 = "Seleccionaría diferentes habilidades según la posición del Aurorian y, si su ataque no puede alcanzar a ningún Aurorian, optará por recuperar su propio HP.",
  str_monster_name_2900891 = "Irridon: Eximius",
  str_monster_name_2900891_en = "Irridon: Eximius",
  str_monster_desc_2900891 = "Heredando las sinceras enseñanzas de su padre y cumpliendo con todas sus expectativas, se ha convertido en la perfecta Irridon, ¡la más grande juez principal jamás conocida!",
  str_monster_ability_2900891 = "Antes de cada Combo en Cadena de los Aurorianos, se forma un Escudo de Luz para bloquear el daño.\nAumenta todo el daño infligido según la cantidad de acumulaciones de Prejuicio en los Aurorianos.",
  str_monster_passiveskill_name_29089011 = "Escudo de luz",
  str_monster_passiveskill_desc_29089011 = "Antes de cada Chain Combo, forma un Escudo de Luz, bloqueando daño equivalente a un porcentaje del HP máximo.",
  str_monster_passiveskill_name_29089012 = "Wrath del Juez Principal",
  str_monster_passiveskill_desc_29089012 = "Posee múltiples segmentos de HP. Al inicio de cada ronda, si ha perdido un segmento de HP en comparación con la ronda anterior, desatará el Castigo del Juez Principal, infligiendo un daño masivo.",
  str_monster_passiveskill_name_29089021 = "Transmisión de daños",
  str_monster_passiveskill_desc_29089021 = "El daño infligido a Irridon: Clones Eximius se transfiere instantáneamente a Irridon: Eximius.",
  str_monster_name_2003601 = "Espectro Carmesí",
  str_monster_desc_2003601 = "Arrogancia, prejuicio y pensamientos corruptos... se han solidificado en espectros malévolos que deambulan por Lumopolis, infiltrándose en cada rincón de esta ciudad eterna.",
  str_monster_ability_2003601 = "Puede teletransportarse a la ubicación del jugador más cercano, infligiendo múltiples golpes dañinos y haciendo retroceder al jugador. Cuanto más lejos se teletransporte, menos ataques lanzará.",
  str_monster_name_2902131 = "No. 33: El Guardián Sin Nombre",
  str_monster_name_2902131_en = "No. 33 - The Nameless Keeper",
  str_monster_desc_2902131 = "Una antigua Aurorian, guardiana de las ruinas subterráneas en Northland. Ha vivido sola durante años, incluso sus recuerdos comienzan a desvanecerse.",
  str_monster_ability_2902131 = "Capaz de realizar ataques a distancia a los Aurorians desde cualquier lugar; Puede alterar los elementos de las casillas alrededor de otros Aurorians y de sí mismo.",
  str_monster_passiveskill_name_290213101 = "Control de área",
  str_monster_passiveskill_desc_290213101 = "Después de que su acción termine en cada ronda, convierte los elementos de las casillas en los 2 cúmulos circundantes.",
  str_monster_ability_5353002 = "Competente en ataques a distancia y AoE; entra en un estado rabioso cuando HP cae por debajo del 30%, desatando continuamente habilidades de daño en pantalla completa. Contrarresta 1 habilidad activa por ronda y lanza 5 acumulaciones de escudo de conteo para autoprotección.",
  str_monster_ability_5353007 = "Inflige daño en un área específica y hace retroceder a las unidades enemigas.",
  str_monster_passiveskill_name1_2900401 = "Con Rabia",
  str_monster_passiveskill_desc1_2900401 = "Cae en un estado rabioso cuando HP es bajo: desata Colossus: Sonic Blast para ataques en pantalla completa en cada ronda.",
  str_monster_passiveskill_name2_2900401 = "Escudo devorador",
  str_monster_passiveskill_desc2_2900401 = "Se rodea con 5 acumulaciones de escudos de conteo, cada una de las cuales ofrece inmunidad al daño 1 vez (el contraataque está limitado a solo 1 vez por ronda).",
  str_monster_passiveskill_name_5353004 = "Invocación de Ghoul sombrío",
  str_monster_passiveskill_desc_5353004 = "Invoca un Gloom Ghoul en una ubicación aleatoria.",
  str_monster_name_2902801 = "Sanki",
  str_monster_name_2902801_en = "Sanki",
  str_monster_desc_2902801 = "\"Cuando el mal acecha en los cerezos en flor, el Sakae huye, abandonado por la población; solo uno de cada diez sobrevive\". Con objetivos a la vista, su batalla por venganza comienza aquí.",
  str_monster_ability_2902801 = "Sanki presume de alta movilidad, lanzando una carga rápida cada pocas rondas para acercarse a su objetivo y causar daño rápidamente. Con cada movimiento, Sanki libera Espadas Sakae en el campo, solo para recuperarlas todas en el siguiente movimiento, infligiendo un gran daño a los objetivos enemigos a lo largo de sus trayectorias.",
  str_monster_name_70011021 = "Abandonado: Sanki",
  str_monster_name_70011021_en = "Forsaken: Sanki",
  str_monster_passiveskill_name_2902801 = "Sakae: Control",
  str_monster_passiveskill_desc_2902801 = "Antes de que Sanki tome acción, libera Espadas Sakae en cuatro direcciones a través del campo, solo para recuperarlas todas en el siguiente movimiento. Las Espadas Sakae infligen un gran daño a las unidades enemigas a lo largo de sus trayectorias cuando se liberan o se recuperan.",
  str_monster_name_70011023 = "Abandonado: Brock",
  str_monster_name_70011023_en = "Forsaken: Brock",
  str_monster_desc_70011023 = "Un miembro del equipo Tornillos Sueltos de Rediesel Wrench, Brock es un cabeza caliente y seguro de sí mismo que a veces hace cosas tontas para satisfacer su naturaleza competitiva.",
  str_monster_ability_70011023 = "Con un notable ATQ y ACT, Brock también puede atraer a los enemigos a su cercanía mediante su habilidad definitiva.",
  str_monster_name_70011041 = "Abandonado: Schwartz",
  str_monster_name_70011041_en = "Forsaken: Schwartz",
  str_monster_desc_70011041 = "El gobernador de Lumopolis, el más grande gobernante, es conocido por su dedicación desinteresada. Incluso puede visitar la arena personalmente para evaluar el poderío de todos.",
  str_monster_ability_70011041 = "Schwartz aprovecha un increíble Poder del Rayo, otorgándole un temible nivel de movilidad y fuerza destructiva. Aquellos que superan su formidable prueba de fuerza son considerados como lo mejor de lo mejor.",
  str_monster_name_5352021 = "Compañero de escudo Lumo",
  str_monster_name_5352021_en = "Compañero de escudo Lumo",
  str_monster_desc_5352021 = "Guardias armados con un escudo de defensa superior. Con la capacidad de soportar duras batallas, son los fuertes muros que protegen a sus camaradas.",
  str_monster_ability_5352021 = "Un guardia valiente con extraordinarias capacidades defensivas puede convocar a otros soldados de Lumopolis para ayudar en la batalla y aumentar su moral. Empuña un poderoso escudo que puede ser utilizado para infligir devastadores ataques cuerpo a cuerpo.",
  str_monster_name_2905801 = "Emperador de la Muerte",
  str_monster_name_2905801_en = "Emperador de la Muerte",
  str_monster_desc_2905801 = "El Emperador Supremo del Caos, padre de Tohru, un veterano de muchas guerras, es una fuerza indiscutible sin importar cuándo y dónde.",
  str_monster_ability_2905801 = "Con una fuerza formidable, maneja una multitud de habilidades para atacar a los jugadores con precisión o desatar ataques de amplio alcance, mientras los derriba.",
  str_monster_passiveskill_name_2905801 = "Debilidad de Lumina",
  str_monster_passiveskill_desc_2905801 = "Los ataques normales y combos en cadena del jugador infligen daño reducido a las 5 casillas que ocupa el jefe, excluyendo la casilla central.",
  str_monster_ability_140045106 = "Usa Nails",
  str_monster_ability_150092106 = "Inflige daño a los enemigos en un área en forma de X mientras convierte las casillas rojas en contra del lanzador.",
  str_monster_ability_160103106 = "Inflige daño al enemigo más cercano mientras convierte las casillas azules en contra del lanzador.",
  str_monster_ability_160111106 = "Lucha usando cristales, infligiendo daño a todos los enemigos en el campo de batalla.",
  str_monster_ability_150009106 = "Inflige daño a enemigos dentro de un área en forma radial y puede causar Miedo a los objetivos alcanzados.",
  str_monster_ability_160120106 = "Su gigantesca armadura, llamada Pompey, puede infligir daño en un área grande y además causar daño adicional a los enemigos dentro de 1 grupo circundante.",
  str_monster_ability_160089106 = "Desata continuamente Lluvia de Espada de Pantano de Oro para infligir daño a objetivos adyacentes.",
  str_monster_name_39004031 = "Abandonado: Schummer",
  str_monster_name_39004031_en = "Abandonado: Schummer",
  str_monster_desc_39004031 = "Originalmente un Celestita, pero se unió a Eclipse y posee un enorme poder aumentado.",
  str_monster_ability_39004031 = "Experto en ataques a distancia y de área.",
  str_monster_name_39058011 = "Abandonado: Emperador de la Muerte",
  str_monster_name_39058011_en = "Abandonado: Emperador de la Muerte",
  str_monster_desc_39058011 = "El Emperador Supremo del Caos, padre de Tohru, un veterano de muchas guerras, es una fuerza indiscutible sin importar cuándo y dónde.",
  str_monster_ability_39058011 = "Con una fuerza formidable, maneja una multitud de habilidades para atacar a los jugadores con precisión o desatar ataques de amplio alcance, mientras los derriba.",
  str_monster_ability_5362001 = "Se escon. en el Lumiwall más ale. del jug.; Los ataq. pueden cambiar el elem. de la cas. en su ruta de ataque.",
  str_monster_name_5362001 = "Gronru",
  str_monster_name_5362001_en = "Gronru",
  str_monster_desc_5362001 = "Es piloto de un mecha gigante y actual oficial de tecnología de la Federación Illumina. Se dice que es un genio salido del ejército... Aunque no está especialmente interesada en luchar, le apasiona el estudio y manejo de máquinas gigantes, casi hasta la obsesión.",
  str_monster_ability_5362002 = "Experto en ataques cuerpo a cuerpo, inflige daño en un área de columna.",
  str_monster_desc_5362002 = "Integrante del equipo técnico de Rediesel Wrench que confía mucho en su tecnología de comunicaciones. Le gusta quejarse y gritar a los demás en el Canal de Comunicación, pero se pone nerviosa cuando hay problemas.",
  str_monster_ability_5362003 = "Experto en ataques de área a distancia, sus habilidades infligen Veneno.",
  str_monster_name_2909001 = "Rey Tritón",
  str_monster_name_2909001_en = "Rey Tritón",
  str_monster_desc_2909001 = "Del mundo superficial al pueblo submarino, un noble dominante y villano.",
  str_monster_ability_2909001 = "Los ataques infligen retroceso. Puede invocar cañones de salva en el borde del campo de batalla.",
  str_monster_passiveskill_name_290900101 = "Despliegue de artillería salvo",
  str_monster_passiveskill_desc_290900101 = "Al comienzo de cada ronda de jugador, si hay menos de 2 Salvo Guns en el campo de batalla, invoca 4 Salvo Guns en el borde del campo de batalla.",
  str_monster_passiveskill_name_290901101 = "Despliegue de artillería salva",
  str_monster_passiveskill_desc_290901101 = "Al comienzo de cada ronda de jugador, si hay menos de 3 Salvo Guns en el campo de batalla, invoca 4 Salvo Guns en el borde del campo de batalla.",
  str_monster_name_70011101 = "Abandonados: Diávola",
  str_monster_name_70011101_en = "Abandonados: Diávola",
  str_monster_desc_70011101 = "A Diavola le gusta esconderse y eliminar sigilosamente a sus enemigos con veneno.",
  str_monster_ability_70011101 = "Diavola no puede moverse. Su cuerpo está envuelto en grandes y firmes hojas espinosas que reducen el daño que recibe.",
  str_monster_passiveskill_name_70011101 = "Hojas espinosas",
  str_monster_passiveskill_desc_70011101 = "Reduce el daño recibido en las 8 fichas exteriores de la Diavola en un 30%.",
  str_monster_passiveskill_name_70011102 = "Hojas espinosas",
  str_monster_passiveskill_desc_70011102 = "Reduce el daño recibido en las 8 casillas exteriores de Diavola en un 50%.",
  str_monster_name_2003801 = "Capitán de la pandilla",
  str_monster_desc_2003801 = "El peculiar líder de una pandilla, experto en armas de fuego. Su presencia solo significa problemas para Umbraton.",
  str_monster_ability_2003801 = "Attacks after moving away from the target, dealing damage 2 times. Can steal the target's attributes.",
  str_monster_passiveskill_name_2003801 = "Disparo Mortal",
  str_monster_passiveskill_desc_2003801 = "Roba el ATK básico y la DEF básica de los Aurorianos al infligir daño. El ATK y DEF robados serán devueltos después de 2 rondas o después de que esta unidad sea derrotada.",
  str_monster_name_2003701 = "Ballestero de pandilla",
  str_monster_desc_2003701 = "Precisas, seguras, discretas e increíblemente poderosas, las ballestas se han convertido en un arma muy apreciada entre los gángsters debido a estas propiedades inigualables. Los enemigos expertos en su uso suelen ser altamente peligrosos.",
  str_monster_ability_2003701 = "Puede atacar objetivos en forma de cruz hasta el máximo de su alcance. Después de golpear, reduce la curación recibida por el objetivo.",
  str_monster_passiveskill_name_2003701 = "Flecha sombreada",
  str_monster_passiveskill_desc_2003701 = "Después de golpear a un Aurorian, reduce en un 40% la curación que recibe. Este efecto no se acumula y se elimina cuando el Ballestero de la Pandilla es derrotado.",
  str_monster_name_2009001 = "Cañón Salva",
  str_monster_desc_2009001 = "Un Eclipsite que se asemeja a un cañón de arma. ¡Proporciona apoyo a sus compañeros y ataca fuertemente a tu equipo!",
  str_monster_ability_2009001 = "Ataca a los enemigos dentro del alcance de ataque. Si no hay objetivos disponibles, su ataque se potencia y cura al Rey Tritón.",
  str_monster_name_8003481 = "Dayna",
  str_monster_desc_8003481 = "A pesar de su corta edad, ya es líder de los Lanzas. Es conocida por establecer un firme punto de apoyo en las calles de Umbraton con su insuperable determinación y sus diabólicas y furtivas armas.",
  str_monster_ability_8003481 = "Ataca al enemigo más cercano.",
  str_monster_name_8003781 = "Robyn",
  str_monster_desc_8003781 = "Miembro de los Lanzas de Umbraton. Tímida e introvertida, se mantiene cerca de su hermana, Dayna, mientras intenta sobrevivir en Umbraton.",
  str_monster_ability_8003781 = "Sigue al jugador e inflige daño de área a los enemigos cercanos.",
  str_monster_ability_2300601 = "Los Lurkers pueden unirse a los Aurorianos dentro de 1 grupo circundante de sí mismos. Una vez unidos, infligen daño al Auroriano y reducen su ATK.",
  str_monster_name_2909101 = "Rebecca Pantano venenoso",
  str_monster_desc_2909101 = "Sus venas palpitan con veneno carmesí, listas para erradicar cualquier amenaza para su familia, incluyéndose a sí misma.",
  str_monster_ability_2909101 = "Permite que los ataques infligan el efecto Fusión, haciendo que los objetivos afectados pierdan HP al comienzo de sus rondas. Invoca Marcas de Veneno en las casillas circundantes en cada ronda, imponiendo Fusión a los enemigos cercanos que pasen por allí; las Marcas de Veneno se transforman en Casillas Oscuras al final de la ronda.",
  str_monster_name_2003901 = "Especialista en apoyo a pandillas",
  str_monster_desc_2003901 = "Un miembro de la pandilla corpulento de fuerza inmensa, hábil en el uso de sus brazos mecánicos para el combate. Además, puede ofrecer apoyo a otras fuerzas enemigas de Umbraton en el campo.",
  str_monster_ability_2003901 = "Proporciona aumentos de ATK y DEF a los miembros de Umbraton dentro de 1 cúmulo circundante; se cura a sí mismo cuando su PS cae por debajo de un cierto porcentaje.",
  str_monster_passiveskill_name_2003901 = "Soporte adicional",
  str_monster_passiveskill_desc_2003901 = "Proporciona aumentos de ATK y DEF a los miembros de Umbraton dentro de 1 grupo circundante.",
  str_monster_name_2004101 = "Asesino de pandillas",
  str_monster_desc_2004101 = "\"El mejor apuñalamiento es el que viene por detrás.\" Hábil en atacar puntos vitales, las hojas de esta unidad son mortales tanto en peleas callejeras como en el campo de batalla.",
  str_monster_ability_2004101 = "Lanza 2 golpes rápidos consecutivos contra el enemigo. Roba el ATQ básico y DEF de los Aurorianos al infligir daño. El ATQ y DEF robados se devolverán después de 2 rondas o después de que esta unidad sea derrotada. Se retira después de atacar para protegerse. Si el objetivo no puede ser atacado, ACT +1 en esta ronda.",
  str_monster_passiveskill_name_2909101 = "Corrosión Tóxica",
  str_monster_passiveskill_desc_2909101 = "Permite que los ataques infligan el efecto Fusión, haciendo que los objetivos afectados pierdan HP al comienzo de sus rondas. Invoca Marcas de Veneno en las casillas circundantes en cada ronda, imponiendo Fusión a los enemigos cercanos que pasen por allí; las Marcas de Veneno se transforman en Casillas Oscuras al final de la ronda.",
  str_monster_passiveskill_name_2004101 = "Fervor de batalla",
  str_monster_passiveskill_desc_2004101 = "Roba el ATQ básico y la DEF básica de los Aurorianos al infligir daño. El ATQ y DEF robados serán devueltos después de 2 rondas o después de que esta unidad sea derrotada.",
  str_monster_name_2909101_en = "Rebecca Pantano venenoso",
  str_monster_name_2003801_en = "Capitán de la pandilla",
  str_monster_name_70011071 = "Abandonado: Gatitopus",
  str_monster_name_70011071_en = "Abandonado: Gatitopus",
  str_monster_desc_70011071 = "Una compañera especial de Gretel. Se parece a un gato con muchas patas... Es lindo, pero algo inquietante.",
  str_monster_ability_70011071 = "Kittypus desata sus tentáculos e inflige un daño masivo a los aurorianos. ¡Recuerda: las tenazas de Kittypus transfieren todo el daño entrante a su anfitrión!",
  str_monster_name_70011081 = "Forsaken: Goldor Oscuro",
  str_monster_name_70011081_en = "Forsaken: Goldor Oscuro",
  str_monster_desc_70011081 = "Eclipsites Blindados de Noche Blanca, Vientre Negro.",
  str_monster_ability_70011081 = "Inmóvil pero puede atacar y derribar objetivos en un área grande.",
  str_monster_name_70011091 = "Abandonada: Diosa Denuo",
  str_monster_name_70011091_en = "Abandonada: Diosa Denuo",
  str_monster_desc_70011091 = "Una mariposa extremadamente rara. Es de naturaleza retraída, con sentidos muy agudos. No se debe subestimar su poder de combate.",
  str_monster_ability_70011091 = "Catalizan el crecimiento de las plantas mediante la polinización, protegiéndose a sí mismos mientras infligen un gran daño a los enemigos.",
  str_monster_ability_70011083 = "Presentando un nivel extremadamente bajo de peligro, huye inmediatamente de miedo después de que los aurorianos usen sus Habilidades Activas.",
  str_monster_name_2909201 = "Agujón: Coalescencia",
  str_monster_name_2909202 = "Cola del aguijón",
  str_monster_name_2909201_en = "Agujón: Coalescencia",
  str_monster_desc_2909201 = "Un arma peligrosa creada al combinar las características mortales de muchas creaciones mecánicas, incluida la tecnología de Astra. Las fuentes de energía ordinarias no pueden mantener en funcionamiento a esta gigantesca criatura.",
  str_monster_ability_2909201 = "Cada Bestia Mecánica que forma parte de su cuerpo tiene su propio ataque único. La cola puede acumular Energía para infligir daño garantizado a sus objetivos, pero también es relativamente frágil.",
  str_monster_passiveskill_name_290920101 = "Armadura inquebrantable",
  str_monster_passiveskill_desc_290920101 = "Obtiene un escudo equivalente a un porcentaje del HP máximo al comienzo de cada ronda. El escudo restante se convierte en HP al final de la ronda.",
  str_monster_passiveskill_name_290920102 = "Prevención de daños",
  str_monster_passiveskill_desc_290920102 = "La cola de Stinger solo puede ser dañada por habilidades de francotirador y es inmune a ataques normales y daño de área. Cuando su cola tiene cero HP restantes, Stinger queda paralizado por 1 ronda.",
  str_monster_name_2004001 = "Cangrejo forjado en horno",
  str_monster_desc_2004001 = "Esta creación de herramienta mecánica fue diseñada para ayudar a los artesanos a hacer inventos ingeniosos. Más tarde, fue modificada para que una variación de esta invención pudiera almacenar Fuerza de Llama en su vientre. Nunca se pretendió que se usara como un arma.",
  str_monster_ability_2004001 = "Se mueve de lado a lado como un cangrejo, balanceando sus pinzas, y puede escupir fuego.",
  str_monster_name_70011141 = "Abandonado: Rebecca Pantano de veneno",
  str_monster_name_70011141_en = "Abandonado: Rebecca Pantano de veneno",
  str_monster_name_70011151 = "Abandonado: Mudbundle",
  str_monster_name_70011151_en = "Abandonado: Mudbundle",
  str_monster_ability_2003411 = "Crea pantanos en las casillas por las que se mueve. Poseyendo una DEF extremadamente alta, se regenerará y mejorará después de ser devorado.",
  str_monster_name_2906201 = "Vilanor: Trampa Maldita",
  str_monster_name_2906201_en = "Vilanor: Trampa Maldita",
  str_monster_desc_2906201 = "Una espada hábilmente forjada nacida de la ingeniosidad del Reino Ye de Longzhou. Originalmente fue diseñada como un arma de autodefensa para aquellos que no sabían cómo defenderse con una espada, pero ahora se ha convertido en una maldita espada maligna después de caer en manos de villanos.",
  str_monster_ability_2906201 = "Después de convertirse en Vilanor, sus habilidades se mejoran enormemente, obteniendo el poder de moverse libremente por el campo y generar espadas a partir de la energía maligna.",
  str_monster_passiveskill_name_290620101 = "Rencor Profundo",
  str_monster_passiveskill_desc_290620101 = "Antes de moverse, Vilanor invoca hebras de Energía de Espada Vil en ubicaciones aleatorias basadas en la cantidad de daño que ha recibido en esta ronda. Cuanto más daño se recibe en esta ronda, más hebras de Energía de Espada Vil se invocan.",
  str_monster_name_2004301 = "Energía de Espada Vil",
  str_monster_desc_2004301 = "Esta energía de espada liberada por Vilanor asume una forma de espada después de alcanzar una cierta densidad.",
  str_monster_ability_2004301 = "La energía de la espada invocada por Vilanor no puede atacar ni moverse, pero ocupará la casilla en la que se encuentra, haciéndola intransitable.",
  str_monster_desc_1602191 = "Contendiente - Istvan",
  str_monster_ability_1602191 = "Después de moverse, lanza un Ataque Normal o Combo en Cadena, causando mucho daño a los Eclipsites.",
  str_monster_ability_1602192 = "Después de moverse, lanza un Ataque Normal o Combo en Cadena, infligiendo mucho daño a los Aurorianos.",
  str_monster_name_1600391 = "Istvan",
  str_monster_name_1600391_en = "ISTVAN",
  str_monster_name_70011191 = "Abandonado: Fujikumo Nobutora - Devorar",
  str_monster_name_70011191_en = "Abandonado: Fujikumo Nobutora - Devorar",
  str_monster_ability_70011191 = "Invoca una gran cantidad de fantasmas y desata diferentes habilidades poderosas basadas en la distancia entre los aurorianos y el enemigo en cada ronda.",
  str_monster_passiveskill_name_200440101 = "Contaminación Mecánica",
  str_monster_passiveskill_desc_200440101 = "Refleja el daño después de recibir daño de los Ataques Normales de los Aurorians.",
  str_monster_passiveskill_name_200460101 = "Reparación Mecánica",
  str_monster_passiveskill_desc_200460101 = "Recupera un cierto porcentaje de HP perdido al comienzo de cada ronda.",
  str_monster_name_2004401 = "Soldado Voidcross",
  str_monster_desc_2004401 = "Una arma de guerra creada a través de la fusión de Eclipsites y Aurorianos. Se han conservado las características de los Aurorianos tanto como fue posible, y la mecanización no es demasiado obvia, pero sigue siendo muy peligrosa.",
  str_monster_ability_2004401 = "Una forma de vida mecánica que ataca hackeando y cortando.",
  str_monster_name_2004501 = "Soldado Ululat",
  str_monster_desc_2004501 = "Una arma de guerra creada a través de la fusión de Eclipsites y Aurorianos. Está protegida por una gruesa capa de armadura mecánica, y su fuerza ha sido potenciada al máximo posible.",
  str_monster_ability_2004501 = "El poder y la defensa de esta forma de vida mecánica modificada han mejorado enormemente, y sobresale en atacar con explosiones y otros métodos similares.",
  str_monster_name_2004601 = "Super-Soldado Meaugm",
  str_monster_name_2004601_en = "Super-Soldado Meaugm",
  str_monster_desc_2004601 = "Una super arma creada a través de la fusión de Eclipsites y Aurorians. Ya no tiene características Aurorianas y ahora es una existencia completamente mecánica.",
  str_monster_ability_2004601 = "Esta forma de vida mecánica modificada puede usar su gruesa armadura como arma, lo que la hace muy difícil de manejar.",
  str_monster_name_2906401 = "Super-Soldado Blaugm",
  str_monster_name_2906401_en = "Super-Soldado Blaugm",
  str_monster_desc_2906401 = "Este súper soldado es un Eclipsite que ha sido equipado con dispositivos mecánicos por todo su cuerpo para hacerlo más resistente, más feroz y más intimidante.",
  str_monster_ability_2906401 = "Un intimidante súper soldado que sobresale en aplastar a los enemigos cercanos con sus ataques.",
  str_monster_passiveskill_name_290640101 = "Absorción Mecánica",
  str_monster_passiveskill_desc_290640101 = "Gana 1 acumulación de Armadura Mecánica al recibir un Ataque Normal. Cada acumulación reduce el Ataque Normal recibido en un 1%. El número de acumulaciones de este beneficio se reduce a la mitad al comienzo de la ronda.",
  str_monster_passiveskill_name_290640102 = "Defensa Mecánica",
  str_monster_passiveskill_desc_290640102 = "Reduce el daño recibido de los ataques frontales.",
  str_monster_passiveskill_name_290640103 = "Frenesí Mecánico",
  str_monster_passiveskill_desc_290640103 = "Aumenta el daño a medida que disminuye su propio HP.",
  str_monster_name_2906301 = "Ulysses Bio",
  str_monster_name_2906301_en = "Ulysses Bio",
  str_monster_desc_2906301 = "Ulysses modificó su cuerpo extensamente para realizar sus ideales extremos. Ya no es un Aurorian ahora.",
  str_monster_ability_2906301 = "Ulysses utiliza diferentes estrategias de ataque basadas en las habilidades de los Aurorianos.",
  str_monster_passiveskill_desc_8024441 = "Cuando un Murkmite golpea a un objetivo, reduce los puntos de fuerza del objetivo en 2.",
  str_monster_name_8024161 = "Voluntad Malvada: Sombra",
  str_monster_name_8024442 = "Voluntad Malvada: Murkmite",
  str_monster_name_80243111 = "Voluntad Malvada: Augean",
  str_monster_name_80243111_en = "Malvado Voluntad: Augean",
  str_monster_name_7001121 = "Abandonado: Rey Tritón",
  str_monster_ability_7001121 = "Los ataques infligen retroceso. Puede invocar Cañones Salvo en ubicaciones específicas en el campo de batalla.",
  str_monster_name_7001121_en = "Abandonado: Rey Tritón",
  str_monster_passiveskill_name_7001121 = "Despliegue de artillería salvo",
  str_monster_passiveskill_desc_7001121 = "Al comienzo de la ronda del jugador, si hay menos de 3 Salvo Guns en el campo de batalla, invoca 4 Salvo Guns.",
  str_monster_name_2004701 = "Diablillo: Rata",
  str_monster_desc_2004701 = "Pequeños diabólicos omnívoros con una cultivación insuficiente, mantienen una naturaleza salvaje. Siempre se cuelan en las viviendas de los aurorianos para robar comida. Algunos más agresivos incluso pueden causar daño.",
  str_monster_ability_2004701 = "Ágil y rápido, se mueve velozmente detrás del objetivo después de un ataque.",
  str_monster_passiveskill_name_2004701 = "Roer del Roedor",
  str_monster_passiveskill_desc_2004701 = "Ataca al Aurorian con la DEF más baja en el equipo al atacar, infligiendo daño.",
  str_monster_ability_5412041 = "Un Eclipsite con habilidades de invocación. Incapaz de moverse por sí mismo, lucha invocando a Gloom Ghouls que poseen habilidades de ataque a distancia. Los Gloom Ghouls sacrifican su propia HP para curar a Croweye al entrar en la batalla y transfieren el daño a Croweye cuando reciben daño.",
  str_monster_passiveskill_name_5412042 = "Simbiosis Sacrificial",
  str_monster_passiveskill_desc_5412042 = "Se sacrifica su propio PS para curar a Croweye al entrar en la batalla y transfiere el daño a Croweye cuando recibe daño.",
  str_monster_name_541100216 = "Chen'ni",
  str_monster_desc_541100216 = "¿El niño que apareció de repente de la nada parecía ser un fiundling peculiar con una apariencia como nosotros?",
  str_monster_ability_541100216 = "¡Sus habilidades son asombrosas!",
  str_monster_passiveskill_desc_541301215 = "Al comienzo de la ronda del jugador, si hay menos de 2 Salvo Guns en el campo de batalla, invoca 4 Salvo Guns.",
  str_monster_name_2909301 = "Fiundling: Nian",
  str_monster_name_2909301_en = "Fiundling: Nian",
  str_monster_desc_2909301 = "La leyenda cuenta que en la víspera del Festival de Primavera, un feroz demonio parecido a una bestia desciende sobre Longzhou, causando caos. Aquellos que logran expulsarlo son bendecidos con un año entero de paz y buena fortuna.",
  str_monster_ability_2909301 = "Nian destruirá todo a la vista a medida que se acerca al pueblo. Solo los Aurorianos que poseen Habilidades Activas poderosas pueden detenerlo.",
  str_monster_passiveskill_name_2909301 = "Bestia antigua formidable",
  str_monster_passiveskill_desc_2909301 = "¡La formidable presencia de Nian es aterradora! Los mosaicos dentro de 1 grupo circundante no pueden ser seleccionados como puntos de aterrizaje de los aurorianos.",
  str_monster_passiveskill_name_2909302 = "Atraviesa la Puerta",
  str_monster_passiveskill_desc_2909302 = "La bestia Nian destruirá la puerta y, al entrar, arrasará con todo, provocando el fracaso de la batalla.",
  str_monster_name_70011251 = "Abandonado: Cerritus",
  str_monster_name_70011251_en = "Abandonado: Cerritus",
  str_monster_desc_70011251 = "El nuevo Eclipsite encontrado durante la exploración parece ser una variante de un poderoso Eclipsite, excepto que está más trastornado y es mucho más destructivo.",
  str_monster_ability_70011251 = "Abandonado: Cerritus carga contra los aurorianos, invocando guijarros y generando continuamente baldosas debilitadas en el campo. También puede mejorar su propio ACT durante el combate.",
  str_monster_name_70011261 = "Abandonado: Chandra",
  str_monster_name_70011261_en = "Abandonado: Chandra",
  str_monster_desc_70011261 = "Una investigadora de Illumina optimista y alegre, tiene una habilidad especial para absorber las emociones negativas de otros y sanar sus traumas mentales.",
  str_monster_ability_70011261 = "Forsaken: Chandra puede lanzar ataques a los Aurorianos desde la distancia y aumentar continuamente el número de veces que su habilidad inflige daño.",
  str_monster_passiveskill_name_70011261 = "Abandonado: Reúna las emociones negativas",
  str_monster_passiveskill_desc_70011261 = "Con cada lanzamiento de Renegado: Proyecto de Emoción Negativa, la habilidad lanza 1 ataque más la próxima vez, infligiendo un aumento del daño total.",
  str_monster_passiveskill_name_80051412 = "Estrategia de Frente de Guerra",
  str_monster_passiveskill_desc_80051412 = "El Mensajero puede almacenar energía de batalla para motivar a los monstruos. Cuando hay más de 30 puntos de energía de batalla, proporciona un aumento permanente del 10% de ATK a todos los monstruos en el campo al final de cada ronda. Sin embargo, el Mensajero desencadenará una explosión de energía al morir, causando un daño masivo a todos los monstruos en el campo.",
  str_monster_passiveskill_name_80051413 = "Acceso a la energía",
  str_monster_passiveskill_desc_80051413 = "El Mensajero restaura automáticamente 10 acumulaciones de energía de batalla al inicio de cada ronda. Cuando el Auroriano libera una Habilidad Activa en el campo, reduce las acumulaciones de energía de batalla del Mensajero en 4. Además, el Mensajero pierde 1 acumulación de energía de batalla cuando es golpeado por el ataque normal del Auroriano.",
  str_monster_name_2909401 = "Ira",
  str_monster_name_2909401_en = "Ira",
  str_monster_desc_2909401 = "Un enigmático y formidable Wraith, recorriendo las tierras para entrenar. Su aliento exuda terror, presagiando la perdición para aquellos que incurran en su ira.",
  str_monster_ability_2909401 = "Capaz de invocar Fuego Sombra con Darkflow en batalla.\nNota: El Meteorito Darkflow de Ira, compuesto de llamas furiosas, puede matar instantáneamente a los Aurorianos dentro de su rango.",
  str_monster_name_2004801 = "Fuego sombra",
  str_monster_passiveskill_name_2004801 = "Cenizas de Fuego Sombra",
  str_monster_passiveskill_desc_2004801 = "Al ser eliminado, Shadowfire deja atrás Azulejos Oscuros en su ubicación.",
  str_monster_ability_5435071 = "Los ataques causan retroceso. Puede invocar cañones de salva en las casillas cercanas para autoprotección.",
  str_monster_ability_5435112 = "Refúgiate en un lugar seguro, sacrificando una porción de PS cada ronda para restaurar el PS de Philex.",
  str_monster_name_70011271 = "Abandonado: Caracalune",
  str_monster_name_70011271_en = "Abandonado: Caracalune",
  str_monster_name_70011281 = "Abandonado: Maude Solus",
  str_monster_name_70011281_en = "Abandonado: Maude Solus",
  str_monster_ability_70011271 = "Sobresale en el uso de ataques de área grande. Bloquea los elementos de los mosaicos a su alrededor después de que se mueve.",
  str_monster_name_70011321 = "Renegados: Araña Queen",
  str_monster_name_70011321_en = "Forsaken: Arachnid Queen",
  str_monster_ability_70011321 = "Al poseer fuertes habilidades reproductivas, teje telas de araña en un entorno de caza y convoca a un gran número de crías de araña para unirse a la batalla cada 3 rondas.",
  str_monster_name_70110011 = "Abandonado: Luto Eve",
  str_monster_name_70110011_en = "Abandonado: Luto Eve",
  str_monster_desc_70110011 = "El dolor del aislamiento y el miedo a ser cortado, esos recuerdos insoportables del pasado, han moldeado a la persona conocida como Eve hoy.",
  str_monster_ability_70110011 = "Cada ronda, invoca Dawn Flores en una ubicación fija en el campo de batalla, aumentando la DEF de acuerdo con el número de Dawn Flores.",
  str_monster_passiveskill_name_70110011 = "Duelo: Metamorfosis",
  str_monster_passiveskill_desc_70110011 = "Cada ronda, invoca Dawn Flores en una ubicación establecida para aumentar la DEF; cada Flor Dawn otorga un impulso extra de DEF.",
  str_monster_name_70110012 = "Dawn Flor",
  str_monster_desc_70110012 = "Estas sencillas flores blancas, pequeñas y ordinarias, se encuentran entre los más preciados consuelos de su corazón.",
  str_monster_ability_70110012 = "Otorga una bonificación DEF adicional para Grieving Eve.",
  str_monster_name_7001134 = "Abandonado: Bennuguardian",
  str_monster_name_7001134_en = "Abandonado:Bennuguardian",
  str_monster_ability_7001134 = "Posee un gran poder. Acumula Furia cuando es atacado. Cuando la Furia alcanza un cierto nivel, entra en un estado Enfurecido, reduciendo el daño recibido y lanzando habilidades adicionales poderosas.",
  str_monster_name_2004901 = "Bruma",
  str_monster_desc_2004901 = "Formado por la rápida acumulación de Darkflow alrededor de los Eclipsites muertos. ¡Ten cuidado! La ira y el resentimiento de los Eclipsites viven dentro de él.",
  str_monster_ability_2004901 = "Todo el daño que recibe se reduce a 1. No puede atacar pero seguirá moviéndose hacia los Aurorianos.",
  str_monster_passiveskill_name_2004901 = "Bruma enredadora",
  str_monster_passiveskill_desc_2004901 = "Todo el daño que recibe se reduce a 1. No puede atacar, pero seguirá moviéndose hacia los Aurorianos y desaparecerá si se le somete a efectos de desplazamiento. Desaparece normalmente después de 2 rondas.",
  str_monster_passiveskill_desc_2004902 = "Todo el daño que recibe se reduce a 1. No puede atacar pero seguirá moviéndose hacia los aurorianos y desaparece si se le somete a efectos de desplazamiento. Desaparece normalmente después de 3 rondas.",
  str_monster_name_2909501 = "Zanahoria: Plaga",
  str_monster_name_2909501_en = "Zanahoria: Plaga",
  str_monster_desc_2909501 = "Después de absorber demasiado resentimiento en un lugar oscuro y pudrirse, esta zanahoria se ha transformado en una criatura extraña que busca venganza después de obtener el poder de Darkflow.",
  str_monster_ability_2909501 = "Lanza zanahorias, causando múltiples instancias de daño. Cuando gira a alta velocidad, inflige múltiples instancias de daño a los enemigos en un área grande y los derriba.",
  str_monster_ability_2909502 = "Lanza zanahorias, causando múltiples instancias de daño. Cuando gira a alta velocidad, inflige múltiples instancias de daño a los enemigos en un área grande y los derriba. En situaciones de emergencia, puede encogerse y enterrarse en el suelo para continuar luchando desde allí.",
  str_monster_passiveskill_name_2909502 = "Plaga: Madriguera",
  str_monster_passiveskill_desc_2909502 = "Si es invencible cuando entra en acción, se vuelve más pequeño, se entierra bajo tierra y recupera su HP completo.",
  str_monster_ability_5455121 = "Puede usar ataques en forma de cruz o de pantalla completa, e invocar rayos.",
  str_monster_ability_4910302 = "Posee un alto ATK, y puede infligir un gran daño en forma radial al alcance máximo.",
  str_monster_ability_5455091 = "Kittypus agita sus tentáculos para infligir un daño masivo a los aurorianos.",
  str_monster_name_2909701 = "Magmita insaciable",
  str_monster_name_2909701_en = "Magmita insaciable",
  str_monster_desc_2909701 = "Un tipo aberrante de Eclipsite que utiliza tanto la lava como el Darkflow para causar daño.",
  str_monster_ability_2909701 = "Puede infligir daño en un área grande, así como invocar un escudo de magma para protegerse.",
  str_monster_passiveskill_name_2909701 = "Reflejo de lava",
  str_monster_passiveskill_desc_2909701 = "Mientras está protegido por su escudo fundido, refleja todos los ataques normales entrantes de los Aurorianos.",
  str_monster_name_80063701 = "Matón de la ciudad",
  str_monster_desc_80063701 = "Matones que han dominado el uso de la ballesta y saben cómo atacar con precisión, sigilosamente y lo más importante... de manera segura.",
  str_monster_ability_80063701 = "Puede atacar a objetivos en forma de cruz hasta el máximo de su alcance.",
  str_monster_name_80063801 = "Matón de élite de la ciudad",
  str_monster_desc_80063801 = "Se dice que son guerreros de élite hábiles con las armas de fuego y tienen una agilidad increíble.",
  str_monster_ability_80063801 = "Inflige daño dos veces después de usar su increíble agilidad para alejarse del objetivo.",
  str_monster_ability_2910242 = "Sobresale en el uso de ataques de gran área; los ataques de alcance ultra grande causan más daño a los objetivos más lejanos.",
  str_monster_ability_2920232 = "Vani puede usar Energía para atacar desde la distancia.",
  str_monster_passiveskill_name_20007011 = "Promoción",
  str_monster_passiveskill_desc_20007011 = "Al llegar al borde del Alchemy Board, serán promovidos a Torre Enfurecida, Caballero Caído, Alfil Eclipse o Queen Engañosa, según su orden de llegada.",
  str_monster_passiveskill_name_20007111 = "Promoción Élite",
  str_monster_passiveskill_desc_20007111 = "Al llegar al borde del Alchemy Board, serán promovidos a Torre Enfurecida - RAM, Caballero Caído - CHARGE, Alfil Eclipse - EX, o Queen Engañosa, según su orden de llegada.",
  str_monster_passiveskill_name_2910242 = "Nunca Te Rindas",
  str_monster_passiveskill_desc_2910242 = "Mad Horn se vuelve más fuerte cada vez que la barra de HP actual se reduce a cero.",
  str_monster_passiveskill_name_2010171 = "Cargando",
  str_monster_passiveskill_desc_2010171 = "Reduce en 1 el tiempo de reutilización de la habilidad del Capitán Auroriano cada vez que es eliminado.",
  str_monster_passiveskill_name_2914001 = "Fearless",
  str_monster_passiveskill_desc_2914001 = "Solo recibe 1 daño de los ataques.",
  str_monster_passiveskill_name_29140011 = "Escolta",
  str_monster_passiveskill_desc_29140011 = "Vani recupera HP igual al 200% del daño que Bennuguardian inflige.",
  str_monster_passiveskill_name_2920232 = "Tenacidad",
  str_monster_passiveskill_desc_2920232 = "Aumenta la DEF a medida que los HP disminuyen.",
  str_monster_passiveskill_name_2010715 = "Debilitamiento",
  str_monster_passiveskill_desc_2010715 = "Reduce la DEF de Queen Engañosa cada vez que muere un Eclipsite.",
  str_monster_passiveskill_name_20107152 = "Protección",
  str_monster_passiveskill_desc_20107152 = "Si la Queen Engañosa tiene Salvaguarda al tomar acción, otorga 3 acumulaciones de Salvaguarda a todos los demás Eclipsites.",
  str_monster_passiveskill_name_2910801 = "Nunca Te Rindas",
  str_monster_passiveskill_desc_2910801 = "El Monarca Desolado se vuelve más fuerte cada vez que su barra de HP se reduce a cero. Algunos Eclipsites Dormidos también serán despertados.",
  str_monster_passiveskill_name_29006411 = "Cierre",
  str_monster_passiveskill_desc_29006411 = "Contrarresta las Habilidades Activas de Aurorian, infligiendo daño a los Aurorianos y convocando Casillas Bloqueadas en las 4 casillas a su alrededor.",
  str_monster_passiveskill_name_29006611 = "Aplastar",
  str_monster_passiveskill_desc_29006611 = "Contrarresta las habilidades activas de Aurorian, invocando aleatoriamente fichas dañadas.",
  str_monster_name_1502001 = "Abandonado: Anatoli",
  str_monster_name_1502001_en = "anatoli",
  str_monster_desc_1502001 = "Un oficial de inteligencia tranquilo y confiable de la Federación Illumina que ocasionalmente presenta quejas inesperadas. Nadie sabe si estas denuncias se hacen de forma intencionada o no.",
  str_monster_ability_1502001 = "Arrastra a las unidades enemigas para controlar la situación de la batalla más fácilmente.",
  str_monster_name_1501761 = "Abandonado: Beretta",
  str_monster_name_1501761_en = "Beretta",
  str_monster_desc_1501761 = "Un médico de combate de Lumopolis fue salvado una vez por un médico llamado John. Desde entonces, ha tomado la decisión de convertirse en una buena doctora.",
  str_monster_ability_1501761 = "Usa hábilmente la Lanza Australis para infligir daño a los enemigos. Tiene la capacidad de contrarrestar las Habilidades Activas Aurorianas.",
  str_monster_passiveskill_name_1501761 = "Contrarresta Australis",
  str_monster_passiveskill_desc_1501761 = "Contrarresta las habilidades activas de Aurorian, otorgando 1 marca de Lanza Australis. Inflige daño 1 vez adicional al lanzar Tempestad Australis.",
  str_monster_name_70011291 = "Abandonado: Dragón Malvado Hakudoma",
  str_monster_name_70011291_en = "Abandonado: Dragón Malvado Hakudoma",
  str_monster_name_5471001 = "Reinhardt",
  str_monster_name_5471001_en = "Reinhardt",
  str_monster_desc_5471001 = "El verdadero Gran Mariscal de la Federación Illumina. No solo es valiente y habilidosa en el campo de batalla, también es una líder honesta y muy capaz respetada por todos los Illumina.",
  str_monster_ability_5471001 = "Posee un alto ATK y puede infligir un gran daño a los objetivos circundantes.",
  str_monster_desc_5471002 = "Un droide de combate modificado por la Federación Illumina. Calibrado según los atributos específicos de Reinhardt, posee algunas de sus habilidades.",
  str_monster_name_2909801 = "Punta de lanza: Aguijón de Rotbone",
  str_monster_name_2909801_en = "Punta de lanza: Aguijón de Rotbone",
  str_monster_desc_2909801 = "Una vez un Coloso de batalla que se lanzó de cabeza a la refriega en nombre del Eclipse, ahora es solo un montón de escombros destrozados, su última amenaza restante yace en su coxis.",
  str_monster_ability_2909801 = "Capaz de infligir daño a objetivos en un área grande y generar unidades periféricas que se mueven en formación de grupo para bloquear a los aurorianos.",
  str_monster_name_2005101 = "Provocante Periferia",
  str_monster_desc_2005101 = "Originalmente una parte de la cola de Spearhead, estas piezas se rompieron una por una y se esparcieron por las ruinas subterráneas.",
  str_monster_ability_2005101 = "Monstruos voladores controlados por una fuerza misteriosa, constantemente forman formaciones extrañas para lanzar ataques a corta distancia a los intrusos.",
  str_monster_name_70011421 = "Abandonado: Figerald",
  str_monster_name_70011421_en = "Abandonado: Figerald",
  str_monster_name_70011431 = "Abandonado: Ira",
  str_monster_name_70011431_en = "Abandonado: Ira",
  str_monster_passiveskill_name_2905201 = "Paso al vacío",
  str_monster_passiveskill_desc_2905201 = "Las fichas en las que se movieron los Aurorianos colapsarán en consecuencia. Los mosaicos no colapsarán en Aurora Time después de que los aurorianos se muevan sobre ellos. La Cordura disminuye en 30 cuando la escena colapsa.",
  str_monster_name_2910101 = "David Porfirio",
  str_monster_name_2910101_en = "David Porfirio",
  str_monster_desc_2910101 = "Jefe de la familia Porfirio. Es alguien a quien le gusta dominar a los demás y persigue incansablemente el poder por cualquier medio.",
  str_monster_ability_2910101 = "Utiliza diferentes habilidades contra los aurorianos basadas en la Cordura: Invoca Necroservidores o ataca para curarse a sí mismo.",
  str_monster_passiveskill_name_29101011 = "Locura",
  str_monster_passiveskill_desc_29101011 = "A medida que la cordura disminuye, David Porfirio se vuelve más frenético, con menor DEF pero mayor ATK.",
  str_monster_passiveskill_name_29101012 = "Disuasión del Miedo",
  str_monster_passiveskill_desc_29101012 = "Solo toma el 10% del primer daño de cada Aurorian en cada ronda.",
  str_monster_name_2005201 = "Sirviente Necro",
  str_monster_desc_2005201 = "Almas partidas miserables, eternamente engañadas y confinadas. Ahora vagan, buscando sangre fresca y cálida para su maestro.",
  str_monster_ability_2005201 = "Causa diferentes efectos de daño a los Aurorianos basados en la Cordura: Drena la Cordura o consume HP.",
  str_monster_name_2910001 = "Syurton",
  str_monster_desc_2910001 = "Un enorme y tenaz vanguardia de asedio. Incluso con extremidades desviadas, puede devastar estructuras terrestres.",
  str_monster_ability_2910001 = "Puede atacar a los Aurorianos con varias partes del cuerpo. Dañar cualquier parte de Syurton le hará daño.",
  str_monster_name_2910001_en = "Syurton",
  str_monster_passiveskill_name_2910001 = "Rechazador de sol",
  str_monster_passiveskill_desc_2910001 = "La cola de Syurton es inmune a ataques normales y daño de área.",
  str_monster_name_2909901 = "Stone Giant of the Ruins",
  str_monster_name_2909901_en = "Gigante de Piedra de las Ruinas",
  str_monster_desc_2909901 = "In the eyes of future Aurorians, extraordinary advanced technology may be seen as equivalent to magic, and in Fleur's eyes, the stone giant is akin to a mecha.",
  str_monster_ability_2909901 = "Posee poderosas habilidades curativas.",
  str_monster_passiveskill_name_2909901 = "Nulo Activo",
  str_monster_passiveskill_desc_2909901 = "Después de cada 3 lanzamientos de Habilidad Activa de Aurorian, el Gigante de Piedra de las Ruinas contraataca, haciendo que el próximo lanzamiento de Habilidad Activa sea ineficaz. Esto no afecta al Sistema Táctico.",
  str_monster_name_70011451 = "Forsaken Invocador Oscuro",
  str_monster_name_70011451_en = "Forsaken Invocador Oscuro",
  str_monster_name_70011461 = "Gigante de Piedra Abandonado de las Ruinas",
  str_monster_name_70011461_en = "Gigante de Piedra Abandonado de las Ruinas",
  str_monster_name_700201901 = "Abandonado Regina",
  str_monster_name_700201901_en = "Gigante de Piedra Abandonado de las Ruinas",
  str_monster_desc_700201901 = "Su naturaleza audaz y desinhibida, así como su impulsividad, son las marcas de una verdadera ¡alma rockera! Su feroz estilo musical la hizo muy popular dentro de Rediesel Wrench, permitiéndole no sólo inspirar a las tropas, sino también liderarlas al frente.",
  str_monster_ability_700201901 = "No puede moverse, pero es excelente para infligir daño de gran área y derribar a los enemigos.",
  str_monster_ability_70011451 = "Invoca faros y obtiene una reducción de daño basada en el número de faros a su alrededor. Sus habilidades tienen un ataque a distancia en forma de cruz y el daño y el alcance de su habilidad cargable se basan en el número de faros.",
  str_monster_name_2910201 = "Stellandine: Prototipo",
  str_monster_name_2910201_en = "Stellandine : Prototipo",
  str_monster_desc_2910201 = "Envuelto en disfraz, canta y llora para atraer a su presa. Una vez que se deshace del disfraz, derrota a sus enemigos con violencia y veneno. Todo el tiempo, no logra entender que el amor es suprimir la propia naturaleza.",
  str_monster_ability_2910201 = "Invoca un gran número de Eclipsites de apoyo, representando una amenaza para las unidades enemigas a su alrededor.",
  str_monster_passiveskill_name_2910201 = "Susurros de las profundidades del mar",
  str_monster_passiveskill_desc_2910201 = "Al inicio de cada ronda, se inflige daño a los aurorianos dentro de 1 grupo circundante basado en su porcentaje actual de HP.",
  str_monster_name_2005301 = "Cañón Salva",
  str_monster_desc_2005301 = "Está aprendiendo sobre los Aurorianos pero tiene dificultades para entender cuándo disparar el saludo con la pistola. Todo lo que quiere es susurrar tiernamente, pero termina convirtiéndose en un veneno de mar profundo que corroe a todos los que se acercan.",
  str_monster_ability_2005301 = "Representa una amenaza para las unidades enemigas a su alrededor.",
  str_monster_name_2005401 = "Demanda",
  str_monster_desc_2005401 = "Hambriento de contacto físico y amor, se acerca constantemente a los aurorianos. Temeroso de salir herido y ser odiado, prefiere atacar primero.",
  str_monster_ability_2005401 = "Cuando se percibe una amenaza, se invocan Eclipsites para asistencia.",
  str_monster_name_70020211 = "Abandonado : Stellandine",
  str_monster_name_70020211_en = "Abandonado : Stellandine",
  str_monster_name_39002111 = "Forsaken: Umbrahulk",
  str_monster_name_39002111_en = "Los Desamparados: Umbrahulk",
  str_monster_ability_39002111 = "Su ataque cuerpo a cuerpo viene con un retroceso, y tiene la capacidad de convocar Piedritas para atacar. Los objetivos impactados serán retrocedidos. También puede lanzar un ataque a pantalla completa, y el daño infligido está determinado por la cantidad de Piedritas.",
  str_monster_name_2910301 = "Nepolis",
  str_monster_name_2910301_en = "Neápolis",
  str_monster_desc_2910301 = "La lirio negro del Espejo de Geminos—hermana amada de Nikinis, la fusión de poder espiritual con la magia del Espejo de Northland, poderosa pero elegante.",
  str_monster_ability_2910301 = "Nepolis destaca en usar espejos para superar a los enemigos, evitando daño mientras entrega golpes mortales y maldice a los Aurorians usando criaturas de espejo.",
  str_monster_passiveskill_name_2910301 = "Espejo Maldito",
  str_monster_passiveskill_desc_2910301 = "Cada 3 rondas, Nepolis invoca 1 criatura espejo que se autodestruye después de 2 rondas, maldiciendo a un Auroriano al azar.",
  str_monster_desc_1 = "Una Eclipsite salvaje de bajo nivel y el monstruo cuerpo a cuerpo de agua más común.",
